/* ============================================================================
 * THE BEHEADED - SHOLTAN JOURNALS (Foundry v14, PF2e 8.4.x)
 * Rebuilt from the current module and handouts, 28 October 2026.
 *
 * HOW TO RUN
 *   GM only. Macro Directory > Create Macro > Type: Script. Paste, save, click.
 *
 * WHAT IT CREATES, in the journal folder "The Beheaded"
 *   12 GM entries across 89 pages, owner only, one per Part of the
 *   module ("Running This Module", "Part One: The Waking" and so on).
 *   "Sholtan: What You Know": 7 shared pages every player can read, plus
 *   6 private pages, one per character.
 *
 *   Sections that are word-for-word the same in all six handouts are shared.
 *   Sections that differ go on each character's private page (currently:
 *   Where You Are), so nobody reads another character's version.
 *
 * RE-RUNNING
 *   With REBUILD = false, entries that already exist by name are skipped. To
 *   pick up changed text, set REBUILD = true for one run: it deletes and
 *   recreates every entry this macro owns. Anything you hand-edited inside
 *   those entries is lost, so copy it out first.
 *
 * PRIVATE PAGES
 *   Matched to a player by an owned actor with the character's name, then the
 *   user's assigned character, then the user name. Unmatched pages stay
 *   GM-only and are listed in the notification. Fill NAME_TO_USER to be explicit.
 * ========================================================================= */

// Optional: "Character name": "Foundry user name"
const NAME_TO_USER = {
  // "Zacchaeus Bael": "Matt",
};

const FOLDER = "The Beheaded";
const PLAYER_JOURNAL = "Sholtan: What You Know";
const REBUILD = false;   // true = delete and recreate every entry this macro owns

if (!game.user.isGM) return ui.notifications.error("Run this as a GM.");
const OWN = CONST.DOCUMENT_OWNERSHIP_LEVELS;
const DM = [{"name":"Running This Module","pages":[{"name":"Running This Module","html":"<p>This is a structure, not a script. The party wakes in Sanguilum after the better part of half a year and has to decide what to do next. It covers the city, the rail network that runs out of it, the towns at the other end of that network, and every person worth naming along the way. Where the party goes, and what the order wants from them, is left open.</p>\n<p><strong>The one rule that governs everything here.</strong> Every Beheaded NPC in this module is competent, courteous, and genuinely glad the party is here. None of them are performing it. The party spent the campaign meeting this order at its worst and most compromised, and Sholtan is where they meet it working as intended. Let them wait for the other shoe. Do not drop it. Friction comes from doctrine, grief, and honest disagreement, never from a mask slipping.</p>\n<p><strong>Structure.</strong> Part One is the waking and what the party already knows. Part Two is Sanguilum, which is now home base rather than a destination. Part Three is the rail line outward. Parts Four through Eight are the places that line reaches. Appendix A holds every statblock, Appendix B holds prices.</p>\n<p><strong>Boxed text</strong> is written to be read aloud or paraphrased. Everything else is for you.</p>\n<blockquote>\n<p><strong>A note on what this document does not contain.</strong> What the spell was, what it did to the land, what has happened with the cowl, and what the world looks like now are all deliberately absent. This module is written to sit <em>underneath</em> those events rather than define them.</p>\n</blockquote>"},{"name":"Running This Module: The Travelling Party","html":"<table>\n<thead>\n<tr>\n<th><strong>Traveller</strong></th>\n<th><strong>In one line</strong></th>\n<th><strong>Doctrinal exposure</strong></th>\n<th><strong>Who they’ll gravitate toward</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Zacchaeus Bael</strong>, 27</td>\n<td>Human (Aiuvarin) Investigator, Medical Corps Proctor, raised in Sanguilum. The party’s primary healer, entirely without magic. Cannot himself be healed by magic.</td>\n<td>None. He is the order.</td>\n<td>Director Solenne; his father</td>\n</tr>\n<tr>\n<td><strong>Fern</strong></td>\n<td>Ancient elf caster, haughty and brilliant, ten thousand years removed from everyone she knew. Significantly altered by the event. Formerly a devoted worshipper of Desna.</td>\n<td>Practising caster</td>\n<td>Director Casiveth Null</td>\n</tr>\n<tr>\n<td><strong>Elemir</strong>, 87</td>\n<td>Nagaji Monk. Stoic, economical, settles things with his hands rather than talking them out.</td>\n<td>Magical tattoos in ghost ink, invisible unless heated. Presents as unmarked</td>\n<td>Knight Lieutenant Torvis Amsel</td>\n</tr>\n<tr>\n<td><strong>Pipsy Morningstone</strong></td>\n<td>Halfling Druid. Kind, sharp-tongued, fierce about nature and altered creatures. Has come out of this a mama bear, still dangerous, now a genuine backbone.</td>\n<td>Fey by ancestry (not held against her) <strong>and</strong> a practising trained druid (which is)</td>\n<td>Director Sable Ironmark</td>\n</tr>\n<tr>\n<td><strong>Gobbler</strong>, 22</td>\n<td>Goblin Ranger. Quiet, watchful, a real hunting talent. Travels with Kitty, a bear. Donkey, his goat, ascended.</td>\n<td>Devotee of Teki Stronggut, though he rarely mentions it</td>\n<td>Knight Paladin Sera Dunmore</td>\n</tr>\n<tr>\n<td><strong>“Flips” Niko</strong>, 23</td>\n<td>Tanuki Swashbuckler, ex-circus. Dancer first, fighter second. Searching for other tanuki. Significantly altered by the event.</td>\n<td>Shapeshifter. Declared it, and nobody has an issue with it</td>\n<td>Instructor Callo Verrienne; the Grand Archive</td>\n</tr>\n<tr>\n<td><strong>Hekete “Hek”</strong></td>\n<td>Nagaji Champion. Few words, enormous protective instinct. <strong>Is now Keh.</strong> Not present. Whether he can change back is unknown.</td>\n<td>—</td>\n<td>See <em>What Happened to Hek</em>, Part One</td>\n</tr>\n</tbody>\n</table>"},{"name":"Running This Module: NPC Quick Reference","html":"<p>Every named NPC in this module, with the one thing that makes them sound like themselves. Full detail in their section; full statblocks in Appendix A.</p>\n<table>\n<thead>\n<tr>\n<th><strong>NPC</strong></th>\n<th><strong>Where</strong></th>\n<th><strong>The hook</strong></th>\n<th><strong>How they talk</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Director Phaedra Solenne</strong></td>\n<td>Sanguilum</td>\n<td>Medical Corps head. Impossible to impress</td>\n<td>Dry, clipped, devastating with one word of praise</td>\n</tr>\n<tr>\n<td><strong>Chair Nathaniel Bael</strong></td>\n<td>Sanguilum</td>\n<td>Bael’s adoptive father. Dwarf. Field surgery legend</td>\n<td>Warm, wry, rambling. Deflects praise badly.</td>\n</tr>\n<tr>\n<td><strong>Director Casiveth Null</strong></td>\n<td>Sanguilum</td>\n<td>Fetchling. Extraplanar and dead-language scholar</td>\n<td>Precise and formal, quietly thrilled underneath</td>\n</tr>\n<tr>\n<td><strong>Associate Wren Callowick</strong></td>\n<td>Sanguilum</td>\n<td>First-year Associate, walked months to get here</td>\n<td>Breathless. Too many questions. Apologizes for them.</td>\n</tr>\n<tr>\n<td><strong>Archivist Sesh Nemeth</strong></td>\n<td>Sanguilum</td>\n<td>Anadi. Runs the Archive reading floor</td>\n<td>Warm, unhurried. Answers the question you meant</td>\n</tr>\n<tr>\n<td><strong>Cultivator Oleander</strong></td>\n<td>Sanguilum</td>\n<td>Ghoran. A plant employed to tend plants</td>\n<td>Slow, dry. One joke per conversation, well enjoyed</td>\n</tr>\n<tr>\n<td><strong>Knight Lieutenant Torvis Amsel</strong></td>\n<td>Sanguilum</td>\n<td>Nagaji unarmed instructor. Elemir’s match</td>\n<td>Almost silent. Communicates by demonstrating.</td>\n</tr>\n<tr>\n<td><strong>Instructor Callo Verrienne</strong></td>\n<td>Sanguilum</td>\n<td>Halfling dance instructor, Arts Corps</td>\n<td>Delighted, fast, physically demonstrative</td>\n</tr>\n<tr>\n<td><strong>Director Sable Ironmark</strong></td>\n<td>Sanguilum</td>\n<td>Leshy Director, Natural Corps</td>\n<td>Curious, blunt, no social anxiety whatsoever</td>\n</tr>\n<tr>\n<td><strong>Knight Paladin Sera Dunmore</strong></td>\n<td>Sanguilum</td>\n<td>Dromaar monster hunter, youngest Paladin in memory</td>\n<td>Economical, generous, plans three moves ahead</td>\n</tr>\n<tr>\n<td><strong>Sub-Envoy Ketal Ashvane</strong></td>\n<td>Sanguilum</td>\n<td>Strix. Shaadu liaison, Attested 22 years, eleven renewals</td>\n<td>Dry, unflappable, never quite answers</td>\n</tr>\n<tr>\n<td><strong>Works-Master Obed Tannhauser</strong></td>\n<td>Sanguilum, strait</td>\n<td>Goblin. Shaadu engineer, thinks the order over-builds</td>\n<td>Blunt, delighted to be allowed to say so</td>\n</tr>\n<tr>\n<td><strong>Factor Suleima Vosk</strong></td>\n<td>Sanguilum</td>\n<td>Azarketi. Adamantine interests, bought her own house</td>\n<td>Sharp, cheerful, entirely transactional</td>\n</tr>\n<tr>\n<td><strong>Broker Anselm Krait</strong></td>\n<td>Sanguilum</td>\n<td>Terrinbar dwarf. Immaculate papers, too many manifests</td>\n<td>Courteous, helpful, never once careless</td>\n</tr>\n<tr>\n<td><strong>Factor Deshi Nyoro</strong></td>\n<td>Sanguilum</td>\n<td>Human. Portovel sea freight. The outside opinion</td>\n<td>Talkative, generous, affectionately baffled</td>\n</tr>\n<tr>\n<td><strong>Mistress Ilva Corrant</strong></td>\n<td>Sanguilum</td>\n<td>Terrinbar gnome. Insures the fleet nobody else would</td>\n<td>Precise, dry, keeps the real numbers</td>\n</tr>\n<tr>\n<td><strong>Innkeeper Hessa Varr</strong></td>\n<td>Ottojikk</td>\n<td>Runs the Wayhouse. Has told this story 400 times</td>\n<td>Brisk, theatrical, delighted by her own material</td>\n</tr>\n<tr>\n<td><strong>Doorwarden Ilsabet Kroy</strong></td>\n<td>Ottojikk</td>\n<td>Elf arcanist who maintains the door-circles</td>\n<td>Dry, precise. Explains magic like an engineer</td>\n</tr>\n<tr>\n<td><strong>Proctor Liaison Corbin Ashe</strong></td>\n<td>Ottojikk</td>\n<td>The order’s man in a town built on magic</td>\n<td>Measured, diplomatic, chooses words carefully</td>\n</tr>\n<tr>\n<td><strong>Factor Bellamy Orr</strong></td>\n<td>Ottojikk</td>\n<td>Ratfolk. Represents three merchant houses at once</td>\n<td>Fast, friendly, always angling toward a sale</td>\n</tr>\n<tr>\n<td><strong>Fellow Orderly Mattias Crowe</strong></td>\n<td>Ottojikk</td>\n<td>Ran the ward that kept the party alive for a month</td>\n<td>Nervous, earnest, still can’t believe it worked</td>\n</tr>\n<tr>\n<td><strong>Tidewarden Ashek-Vel</strong></td>\n<td>Portovel Arterium</td>\n<td>Azarketi. Inspects hulls by swimming under them</td>\n<td>Blunt without malice. Shortest true thing, then stops</td>\n</tr>\n<tr>\n<td><strong>Proctor Ordnancer Hadria Volk</strong></td>\n<td>Portovel Arterium</td>\n<td>Dwarf. Runs the gun shop and the yard’s design arguments</td>\n<td>Loud, direct, delighted by her own work</td>\n</tr>\n<tr>\n<td><strong>Harbormaster Ondrei Kolt</strong></td>\n<td>Portovel Arterium</td>\n<td>Tengu. Runs the docks, exasperated by everyone</td>\n<td>Fast, clipped, never stops walking</td>\n</tr>\n<tr>\n<td><strong>Knight Ilyana Marsh</strong></td>\n<td>Portovel Arterium</td>\n<td>Customs. Easygoing manner, misses nothing</td>\n<td>Warm and chatty. Hard questions as small talk.</td>\n</tr>\n<tr>\n<td><strong>Associate Chirurgeon Perpetua Vance</strong></td>\n<td>Portovel Arterium</td>\n<td>Clinic and schoolhouse both. Delivered half the town</td>\n<td>Unhurried, motherly, bossy. Calls everyone “love.”</td>\n</tr>\n<tr>\n<td><strong>“Old Rill” Kestrel</strong></td>\n<td>Portovel Arterium</td>\n<td>Minotaur barkeep, retired sailor, rumor mill</td>\n<td>Booming, digressive, three stories deep first</td>\n</tr>\n<tr>\n<td><strong>Proctor Cultivator Ysolde Penn</strong></td>\n<td>Cordevale</td>\n<td>Soil genius who has twice refused Senior Proctor</td>\n<td>Quiet, practical, talks with her hands in the dirt</td>\n</tr>\n<tr>\n<td><strong>Proctor Cultivator Tamarisk</strong></td>\n<td>Cordevale</td>\n<td>Ghoran. Remembers the valley’s soil personally</td>\n<td>Unhurried. Measures conversations in seasons</td>\n</tr>\n<tr>\n<td><strong>Proctor Machinist Odalie Krenn</strong></td>\n<td>Cordevale</td>\n<td>Gnome. Trying to make herself unnecessary</td>\n<td>Blunt, cheerful, covered in grease</td>\n</tr>\n<tr>\n<td><strong>Ostrid Vale</strong></td>\n<td>Cordevale</td>\n<td>Learned everything the order had, now runs it herself</td>\n<td>Dry, direct, explains things once</td>\n</tr>\n<tr>\n<td><strong>Knight Captain Maribel Kosk</strong></td>\n<td>Cordevale</td>\n<td>Orc. Guards the grain and the people. Fights fire, not monsters</td>\n<td>Practical, warm, unimpressed by anything</td>\n</tr>\n<tr>\n<td><strong>Proctor Clerk Aurel Nim</strong></td>\n<td>Cordevale</td>\n<td>Civil Corps. Weighs and records every ton that leaves</td>\n<td>Precise, friendly, apologetic about paperwork</td>\n</tr>\n<tr>\n<td><strong>Proctor Warden Sesk Tallow</strong></td>\n<td>Cordevale</td>\n<td>Kholo. Draft teams, herding dogs, ratting dogs</td>\n<td>Few words, slow. Better with dogs than people</td>\n</tr>\n<tr>\n<td><strong>Bram Aldous</strong></td>\n<td>Cordevale</td>\n<td>Dwarf orchard elder, unofficial mayor</td>\n<td>Slow, fond, same story every time</td>\n</tr>\n<tr>\n<td><strong>Sentinel Darro Ashfen</strong></td>\n<td>Vigilsylva</td>\n<td>Lizardfolk sentinel. The one figure all three parties listen to</td>\n<td>Very few words. Long pauses. Never small talk.</td>\n</tr>\n<tr>\n<td><strong>Associate Chirurgeon Vashti Rell</strong></td>\n<td>Vigilsylva</td>\n<td>Nagaji. Runs the fever wards. Has named four diseases</td>\n<td>Direct, tired, very hard to alarm</td>\n</tr>\n<tr>\n<td><strong>Captain Verel Ashcombe</strong></td>\n<td>Vigilsylva</td>\n<td>Imperial commander. Competent, constrained, not a villain</td>\n<td>Clipped and formal. Thaws around competence</td>\n</tr>\n<tr>\n<td><strong>Yeleth Vaar</strong></td>\n<td>Vigilsylva</td>\n<td>Anadi Wall-Speaker. Two-thirds of the wall is hers</td>\n<td>Warm, blunt, unimpressed by hierarchy</td>\n</tr>\n<tr>\n<td><strong>Coen Vask</strong></td>\n<td>Vigilsylva</td>\n<td>Guide who takes patrols past the treeline for free</td>\n<td>Flat, dry, direct. Answers exactly what was asked.</td>\n</tr>\n<tr>\n<td><strong>Overseer Bruun Stonewell</strong></td>\n<td>Venoqual</td>\n<td>Dwarf running the world’s largest noqual mine</td>\n<td>Proud, loud, safety-obsessed. Quotes his record.</td>\n</tr>\n<tr>\n<td><strong>Knight Lieutenant Perrin Adair</strong></td>\n<td>Venoqual</td>\n<td>Hobgoblin. The checkpoint. Procedure as devotion</td>\n<td>Formal, precise, polite. Never hurries.</td>\n</tr>\n</tbody>\n</table>"}]},{"name":"Part One: The Waking","pages":[{"name":"Overview","html":"<h3>What Actually Happened</h3>\n<p>Set this out plainly at the table, because the party lived through the front half of it and slept through the rest.</p>\n<p><strong>The event.</strong> Hek did what Hek did, and became <strong>Keh</strong>. Everyone else went down.</p>\n<p><strong>What moved them.</strong> When Keh cast <em>tear the veil</em>, a messenger of Desna came through in the moment after and found <strong>Donkey</strong> the only one of the party still standing, battered and bloodied and refusing to let anyone face it without him. It entered him. Both of them understood his mortal body would not hold it for more than moments, and he took it anyway. Donkey gathered the whole party and carried them through the void that opened in front of him, a shooting star across the sky, and set them down in a heap at an inn in Xandar, one of the inns around the world that keep a door-circle, each under its own owner. The effort spent him. A man at that inn, the innkeeper as far as anyone can tell, carried the party into the door-circle room and shut the door on them, and they came out the other side at the Wayhouse in <strong>Ottojikk</strong>, a town they had all been to before. Donkey stayed on the far side of that door, beside the man. Why the man did it, and whether he understood what he was looking at, nobody knows.</p>\n<p><strong>He did not die of it. He ascended.</strong> Gobbler had already made him a god through the Grog of Substantial Whimsy, and the Grog rewrote what happened to match. What Donkey became is native to the material plane rather than an arrival from anywhere else. He is no longer the messenger; he kept the power as his own. It was forced on him through his wish to save his friends, without his knowing what it would do, and none of that is his fault.</p>\n<p><strong>Ottojikk.</strong> Six unconscious people came through the arrival door off the schedule, and none of them woke up. Someone at the Wayhouse recognized Bael’s order for what it was and went and found Beheaded.</p>\n<p><strong>The first month.</strong> Local Beheaded took them in and nursed six unconscious strangers for roughly a month. They did <strong>not</strong> immediately move them south, and the reason matters: transporting comatose patients, two of whom are deeply magical people, across a landscape saturated with noqual was judged too risky until they had stabilized. So the party spent their first month on this continent in a small ward in a trade town, being kept alive by people who had no idea who they were.</p>\n<p><strong>The next four months.</strong> Once stable, they were moved to Sanguilum and treated in the Sanctum Medica. Roughly five months unconscious in total.</p>\n<p><strong>Now.</strong> They have been awake for a matter of weeks, long enough to walk, to train, and to begin to understand a world that changed while they were under. Some of them have come out of it fundamentally altered: Fern and Flips most obviously, Pipsy in a quieter but no less real way. Everyone has had time to relearn their own body.</p>\n<blockquote>\n<p><strong>Timeline dial.</strong> Roughly five months unconscious, roughly three to six weeks awake. The awake period is the adjustable figure: stretching it gives more room for how substantially several of the party have changed.</p>\n</blockquote>\n<h3>What Happened to Hek</h3>\n<p><strong>Hek is not dead, and Hek is not exactly Hek.</strong> He became <strong>Keh</strong>, and the party watched it happen. What is not known, by them or by anyone in Sanguilum, is whether that is reversible, temporary, or permanent. Nobody has the expertise to answer it, including the order.</p>\n<p>He was not among the six who came through the door in Ottojikk. No one on this continent has any record of him arriving.</p>\n<p><strong>The party does not have all of that, and two of them hold pieces.</strong> Flips made the save and stayed conscious. Desna spoke to her directly, said it was the last time she would be able to save them, and asked her to tell Fern she will always be welcomed. Gobbler came round for a moment at the inn in Xandar, afraid, as the man was carrying them into the door room, and saw Donkey standing beyond the door beside him. Donkey lowered his head, glowed, and faded as it closed. Gobbler has not stopped feeling him since. Whether either of them has said any of this out loud is a table question rather than a settled one.</p>\n<p>Everyone else has nothing but the absence. The obvious guess is Keh, and the party has probably made it out loud already. It is the wrong guess. Ottojikk can tell them which door they came through and nothing about what happened before it.</p>\n<blockquote>\n<p><strong>What the order knows: nothing.</strong> Sanguilum has no account of this and no way to get one. Do not let a Beheaded NPC supply it. If the party works it out, they work it out from Flips, from Gobbler, and from Donkey's absence.</p>\n</blockquote>\n<p><strong>Nor is it established what Keh actually is now.</strong> The party watched Hek become something. Whether that something is a demigod, an avatar, a vessel, or a category nobody has a word for is not known, and nobody in Sanguilum can tell them. The order’s scholars are the best in the world at documenting this sort of thing and they still need a subject to document. Resist letting any NPC put a confident label on it.</p>\n<p>Whether Keh can come back, and what Keh is, should stay genuinely open at the table. The order will not resolve either.</p>\n<p>For Elemir specifically, this is not a grief plot; it’s an <em>unresolved</em> one, which is worse in a more interesting way. He knew Hek from birth, and the person he knew is now something he has no name for. He does not get to bury him and he does not get to find him.</p>\n<p><strong>Be careful how much the order can actually promise here.</strong> Nobody will tell Elemir no. The Scholarly Corps keeps records, the Faith Militant tracks things for a living, and Sera Dunmore in particular hunts what doesn’t want to be found. All of that is real, and all of it is <em>local</em>. The order’s reach effectively ends at the southern triangle. In Xandar it has almost nothing left, its chain of command there collapsed, its people there are scattered or compromised, and everything it learns about that continent arrives second-hand, weeks late, on a ship into Portovel Arterium.</p>\n<p>So the honest answer Elemir gets is a generous one and a limited one at the same time: <em>we will help you look, and we will not charge you for it, and if he is on this continent we will find him. If he is not, we can offer you what comes off the docks and very little else.</em> Nobody in Sanguilum will pretend otherwise, because pretending otherwise is not how these people operate.</p>\n<p>It is also not established that Keh is in Xandar, or anywhere the party could reach. That is one more open question rather than a destination.</p>\n<h3>Where They Stand Now</h3>\n<p><strong>They are welcome.</strong> This is important and should be played without irony. Sholtan is far enough from Xandar that what has happened there has not curdled the people here against outsiders. The party is not viewed with suspicion, and the order has both sheltered them and offered them real guidance for months. Whatever they carried in has had half a year of ordinary decency worn against it.</p>\n<p><strong>They are not strangers.</strong> Weeks awake in Sanguilum means they know how to get to the market, which bells mean what, and roughly who to ask about what. The city should feel <em>familiar</em>, not overwhelming. That’s a different register from a first-contact scene and worth playing deliberately.</p>\n<p><strong>Bael woke up with his father at the bedside.</strong> If Zacchaeus Bael lay unconscious in Sanguilum’s own hospital for four months, Chair Nathaniel Bael was there for it. That reunion has already happened, quietly, off-screen, and does not need replaying. What hasn’t happened is the party meeting him.</p>\n<p><strong>The rules were explained weeks ago.</strong> No gate scene, no confiscation, no declaration at a wall. A Civil Corps officer sat with each of them individually during recovery, in a chair, unhurried, with tea, and went through the guest rules properly. See <em>What They Were Told</em>. They know. Nobody can plead ignorance later.</p>\n<p><strong>They are done sitting still.</strong> Nothing is getting better. Nobody is telling them to wait, but nobody is telling them what to do either. The question the session opens on is not <em>where are we</em>. It’s <em>what do we do</em>. This module exists to give that question concrete answers.</p>"},{"name":"The Noqual Field","html":"<blockquote>\n<p><strong>DM-facing. Do not hand this to players.</strong></p>\n</blockquote>\n<p>Devulat’s noqual did not form here. It <strong>fell</strong>, a single body of it, continental in scale, buried in the highlands where Venoqual now stands. That is why the deposit is the largest in the world by an absurd margin and why the order’s engineers have never found the bottom of it. Almost nobody knows this.</p>\n<p>What everyone in southern Sholtan knows is the <em>effect</em>, even if they don’t know the cause:</p>\n<p><strong>Strongly magical creatures avoid the region.</strong> Not by law and not by patrol. They simply don’t come. The mass of noqual sitting under the highlands functions as a repellent, and Venoqual’s position between the northern forest and the capital means it stands directly between Sanguilum and everything that might otherwise wander south. This is the actual reason the capital is as safe as it is. The Faith Militant garrison at Vigilsylva gets the credit. The rock does most of the work.</p>\n<p><strong>It does not extend far out to sea.</strong> Coastal waters near shore are noticeably calmer than Sholtan’s waters generally. Beyond that, the sea is as dangerous as it has always been.</p>\n<p><strong>Magically-natured people can feel it.</strong> For Pipsy and Fern this is not pain and not a penalty. It’s a persistent wrongness in the air, a low buzz under everything, most noticeable when they first stopped being unconscious enough to notice it. It is markedly different from what they were used to in Xandar. Anyone with the fey trait, an innate magical nature, or heavy practice will register it if they think about it.</p>\n<p><strong>The effect intensifies with proximity.</strong> Sanguilum is a hum. Venoqual is not.</p>\n<blockquote>\n<p><strong>Venoqual is a genuine problem for Fern and Pipsy, and this should be signposted well in advance.</strong> Going down into the Excavation Works would be actively bad for them. The closest reference point the party has is the farm incident, where several of them got sick. Anyone can <em>visit the town</em>. Descending into the shafts is a different proposition, and a Beheaded physician who understands what they are will say so plainly and without drama before letting them try.</p>\n</blockquote>\n<p><strong>And it is why the party spent a month in Ottojikk.</strong> The Beheaded who found them were not being slow or cautious for its own sake. Hauling two deeply magical unconscious patients south, toward the field rather than away from it, was a real medical risk. They waited until the party could take it.</p>"},{"name":"Who Actually Governs Sholtan","html":"<p>Nobody, cleanly. Sholtan is not a country and the order is not its government. Three overlapping authorities share the continent, and the borders between them are soft in a way a modern map would refuse to draw.</p>\n<p><strong>Borders here are pre-modern.</strong> There is no line on the ground and no standing army holding one. Control is a question of who the locals believe is in charge, which shifts town by town and sometimes street by street. This matters constantly and quietly: the party can cross out of Beheaded influence without anything visibly changing.</p>\n<h3>The Three Powers</h3>\n<p><strong>The Beheaded</strong> govern the deep south directly. <strong>Sanguilum, Venoqual, and Portovel Arterium are order cities outright</strong>, built by them, run by them, and unambiguous about it to anyone who looks. <strong>Cordevale</strong> is theirs as well, though it does not feel that way from the ground; the authority is real and almost never has to be exercised. Between those points the broad triangle is under order influence, and within it they are steadily and unobtrusively extending that influence to towns still nominally Imperial, mostly by being better at wells, clinics, and grain than the alternative.</p>\n<p>The three cities do different work. <strong>Sanguilum</strong> is the capital and the industrial heart, where the ore lands and the ships and automatons are built. <strong>Venoqual</strong> is the noqual works. <strong>Portovel Arterium</strong> is the continent’s front door, the passenger and general-trade port, positioned centrally enough that anyone arriving on Sholtan comes through it on their way to somewhere else.</p>\n<p><strong>The Empire</strong> holds the rest as loose vassals with wildly varying levels of actual control. Several humanoid settlements and the areas around the small northern port are outright colonies. Everything further out is a matter of degree.</p>\n<p><strong>The monstrous peoples</strong> of the middle continent hold their own territory and have their own arrangement, a treaty with the Empire structurally similar to the order’s, except that in practice they are subjugated, poorly supported, and living to a standard the Empire would not tolerate for its own. They deal with the Beheaded far more readily than with the Empire, and the reason is not complicated: the order treats them as people.</p>\n<h3>Why the Empire’s Grip Is Weak Here</h3>\n<p>Sholtan sits ten to fifteen thousand miles from the Imperial heartland, across ocean that is genuinely lethal. Crossing it requires real fleets, and Imperial vessels carry powerful mages as standard equipment rather than as a luxury.</p>\n<p>The Beheaded, who cannot do that, have gone the other direction entirely: armoured hulls, ironclads, and progressively heavier guns, on the theory that a sea monster can be shot even if it cannot be warded. That arms race is ongoing and is one of the more visible places the order’s technology is advancing fast.</p>\n<p>On top of the distance, magic going loose in the world has made holding territory dramatically harder than it was a generation ago, and the Empire has felt that more than anyone because it has more territory to hold. It is currently pouring enormous resources into the worst-affected regions of Xandar and has fallen back on local leadership to keep Sholtan together until things calm down. Nothing suggests they will.</p>\n<p>There is an irony in this that the order is far too polite to say out loud in mixed company: the thing eroding Imperial control is precisely the thing the Beheaded have spent centuries warning about, and the Empire’s answer has been to put more mages on more ships.</p>\n<blockquote>\n<p><strong>What this means at the table.</strong> The order is powerful, respected, and locally dominant, but it is not sovereign and does not pretend to be. It has no claim on the party, no authority to detain them, and no interest in acquiring either. Everything the order gets in Sholtan, it gets by being useful.</p>\n</blockquote>"},{"name":"The Order Is Not Human","html":"<p>This needs saying because it is easy to run wrong by default. The Beheaded are one of the most ancestrally mixed institutions in the world, and a Sanguilum street should not read as a human city with a few exceptions in it.</p>\n<p>Devulat has plenty of humans and the south has more than most places, but the order is not a human organization that admits others. It recruits from anyone who can do the work, and it has been doing so for centuries. <strong>Dwarves, elves, halflings, gnomes, and minotaur are all common enough in the southern population to be unremarkable in the ranks.</strong> Beyond that the order runs considerably stranger than the world around it.</p>\n<p><strong>The monstrous peoples are the part most likely to get missed.</strong> The middle of the continent and the forest fringe are home to peoples the Empire regards as a treaty obligation and keeps on substandard support, anadi, ghoran, lizardfolk, kholo, tripkee and vanara in the wet country, azarketi along the northern shoreline, and jotunborn out at the far northwestern edge. The Beheaded have spent generations treating them as colleagues, and it has been repaid. Their children come to Beheaded schools. Their sick come to Beheaded wards. A meaningful number of them take the scarf.</p>\n<p><strong>And the ordinary ranks are broader than the southern population would suggest.</strong> Orcs, goblins, hobgoblins, ratfolk, tengu, kobolds, and catfolk all turn up in the Corps in numbers that would raise eyebrows anywhere else and raise none here. The order recruits on competence and has never seriously pretended otherwise.</p>\n<p>That is not charity and the order would be irritated at the suggestion. It is the doctrine working as written: the edicts say nothing whatsoever about shape, and a great deal about competence.</p>\n<blockquote>\n<p><strong>Practical instruction.</strong> When populating a room, a ward, a lecture hall, or a work crew, default to mixed. A surgical theatre with a ghoran holding retractors is normal. A lizardfolk lecturing on siege engineering is normal. Nobody in Sanguilum comments on any of it, and a visitor who <em>does</em> comment will get a politely blank look.</p>\n</blockquote>\n<p><strong>Three named NPCs are included below specifically to make this concrete.</strong> They are Archivist Sesh Nemeth, Cultivator Oleander, and Tidewarden Ashek-Vel, and they should not be the only non-humanoid faces the party sees.</p>"},{"name":"What They Were Told","html":"<p>This is the doctrinal spine of the entire module. It came up during the party’s orientation, it comes up again in every town, and it governs how every Beheaded NPC reacts to every spell cast in front of them. One read should be enough to run all of it.</p>\n<p><strong>They do not disarm anyone of magic.</strong> The edicts bind members, not guests. A Faith Militant warden watching a visiting caster is doing what a city guard does watching a visitor with a sword on their hip: noting it exists, trusting it to stay sheathed, reacting the moment it isn’t.</p>\n<p><strong>But there is a hard floor, and it is not about magic at all.</strong> The order’s objection to most magic is doctrinal, a slow poison, a surrender of self-reliance, something to be patient with and gently argued out of. Their objection to <em>one specific category</em> is not doctrinal. It is moral, absolute, and shared by essentially every member regardless of Corps or rank.</p>\n<p>Magic that removes a person’s consent is considered inherently evil. Not unwise. Not a regrettable shortcut. Evil, plainly, and the order’s position is that this is simply what the thing is once you describe it honestly. A spell that seizes another person’s body and mind and walks them around like a puppet is slavery executed in six seconds with a gesture, and the fact that it wears off in an hour does not make it something else. A spell that removes someone’s ability to refuse, then used to take from them or touch them, is assault at minimum and considerably worse at its logical end. Every member of this order will say that to your face, and most will get visibly heated doing it.</p>\n<p>Two things follow, and both are worth playing:</p>\n<p><strong>It’s personal for a meaningful number of them.</strong> The order draws recruits from people the world has failed. There are full members in Sanguilum who came to The Beheaded because someone once took their will away with a word and they never entirely got it back. They don’t discuss it. They don’t need to. It’s audible in how the subject gets talked about.</p>\n<p><strong>Formal instruction in it reads as civilizational insanity.</strong> That there are academies where a young person can enroll, pay tuition, and be systematically trained to override other minds, and that this is a respectable career, is to the average member roughly as comprehensible as a licensed school for poisoners. This is one of the few subjects on which an otherwise gracious, patient, hospitable member of this order will simply lose their temper.</p>"},{"name":"What They Were Told: How the Order Actually Argues","html":"<p>This is where the tone most often goes wrong, so it is worth being precise.</p>\n<p><strong>The order does not proselytise, and it does not open the subject.</strong> No Beheaded NPC walks up to a caster and starts in on doctrine. Nobody comments on a spell being cast in the street. Nobody makes a face. A member who disagrees with how a guest lives simply gets on with their afternoon, and the party could spend a week in Sanguilum without a single person raising it.</p>\n<p><strong>They engage when the party engages.</strong> If a PC asks what they think, defends their own practice, or challenges the doctrine, the member will answer, and they will answer properly, these are educated people who have thought about this more than the person asking. But it is a conversation, not a confrontation. Flat, matter-of-fact, no heat, and it ends when the PC wants it to end.</p>\n<p><strong>Heat appears only when pushed, and only in specific people.</strong> The consent material is the exception. A member with a personal history there will get an edge in their voice if someone is flippant about mind magic, and the edge is the tell that there is a history. That should be rare, earned, and never the opening note.</p>\n<blockquote>\n<p><strong>The rule in one line:</strong> disagreement is offered, never imposed. If the party never asks, the order never says.</p>\n</blockquote>"},{"name":"What They Were Told: What They Might Actually Say","html":"<p>Sample lines, so the argument doesn’t have to be improvised. None of these are openers. All of them are answers.</p>\n<p><strong>On magic generally, the standard position:</strong> &gt; “It works. Nobody here disputes that it works. We dispute what it costs, and that the bill arrives somewhere other than where the spell was cast.”</p>\n<p><strong>When told the order’s position is extreme:</strong> &gt; “Possibly. We have been wrong before and will be again. But we have been keeping records for nine hundred years, and the records do not improve.”</p>\n<p><strong>When someone points out the order uses technology that looks like magic:</strong> &gt; “The difference is that I can show you how mine works. Every part of it. That is the whole of the argument.”</p>\n<p><strong>On being asked whether they hate casters:</strong> &gt; “No. I would rather you didn’t. That is a different sentence.”</p>\n<p><strong>Sable Ironmark, to Pipsy, on trained practice:</strong> &gt; “You were born fey. That is weather. Nobody chooses it and I would be a hypocrite to hold it against you, look at me. What you learned afterward you chose. I would like to know why you chose it, and I would like you to have a better answer than that it was useful.”</p>\n<p><strong>Oleander, if Pipsy accelerates growth with magic:</strong> &gt; “It will fruit. It will fruit sooner than it should, and it will be weaker for the whole of the rest of its life, and the soil will carry less than it did. You have borrowed against the plant. It is not my plant, so it is not my business. But you asked.”</p>\n<p>Oleander is the most useful NPC for this argument precisely because there is no theology in it. It is one gardener telling another gardener that a shortcut has a cost, and it lands harder than any doctrine would.</p>\n<p><strong>Casiveth Null, to Fern:</strong> &gt; “You are the only person I have ever met who saw the world before any of this was settled. I am not going to waste that arguing with you. I would rather you told me what it looked like, and then, if you like, I will tell you what I think it became.”</p>\n<p>Null genuinely will not argue doctrine with Fern unless she insists. He wants the primary source, not the win.</p>\n<p><strong>Torvis Amsel, on Elemir’s tattoos, if asked directly:</strong> &gt; “You brought hands. I brought hands. The rest is your business.”</p>\n<p><strong>Nathaniel Bael, if the subject of magical healing comes up:</strong> &gt; “I have watched a man knit a bone with a word. Very impressive. I have also watched him do it wrong, and nobody in that room including him could tell me why. I can tell you why. That is not nothing.”</p>"},{"name":"What They Were Told: Where the Edge Is","html":"<p>Two of the named NPCs carry something personal, and it should surface only under pressure.</p>\n<p><strong>Perpetua Vance</strong> <em>(Portovel Arterium)</em> delivered a child, twenty years ago, to a woman who had been charmed into a marriage she did not choose and could not explain to anyone. Perpetua has never told that story to a stranger and will not tell it now. But if someone at her table treats enchantment as a clever tactic, the warmth drops out of her voice for one sentence and comes straight back, and she changes the subject herself.</p>\n<p><strong>Darro Ashfen</strong> <em>(Vigilsylva)</em> lost his people to something that walked them out of their own homes. He will not discuss it. If a guest jokes about mind-affecting magic in his hearing he simply stops talking and does not start again, which is considerably worse than being argued with.</p>"},{"name":"What They Were Told: The Named List","html":"<p>Recited flat, with no particular emphasis, the way one reads a fire code. <strong>These are not forbidden spells. They are spells prosecuted as violent crimes if used on a person</strong>, with no distinction drawn between the spell and a knife.</p>\n<table>\n<thead>\n<tr>\n<th><strong>Effect</strong></th>\n<th><strong>PF2e examples</strong></th>\n<th><strong>Treated as</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Seizing control of a body or mind</td>\n<td><em>dominate</em>, <em>charm</em>, <em>command</em>, <em>suggestion</em>, <em>confusion</em></td>\n<td>Assault; at the upper end, enslavement</td>\n</tr>\n<tr>\n<td>Removing a sense or the ability to act</td>\n<td><em>blindness</em>, <em>deafness</em>, <em>paralyze</em>, <em>sleep</em>, <em>shroud of night</em></td>\n<td>Assault</td>\n</tr>\n<tr>\n<td>Reading or entering a mind uninvited</td>\n<td><em>mind reading</em> and equivalents</td>\n<td>Assault</td>\n</tr>\n<tr>\n<td>Wearing another’s face to obtain something</td>\n<td>any transformation or illusion so used</td>\n<td>Fraud; if used to obtain intimacy, assault</td>\n</tr>\n</tbody>\n</table>\n<p>Self-defense is the only accepted justification, and it’s a real one. If someone draws steel in an alley, blinding them is defensive and will be treated as such. The order is not asking guests to die politely. What it will not accept is any of the above used first, used casually, or used because someone was irritating.</p>\n<blockquote>\n<p><strong>Underplay this.</strong> The officer delivers the sense-deprivation line, <em>blinding, deafening, or paralysing a person is treated exactly as though you had done it with your hands</em>, while pouring tea, then moves to the next item on the list. It is meant to land on nobody in particular. It may land on somebody in particular anyway.</p>\n</blockquote>"},{"name":"What They Were Told: Shapechangers","html":"<p>Anyone able to alter their form is asked for a brief, honest description and reminded that using it to deceive someone inside the walls is fraud. The order is genuinely more relaxed here than on mind magic: changing your own face is your business, and wearing a stranger’s to burgle a warehouse is a property crime like any other. Where it stops being relaxed is the point where a false face obtains something the real one wouldn’t have been given.</p>\n<blockquote>\n<p><strong>Scene, usable as flashback.</strong> The officer reaches Niko’s page, glances up, and asks, pleasantly, without any change in tone, what she can change into and whether she intends to pass as someone she isn’t while she’s here. It’s a question, not a challenge. Any honest answer is the right one. She thanks her for the specifics and moves to the next item.</p>\n</blockquote>"}]},{"name":"Part Two: Sanguilum","pages":[{"name":"Overview","html":"<p><em>Southern tip of Sholtan. Seat of the order for five centuries. Population \\~286,000, of whom roughly 167,000 are members. Home, for now.</em></p>\n<p>The party has been here for months, though they were unconscious for most of it. They know this city the way anyone knows a place they have convalesced in: the route from their rooms to the market, the sound of the bells, which corridors of the Sanctum Medica smell like what. It is familiar. It is not theirs.</p>"},{"name":"Overview: The First Time They Really Saw It","html":"<p>One moment of scale worth using: the day each of them was first well enough to walk outside unaided. That happened weeks ago, and can be delivered as a flashback or simply as the thing they see again every morning.</p>\n<blockquote>\n<p>The Sanctum Medica sits in the middle tiers, and the terrace outside the recovery wards faces west and down.</p>\n<p>Sanguilum is white, and then it very much isn’t. It’s built on a hill above a natural harbor and it climbs, tier on tier, in pale stone that catches the afternoon light hard enough to hurt, but red bougainvillea pours out of every window and planter in long cascades. There are flowering terraces on every level, and the roads between the tiers are red brick, arteries laid deliberately, running up through the white in long looping curves you can trace from one end of the city to the other. At the crown sits a single enormous structure with a dome, and even from here the scale of it recalibrates everything else you were looking at.</p>\n<p>The streets are full of colour that has nothing to do with the flowers. Prussian blue, crimson, charcoal, brown, harvest orange, plum, ochre, forest green, and a long red scarf on every single one of them.</p>\n<p>Below, the harbor is full. Barges down from the highlands, deep-water ships at the outer moles, the river mouth churning with traffic. Lift cars climb the hill on cables from tier to tier, and one swings up out of the harbour on the longest span you've ever seen. Somewhere in the middle tiers a railcar runs along its own elevated line and disappears behind a terrace.</p>\n<p>And under all of it, the bells. Every tier keeps its own, and on the hour they ring in sequence from the crown downward, so the sound rolls down the hill to the harbor and stops. It takes about a minute. The whole city pauses fractionally while it happens, the way people do for something they have heard their entire lives.</p>\n<p>There is also something else, if you are the kind of person who would notice. A pressure. A faint wrongness in the air that has been there since you woke and that you have not been able to name.</p>\n</blockquote>"},{"name":"Overview: Reading the City","html":"<p>Sanguilum is legible if you know what to look for, and Bael does. He can name any of this on sight, and letting him explain his own city to his friends is worth more than any boxed text.</p>\n<table>\n<thead>\n<tr>\n<th><strong>Tier</strong></th>\n<th><strong>What’s there</strong></th>\n<th><strong>How it looks</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>The Crown</strong></td>\n<td>Codex Ventriculum, the Grand Archive, leadership offices, the vault</td>\n<td>White stone, deliberate space, quiet. Penitent visible at the approaches.</td>\n</tr>\n<tr>\n<td><strong>Upper tiers</strong></td>\n<td>Scholarly and Arts Corps. Libraries, lecture halls, the Round, studios</td>\n<td>Windows everywhere. Instruments and argument. Students on every stair.</td>\n</tr>\n<tr>\n<td><strong>Middle tiers</strong></td>\n<td>Medical and Engineer Corps. Sanctum Medica, workshops, foundries, rail yards</td>\n<td>Working buildings. Steam, smoke, hot metal, antiseptic.</td>\n</tr>\n<tr>\n<td><strong>Lower tiers</strong></td>\n<td>Civil, Natural, Agrarian Corps. Markets, Counting House, Conservatory, granaries</td>\n<td>Busiest and most ordinary. Non-members everywhere. Children, carts, laundry.</td>\n</tr>\n<tr>\n<td><strong>The Harbor</strong></td>\n<td>Shipyards, foundries, ore wharves, warehouses, river mouth</td>\n<td>Loud, wet, industrial. The largest works in the order. Crews who’ve never been up the hill.</td>\n</tr>\n<tr>\n<td><strong>The Walls</strong></td>\n<td>Faith Militant. Barracks, sparring yards, armouries, the Hunters’ Lodge</td>\n<td>Deliberately unglamorous. Drill noise at all hours.</td>\n</tr>\n</tbody>\n</table>\n<p><strong>The thing to convey:</strong> the Corps aren’t segregated, they’re <em>concentrated</em>. A physician lives wherever they like. But the density shifts as you climb, and the whole city reads as one continuous argument that knowledge, craft, and care are worth building a mountain out of.</p>\n<p><strong>Sanguilum makes things, and it makes them here.</strong> The harbour and the middle tiers together are the largest industrial concentration the order has anywhere. Noqual comes down the river from Venoqual, adamantine and heavy ore come in by sea from Shaadu, fifteen hundred miles east, and what goes out is warships, automatons, ordnance, rail plant, surgical instruments, and everything else the order builds. Every other Beheaded holding is supplied from here. Nothing in Portovel Arterium, Venoqual, or anywhere else competes with it, and none of them try.</p>"},{"name":"Overview: Who Lives Here, and How","html":"<p>This is the thing about Sanguilum that a visitor works out on the first afternoon and never quite gets over: a great many of the people in the streets do not wear a grade, and nobody treats them as guests.</p>\n<p>Residence in the capital is granted, never bought. There is no market in houses, no way to petition from outside, and no route in for someone with no connection to the order. You are born here, you marry in, you are brought in, or the order decided it owed you something. The instrument is the <strong>Oath of Residence</strong>, and it carries five statuses. Four of them are not membership: no grade, no vote, no Corps. All five carry the same guarantee, which is the part that unsettles outsiders: fed, housed, and educated at the order's expense, for as long as you are here.</p>\n<table>\n<thead>\n<tr>\n<th><strong>Status</strong></th>\n<th><strong>Who holds it</strong></th>\n<th><strong>In Sanguilum</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Member</strong></td>\n<td>Full members of any Corps and grade</td>\n<td>~167,000</td>\n</tr>\n<tr>\n<td><strong>Household</strong></td>\n<td>Spouses, children, parents, siblings and aged kin of members. Automatic, held for life</td>\n<td>~43,000</td>\n</tr>\n<tr>\n<td><strong>Ward</strong></td>\n<td>Anyone in general education at the order's expense, adult or child, including members' children and every orphan the order has taken in</td>\n<td>~58,000</td>\n</tr>\n<tr>\n<td><strong>Charge</strong></td>\n<td>People the order took in and will not turn out again</td>\n<td>~15,000</td>\n</tr>\n<tr>\n<td><strong>Attested</strong></td>\n<td>Outsiders resident on fixed renewable terms, because the order's own business requires them present</td>\n<td>~3,000</td>\n</tr>\n<tr>\n<td><strong>Total</strong></td>\n<td></td>\n<td><strong>~286,000</strong></td>\n</tr>\n</tbody>\n</table>\n<p>That is a little over half the order's three hundred thousand members living in one city, with 119,000 non-member residents alongside them.</p>\n<p><strong>Running this at the table.</strong> Do not explain the Oath to the party. Let them notice it. The tell is that nobody in Sanguilum asks a stranger what they do; they ask who brought them. A Household grandmother running a stall in the lower tiers will talk about her daughter's Corps as if it were the family trade, because it is. A Charge who has lived on the order's bread for thirty years will be entirely unembarrassed about it, which is the detail that lands hardest with players used to charity being conditional. If someone asks a Civil Corps clerk how much residence costs, the clerk will not understand the question.</p>\n<p><strong>Charge is the status that says most about the order.</strong> It covers the Empire's discards, jotun and giants and gnomes and dwarves who were held as property and are too old, too broken, or too uninterested in a church to take a grade. Patients of the capital hospital whose convalescence became permanent. The non-member spouses of dead members, who keep their residence unconditionally and for life. Candidates who have sat the entrance examination three times and failed, and members who resigned a grade, neither of whom the order will turn out for it. Refugees the Watchline displaced. And the occasional person the Empire wants, for whom refuge fifteen thousand miles from the Royal City costs the order very little.</p>\n<p>Residence is not revoked for ceasing to be useful. It is revoked for cause, by the Assay Office, on written grounds, and almost never. So the city permanently accumulates people the order has no use for and goes on feeding them, and the Civil Corps budgets a line for it every year that only ever grows. Nobody regards this as a problem worth raising, and anyone who raised it would be told what the Ward status is for.</p>"},{"name":"Overview: The Attested","html":"<p>Three thousand people in Sanguilum believe none of it and live there anyway, because the order's own business requires them present. Terms are fixed, renewable, and signed by the Assay Office, which reads the Attested list more often than it reads anything else. An Attested cannot vote, cannot hold a post, cannot enter the Crown tier without escort, and can be put on a ship at the end of a term without appeal. In exchange they get the same bread, the same roof, and the same schooling for their children as a Proctor.</p>\n<p>They are the order's only honest foreigners, and they are the best source of outside opinion the party will find in the capital. A member will defend the order reflexively. An Attested factor who has spent nine years watching it from the inside will tell the party exactly what he thinks, over a drink, at length, and most of it will be admiring and none of it will be devout.</p>\n<p><strong>The three categories, and the six worth naming.</strong></p>\n<p><strong>Shaadu liaison staff, on the strait works.</strong> The largest single group and the most political, since the works are a joint undertaking and neither side entirely trusts the other's engineers. Mostly goblins, nagaji and strix, as Shaadu is.</p>\n<p><strong>Sub-Envoy Ketal Ashvane</strong>, Shaadu strix, twenty-two years Attested and the longest-standing on the list. Fluent, dry, utterly unflappable, and believes herself more familiar with Engineer Corps procedure than most Engineer Proctors. Her terms have been renewed eleven times and she has stopped pretending she will go home. She is the person the Assay Office quietly asks when it wants to know what Shaadu is actually thinking, which is a compromising position she has never once acknowledged. Her terms are signed, as all of them are, by an Associate Director of the Assay Office.</p>\n<p><strong>Works-Master Obed Tannhauser</strong>, Shaadu goblin, six years Attested, on site at the strait rather than in the city for most of the year. Openly contemptuous of the order's habit of building things three times stronger than they need to be, as he is more fond of the quick and dangerous engineering known to most goblins. He is openly delighted by being allowed to say so, despite any eye rolls he might receive from order engineers. He and the Engineer Proctor who signs off the works' load tables have an argument about tolerances that has been running for four years and that both of them enjoy enormously.</p>\n<p><strong>Adamantine brokers, who have to sign for bulk deliveries in person.</strong> Small, wealthy, and watched. Overwhelmingly Terrinbar: dwarves and gnomes, with halflings and elves behind them in the counting houses.</p>\n<p><strong>Factor Suleima Vosk</strong>, azarketi, of a Portovel house with adamantine interests, four years Attested and the only Attested who keeps a house on the third tier rather than in the assigned quarters. She paid for it and the order let her, which caused a minor scandal in the Counting House that has never fully died down. Sharp, cheerful, and entirely transactional. If the party needs something moved that the order would rather not move, she is the first person to think of, and she will want something specific in return.</p>\n<p><strong>Broker Anselm Krait</strong>, a Terrinbar dwarf, fifteen years Attested, and the one name on the list the Assay Office has considered not renewing twice. Nothing has ever been proven. He signs for adamantine, his paperwork is immaculate, and he is on more manifests than the volume of his trade accounts for. Inquisitor Shine Scar has read his file. He does not know that.</p>\n<p><strong>Portovel factors, with business that cannot be done at arm's length.</strong> Shipping, insurance, and the freight the rail does not carry. These are the order's own coast rather than foreigners, and they look like Portovel does: mixed, salt-stained, and unimpressed.</p>\n<p><strong>Factor Deshi Nyoro</strong>, human, nine years Attested, handles Portovel Arterium's end of the order's sea freight, and is the Attested most likely to end up drinking with the party. Talkative, generous, and genuinely fond of the order in the exasperated way of a man who has watched it refuse to do the profitable thing for nine straight years. He is the outside voice: everything he says about the Beheaded is affectionate, accurate, and slightly baffled.</p>\n<p><strong>Mistress Ilva Corrant</strong>, a Terrinbar gnome, marine insurer, three years Attested, present because the order's own fleet is uninsurable by any normal standard and she is the only underwriter who would take it. She is in Sanguilum to see with her own eyes what she is covering, has been appalled twice and impressed more often, and keeps a private ledger of the order's losses that is more accurate than the Counting House's. She would not sell it. She might, eventually, show it to someone she trusted.</p>\n<p><strong>Using them.</strong> Any of the six will talk to the party, which makes them the cleanest way to get an outside read on the order without breaking anyone's characterisation. They are not adversaries and mostly not quest-givers. Krait is the exception, and he is a slow one: the Assay Office thread, not a fight. If the party is escorted in the capital, their escort will be politely vague about the Attested quarters, not because anything is hidden but because the order finds the whole arrangement slightly embarrassing and would rather talk about the Archive.</p>"},{"name":"Overview: Colour","html":"<p>Do not let Sanguilum read as austere. It is white stone, but almost nothing else about it is restrained.</p>\n<p>Red bougainvillea spills from windows and planters in long cascades down the walls, and there are planted beds, trailing vines and flowering terraces on practically every tier. Even the Codex Ventriculum, a fortified compound surrounded by guards and automatons, holds gardens and sitting areas inside it.</p>\n<p>And every member of every Corps is wearing the colour of their profession, all day, everywhere. On a busy morning in the lower tiers the street is a moving map of what the order actually does.</p>\n<p>It is also a moving map of who they are. A charcoal-robed anadi arguing with a plum-robed halfling on a stair. A ghoran in harvest orange carrying seed trays. Two lizardfolk in forest green off shift and eating on a wall. A minotaur in dark crimson with a load of pipe on one shoulder. Sanguilum is a human city in roughly the way a port is: humans are the largest single group and nowhere close to a majority of what you see.</p>\n<table>\n<thead>\n<tr>\n<th><strong>Corps</strong></th>\n<th><strong>Robes</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Deep Prussian blue, cut like long dusters. Removed entirely for surgery</td>\n</tr>\n<tr>\n<td><strong>Engineer</strong></td>\n<td>Dark crimson overalls, leather at knees, elbows and chest, personal modifications everywhere</td>\n</tr>\n<tr>\n<td><strong>Scholarly</strong></td>\n<td>Deep charcoal grey, full length, wide sleeves, slight hood rarely worn up</td>\n</tr>\n<tr>\n<td><strong>Natural</strong></td>\n<td>Earthy brown, hemmed at knee or mid-calf, reinforced boots</td>\n</tr>\n<tr>\n<td><strong>Agrarian</strong></td>\n<td>Harvest orange, short-hemmed, well-worn and patched, sleeves rolled</td>\n</tr>\n<tr>\n<td><strong>Arts</strong></td>\n<td>Deep plum, flowing, longer cut and wider cuffs. Personal embellishment quietly tolerated</td>\n</tr>\n<tr>\n<td><strong>Civil</strong></td>\n<td>Warm ochre, a muted golden-brown, formal and immaculately pressed</td>\n</tr>\n<tr>\n<td><strong>Faith Militant</strong></td>\n<td>Forest green, slim and military, rank stitched at collar and shoulder</td>\n</tr>\n</tbody>\n</table>\n<p>Every one of them also wears the long red scarf. That is the through-line holding all the colour together, and it is the single most recognizable thing about the order anywhere in the world.</p>"},{"name":"Overview: The Audience","html":"<p>At some point after they’re all on their feet, leadership asks to see them properly. Not a summons. An invitation that everyone understands is not really optional, extended with total courtesy.</p>\n<blockquote>\n<p><strong>Who’s in the room.</strong> Some combination of <strong>High Chancellor Maren Voss</strong>, <strong>High Provost Thessaly Ourn</strong>, and <strong>Grand Marshal Aldric Crane</strong>. Two is plenty. Sera Dunmore may be present if the conversation touches extraplanar threat.</p>\n</blockquote>\n<p><strong>How to play it.</strong> Attentive. Respectful. Entirely aware the party holds firsthand knowledge of an active crisis that the order’s own records cannot match, and completely unwilling to be anything less than gracious about asking for it. They listen more than they talk. They ask precise questions. Where the party’s account conflicts with the order’s records, they say so plainly and without defensiveness, <em>that isn’t what we were told, and I would like to understand why.</em></p>\n<p>They will not be shocked by the existence of the cult. They will be shocked by specifics.</p>\n<p><strong>What the party gets out of it:</strong> the genuine sense that they were believed, an open invitation to the Grand Archive, and, critically, <strong>an answer to “what now.”</strong> These are the people best positioned to tell the party where the problems actually are, which makes this the natural room in which to point them at whatever comes next.</p>"},{"name":"Overview: The Escort","html":"<p>For the Codex Ventriculum grounds and comparable high-security areas, the party is accompanied. One or two Penitent, assigned to those areas and nowhere else. Framed exactly as intended: courtesy and precaution, not threat. Nobody says <em>we don’t trust you</em>. Any high-clearance visitor gets the same.</p>\n<p>The party has almost certainly glimpsed Penitent at a distance during recovery. This is the first time they’re close.</p>\n<blockquote>\n<p>They are too large. Not monstrously, but a hand’s breadth taller than their ancestry should allow, and broad through the shoulders in a way that reads wrong before you can name why. The armour is Sovereign Steel, dull and cold-looking, and it has been <em>written on</em>: edicts and passages worked into the plate in dense lines, hung with small reliquary objects that shift and click when they move. Where skin shows, the same text continues in ink.</p>\n<p>They fall in beside you without being asked, one ahead and one behind. Neither introduces themselves. When you speak to them they answer, politely, in as few words as possible, and then go back to watching the corridor.</p>\n</blockquote>\n<p>Most of the order believes they’re the product of brutal training, specialty elixirs, and the grafts the Medical Corps fits every one of them with and discusses with anyone who asks. The grafts are real. They aren’t the whole of it.</p>\n<p><strong>Bael knows what they actually are.</strong> Treat this as fixed: he has the full truth of the Penitent program, including the magical imbuing at its core, and holds it as a matter of trust rather than something he stumbled into. See <em>Chair Nathaniel Bael</em> and <em>Penitent Confessor Zacchaeus</em> for why.</p>"},{"name":"Sanguilum: Points of Interest: The Grand Archive","html":"<p>The public-facing wing of the Codex Ventriculum grounds. A long, high-windowed hall of reading tables and standing shelves holding every text the order will let outsiders browse unsupervised. Not the vault; the vault is beneath the building and none of this touches it. What it does hold is most of the order’s history, its magical theory (studied, never practised), and its accumulated natural science, offered to guests with startling generosity.</p>\n<p><strong>Director Casiveth Null</strong> <em>(Fetchling — Scholarly Corps)</em>, the order’s foremost expert on extraplanar civilizations and dead languages, will make time for Fern personally, and it won’t be performative. He has spent two decades chasing the origin of the order’s advanced knowledge and has never had a primary source walk in wearing skin.</p>\n<blockquote>\n<p><strong>Voice:</strong> Precise and formal, with something delighted running underneath that he keeps mostly contained. Asks one careful question at a time and actually waits for the answer.</p>\n</blockquote>\n<p>He can match Fern’s arrogance with quiet, unshakeable confidence, which may be the first time in ten thousand years someone has managed it. Note that he will not argue doctrine with her unless she insists on it. He wants the primary source far more than he wants the point. Worth holding in reserve rather than announcing: Null is a Fetchling, and so was Fern’s husband, dead now as long as everything else she left behind. Let Fern’s player decide what her face is doing.</p>\n<p><strong>Associate Wren Callowick</strong> <em>(Scholarly Corps)</em>, a first-year who once walked several months just to reach a Beheaded school, will orbit that meeting the entire time, too excited to contain it, too aware of rank to interrupt.</p>\n<blockquote>\n<p><strong>Voice:</strong> Breathless. Asks three questions in a row then apologizes for all three.</p>\n</blockquote>\n<p><strong>Archivist Sesh Nemeth</strong> <em>(Anadi, Female, 61 — Scholarly Corps)</em> runs the Archive’s reading floor and is the person anyone actually deals with, Null being three floors up and difficult to reach. Anadi keep two shapes; Sesh works in her humanoid one for the same reason anyone wears practical clothes to a job, and shifts out of it in her own rooms without ceremony or comment. Her people weave, and she has spent forty years applying that instinct to cross-referencing.</p>\n<blockquote>\n<p><strong>Voice:</strong> Warm, unhurried, faintly amused. Asks what you’re actually looking for rather than what you asked for, and is usually right.</p>\n</blockquote>\n<p>She is a good first face for the Archive precisely because she is unremarkable to everyone in the building. Nobody there finds a spider-weaver running the reading floor worth a second thought, and the party noticing that is rather the point.</p>\n<p><strong>And the Archive is the best thing that has happened to Niko in her life.</strong> She has trained herself to Master rank in the lore of her own people, an entire discipline’s worth of study about a culture she has never met a member of, and she is actively looking for other tanuki. This building holds the order’s ethnographic and natural-historical record of the world, offered freely, and nobody in it has any reason to withhold anything from her. Whether the search turns up a living community, a century-old traveller’s account, or one frustrating fragment is left open. But the <em>offer</em> costs the order nothing and means more to her than anything else in the city. Play the librarian as completely matter-of-fact: this is a normal request, they keep records, of course they’ll help her look.</p>"},{"name":"Sanguilum: Points of Interest: The Sanctum Medica","html":"<p>The Medical Corps’ primary teaching hospital. Surgical theatres, a triage hall, wards, and lecture rooms where the next generation of Beheaded physicians is built one exacting standard at a time. It smells of antiseptic and lamp oil rather than anything supernatural, which is precisely the point.</p>\n<p>This is Bael’s home ground in the most literal sense. He carries the highest Medicine in the party by a distance, keeps the group standing through fights and between them, and does it with his hands and a toolkit rather than a spell. He is a living argument for the order’s entire thesis, and every physician in this building will recognize that on sight, because it’s what the Sanctum exists to produce.</p>\n<p><strong>Director Phaedra Solenne</strong> <em>(Medical Corps)</em>, three centuries into a career of being nearly impossible to impress, has quietly tracked Bael since he first crossed her desk as a promising Ward.</p>\n<blockquote>\n<p><strong>Voice:</strong> Dry and clipped. Says less than she means. One word of approval from her outweighs a paragraph from anyone else.</p>\n</blockquote>\n<p>She won’t make a scene of his return. She’ll find a reason to be in the room, ask two or three questions that reveal she has read every report he’s filed, let her rare approval land exactly once in a single sentence, and go back to work.</p>\n<p><strong>Chair Nathaniel Bael</strong> <em>(Dwarf, Male, 143 — Medical Corps, Chair of Field Surgery)</em> is somewhere in this building, and he does not know his son has arrived until someone tells him.</p>\n<p>Nathaniel is the man who pulled a five-year-old out of a destroyed town, performed an excision weeks from any hospital that should have been able to support it, sat with the boy through months of nightmares, adopted him, and gave him a name. He was a Senior Knight Proctor then and a Knight Professor by the time the adoption went through. Twenty-two years on he holds a Chair, and his reputation rests on precisely the thing he is most reluctant to discuss: field surgery under impossible conditions.</p>\n<blockquote>\n<p><strong>Voice:</strong> Warm, wry, slightly rambling. Deflects praise reflexively and badly. Will talk at length about the technique and not at all about the child.</p>\n</blockquote>\n<p><strong>Playing the reunion.</strong> This does not need to be a set piece. Nathaniel is a dwarf in his workroom who is told his son is in the city, and the scene plays best unscripted. He will want to meet the people his son travels with, and he will be uncomplicatedly delighted by all of them, including the goblin and the goat.</p>\n<p>He is also one of a small number of people outside the program who know what the Penitent are, and the reason is standing in his own case notes.</p>"},{"name":"Sanguilum: Points of Interest: The Sparring Yards","html":"<p>An open training complex on Faith Militant ground where recruits drill in unarmed combat, blade work, and the specific art of taking down something much larger than themselves without magic. Runs early, loud, and constantly.</p>\n<p><strong>Knight Lieutenant Torvis Amsel</strong> <em>(Nagaji, Male, 124 — Faith Militant)</em> runs the hand-to-hand curriculum: leverage, patience, never striking first. Venerable by Nagaji standards, a generation and a half past Elemir, with that much longer to turn strength into technique.</p>\n<blockquote>\n<p><strong>Voice:</strong> Almost silent. Communicates by demonstrating. When he does speak it’s one short sentence and it’s usually a correction.</p>\n</blockquote>\n<p>That suits Elemir exactly, he’d rather settle a question on the mat than talk around it, and Torvis is one of the few people here who will simply nod and take up a stance instead of asking what he means by that.</p>\n<p><strong>Elemir’s tattoos.</strong> Worth knowing rather than planning for. His work is applied in ghost ink and stays invisible unless heat is put to it, which for Elemir means any time he uses his fire, and for anyone else wearing his work means standing near a bonfire or a hearth. Day to day he presents as completely unmarked, and the order has no reason to look twice at him.</p>\n<p>The interesting version of this is not concealment, since nothing would be confiscated anyway. It’s that Elemir is the one member of the party carrying obvious magic who gets to choose whether it’s obvious. The moment his tattoos surface mid-fight in front of Beheaded observers is a real beat, and it belongs to whenever it happens naturally rather than being staged.</p>\n<p>He’s trained well enough in Occultism and Religion to argue the theology properly rather than bristle at it. Torvis would not care either way.</p>"},{"name":"Sanguilum: Points of Interest: The Verdant Conservatory","html":"<p>Glass-roofed, maintained jointly by the Natural and Agrarian Corps. Part greenhouse, part working laboratory, part small menagerie for creatures under long-term study. Rare specimens beside mundane crops, all of it running on the conviction that understanding nature and defending it are the same project.</p>\n<p><strong>Director Sable Ironmark</strong> <em>(Leshy — Natural Corps)</em> is the most natural conversation partner the order has for Pipsy, and it is worth being precise about why.</p>\n<p>Sable is a leshy. She was born of natural magic, native to this plane, and she does not cast. <strong>None of that is a contradiction with anything the order believes.</strong> The edicts object to mortals reaching for magic and using it. They say nothing against things that magic made, and they explicitly instruct members not to fear those born to it. A leshy running the Natural Corps is not an awkward exception the order tolerates. It is the doctrine working exactly as written, and Sable will say so flatly if anyone suggests otherwise.</p>\n<p>She is useful to Pipsy because she has spent a career on the line between what a person is and what a person does, and she is very good at explaining where that line sits.</p>\n<blockquote>\n<p><strong>Voice:</strong> Curious, blunt, entirely without social anxiety. Asks personal questions without realizing they’re personal.</p>\n</blockquote>\n<p><strong>Cultivator Oleander</strong> <em>(Ghoran, 34 — Natural Corps)</em> works the Conservatory’s propagation beds under Sable and is, by any reasonable definition, a plant employed to look after plants. Oleander finds this funny and will make the joke before anyone else can. Ghoran remember across generations, which makes them extraordinary at long-term cultivation work and slightly unnerving in conversation, since Oleander occasionally recalls something that happened to someone else a century ago as though it were last week.</p>\n<blockquote>\n<p><strong>Voice:</strong> Slow, deliberate, dry. Long pauses that are thinking rather than hesitation. Makes exactly one joke per conversation and enjoys it enormously.</p>\n</blockquote>\n<p>Pipsy and Oleander will get on immediately, for reasons neither of them will need to explain.</p>\n<p>The one place they will not agree is growth magic. If Pipsy accelerates something in these beds, Oleander will take quiet, genuine exception, not doctrinally, but professionally. A forced plant fruits early, stays weaker for the rest of its life, and leaves the soil poorer than it found it. Oleander will say so once, plainly, note that it isn’t their plant and so isn’t their business, and go back to work. It is the single most effective version of the order’s argument in the module, because there is no theology in it at all.</p>\n<p><strong>Two separate things, and the order treats them differently.</strong> Pipsy carries the fey trait and speaks Fey and Wildsong, and none of that is held against her, the order’s own written doctrine instructs members not to fear those born to magic, whether beast or sentient. She didn’t choose what she was born as. The order has committed itself in writing to tolerating exactly that, and anyone who wants to make an issue of it has to argue with their own text and with a serving Proctor standing right there.</p>\n<p>What she has <em>learned</em> is a different question entirely. She is a trained druid who has studied and practised and grown her craft far past anything her ancestry handed her, and that is precisely the mortal use of magic the order objects to.</p>\n<p><strong>But nobody is going to raise it with her.</strong> Sable will not open the subject, Oleander will not open the subject, and neither will anyone else in the building. Pipsy can work in the Conservatory for a week and never once be challenged. If she asks what Sable thinks, or defends her practice unprompted, she will get a real and considered answer, see <em>What They Might Actually Say</em>, delivered without heat and dropped the moment she wants it dropped. That is the whole of the friction available here, and it only exists if Pipsy reaches for it.</p>"},{"name":"Sanguilum: Points of Interest: The Round","html":"<p>The Arts Corps’ primary performance hall, a circular theatre built for music, dance, and the order’s serious belief that culture is worth preserving on its own terms.</p>\n<p><strong>Instructor Callo Verrienne</strong> <em>(Halfling, Female, 40 — Arts Corps)</em> runs the movement and dance program and can watch someone move for thirty seconds and name the tradition that trained them.</p>\n<blockquote>\n<p><strong>Voice:</strong> Delighted and fast. Demonstrates constantly. Interrupts herself to try something.</p>\n</blockquote>\n<p>Flips isn’t a fighter who happens to be graceful, she’s a dancer whose entire combat style runs on it, taking her footing and momentum from the performance itself. Callo will spot that inside a minute and want to learn it, generously and with full attribution. Expect Flips to be asked to teach as much as she’s taught. She’ll also do tricks for snacks, and the Round’s instructors will find this delightful rather than undignified.</p>\n<p><strong>Director Lirien Ashveil</strong> <em>(Sylph — Arts Corps)</em> may appear briefly where a scene needs more weight. Unpredictable presence, genuine interest.</p>"},{"name":"Sanguilum: Points of Interest: The Hunters’ Lodge","html":"<p>A working outpost attached to the Faith Militant’s monster-hunting wing: kennels, a tracking range, trophy walls that are really teaching aids, and a briefing room papered with maps of everywhere something recently went wrong.</p>\n<p><strong>Knight Paladin Sera Dunmore</strong> <em>(Dromaar, Female, 39 — Faith Militant)</em>, the order’s foremost extraplanar tracker and threat assessor, head of its hunting arm, and the youngest Knight Paladin in living memory.</p>\n<blockquote>\n<p><strong>Voice:</strong> Economical with words, generous with action. Says the useful thing and stops.</p>\n</blockquote>\n<p>She hunts fiends and fey the way Gobbler hunts anything that moves, with total professional respect for the creature in question, and will recognize a real hunter’s eye the moment she sees one work. Kitty is welcome; the order does not turn away a working animal.</p>\n<p><strong>Two things about Gobbler to decide in advance.</strong></p>\n<p><em>He is the youngest in the party.</em> Twenty-two, a year behind Flips, and a goblin in his prime rather than a boy. What some Beheaded officers see first is the size and the trade instead: a small man carrying a brand, manacles and Master-rank Stealth, and how each individual NPC resolves that is a real choice rather than a detail. Sera reads him as a professional. Others might not, and his reaction to being condescended to is worth playing.</p>\n<p><em>He keeps a god.</em> A devotee of Teki Stronggut, trained well enough in Religion to defend the position if pressed, though he has never made much of it out loud and may not volunteer it at all. He isn’t unique in this: Fern was a devoted worshipper of Desna before everything that has happened to her, and where that stands now is an open question worth leaving to her. The order’s doctrine calls for patience toward exactly this, and most members will manage it without effort.</p>"},{"name":"Sanguilum: Points of Interest: The Counting House","html":"<p>The Civil Corps’ public banking and exchange office near the Grand Bazaar. Deposits, letters of credit, currency exchange, for members and visitors alike, with the same unremarkable competence the order brings to everything administrative.</p>\n<p>Mentioned because it solves a real problem: Pipsy is carrying enough loose coin to physically slow her down. Converting it or leaving it on deposit fixes that in an afternoon, and the clerk won’t find the request unusual. It’s also a plausible reason for anyone to interact with the Civil Corps, who are otherwise easy to miss entirely.</p>"},{"name":"Sanguilum: Points of Interest: The Hall of the Unburied","html":"<p>A quiet building near the Medical Corps’ grounds, half chapel and half memorial, where the order keeps the names of members and non-members alike who died in its service or under its protection. Not morbid, gardens rather than crypts, open air rather than stone weight, and a chaplain always present to sit with anyone who needs to sit with something.</p>\n<p>Offered as a space, not a plot beat. Sanguilum is built to hold grief with real weight rather than politely stepping around it, and a chaplain here will offer the order’s blessing for the dead plainly: that a life given in protection of others is honored, and that all blood ultimately returns where The Beheaded’s did.</p>\n<p><strong>But what this party is carrying is not a death, and the chaplains here know the difference.</strong> Hek is not dead. He is changed, and gone, and unaccounted for, and there is no rite for that. The order does not pretend otherwise and will not offer a funeral for a man who has not had one.</p>\n<p>What the Hall does have is a practice for exactly this. The unburied of the name are not only the dead. They are everyone the order lost track of. There is a wall for them, separate from the memorial proper, and the names on it have no dates. People come and sit with it. Some of those names have been there for decades. A few have been taken down again, which is the entire reason anyone keeps coming.</p>\n<p>A chaplain will offer to add Hek’s name, and will explain exactly what that means and does not mean: no claim that he is dead, no ceremony, no closing of anything. Just a name written down in a place where names are kept, and a standing acknowledgment that somebody is still missing and somebody is still waiting. It costs nothing and commits to nothing.</p>\n<p>That offer is Elemir’s to accept or refuse, and either is a real answer.</p>"},{"name":"Sanguilum: Points of Interest: The Grand Bazaar","html":"<p>Sanguilum’s central marketplace, sprawling from the base of the main road in a wide plaza of stalls, storefronts, and the order’s own provisioning houses. Loud, crowded, and entirely unwatched in the sense that matters. Nobody is monitoring what the party buys. Prices in Appendix B.</p>\n<p><strong>What the bazaar will not sell them</strong> is in Appendix B as well, and the answer at a stall is always the same: that isn’t something the order sells, said politely, with no elaboration offered. A stallholder genuinely does not know more than that. The restricted list moves on a Writ of Requisition out of the Ordnance House, and the party will not hear the word writ from a merchant.</p>"},{"name":"Sanguilum: Points of Interest: The Pilgrim’s Rest","html":"<p>Visitor lodging in the lower tiers, one of several such houses the order maintains. Clean rooms, real food, and nobody asking anything of anyone.</p>\n<p>The party has been housed near the Sanctum Medica since they woke, which was a medical arrangement rather than a hospitality one. At some point they stop being patients, and the Pilgrim’s Rest is where people in that position usually end up, close enough to everything, cheap enough to be free for guests of the order, and entirely their own. Moving out of the recovery wards and into rooms they chose is a small, real marker that the convalescence is over.</p>"},{"name":"Sanguilum: Points of Interest: The Writ of Requisition","html":"<p><strong>Use this the moment the order formally tasks the party with something.</strong> Until then it does not exist as far as they know.</p>\n<p>The order does not sell restricted equipment and is not going to start. What it will do, for people it is sending to do work it cannot do itself, is lend some. A Writ of Requisition is signed by a Director and countersigned by the Assay Office, and it is a loan, logged by item and by name, for the duration of a specific charter. The full list of what it opens and what it does not is in Appendix B.</p>\n<p><strong>Run the handover as a scene, not a shopping trip.</strong> It happens at the Ordnance House inside the Faith Militant compound, not at a stall. A Civil Corps clerk reads the list aloud twice. Every item is numbered. Nobody hurries and nobody is suspicious. It should feel less like being armed and more like being entered into a ledger, because that is exactly what it is.</p>\n<p><strong>Three things to land.</strong></p>\n<p>The writ is authority. Any member who reads it cooperates immediately and without question, which makes it the single most useful object the party will carry and also a beacon to anyone who recognises it.</p>\n<p>Loss is recorded, not punished. If they destroy something, the order notes it, replaces it if it can, and does not moralise. The note stays in the ledger for as long as the order exists, which for this institution is the actual consequence.</p>\n<p>Sovereign Steel is not on the table and the refusal is an offer. The party can pass the Militant Course on the same terms as anyone, and a Director will say so without being asked. Whether any of them want to is a much better question than whether they can have a sword.</p>\n<blockquote>\n<p><strong>For Fern and Pipsy specifically.</strong> The optics, the baton, the compound grenades and the mercy rounds contain no noqual and are safe for them. The order volunteers this before either of them has to ask, and volunteering it unprompted is the most Beheaded thing in the scene.</p>\n</blockquote>"},{"name":"The Attested — Stat Blocks","html":"<p>Six non-combatants, each built on a PF2e NPC Gallery chassis and nudged for ancestry and trade. None of them is a fight. If one ends up in a fight, the order has already failed at something.</p>\n<h3>Sub-Envoy Ketal Ashvane — Creature 4</h3>\n<p><strong>Common · LN · Medium · Strix · Humanoid</strong>\\\n<em>Attested · Shaadu liaison staff · Sanguilum, the strait works</em></p>\n<p>Twenty-two years and eleven renewals. Dry, unflappable, and believes herself more familiar with Engineer Corps procedure than most Engineer Proctors.</p>\n<p><strong>Perception</strong> +10\\\n<strong>Languages</strong> Common, Shaadu tongues, two more\\\n<strong>Skills</strong> Diplomacy +14, Society +12, Deception +10, Engineering Lore +10, Shaadu Lore +14\\\n<strong>Str</strong> +0, <strong>Dex</strong> +3, <strong>Con</strong> +1, <strong>Int</strong> +4, <strong>Wis</strong> +3, <strong>Cha</strong> +5\\\n<strong>Items</strong> writing set, sealed folio of terms, a knife she has never drawn</p>\n<p><strong>AC</strong> 19; <strong>Fort</strong> +8, <strong>Ref</strong> +10, <strong>Will</strong> +12\\\n<strong>HP</strong> 50</p>\n<p><strong>Low-Light Vision</strong> — Strix ancestry.</p>\n<p><strong>Wing Flutter</strong> — Ashvane can Leap up to 15 feet horizontally and takes no damage from a fall of 30 feet or less. She considers using it in the city undignified.</p>\n<p><strong>Twenty-Two Years of This</strong> — +2 circumstance bonus to Perception checks to Sense Motive against any member of the order, and to Society checks concerning the order's own procedure.</p>\n<p><strong>Neither Side's Creature</strong> — Once per day, Ashvane can decline to answer a question in a way that satisfies the asker. The GM decides what she leaves out.</p>\n<p><strong>Speed</strong> 25 feet</p>\n<p><strong>Melee</strong> [one-action] <strong>knife</strong> +8 (agile, finesse), <strong>Damage</strong> 1d4+1 piercing</p>\n<p><em>Built on: Noble (Creature 2), scaled two levels, Athletics traded for Diplomacy and Shaadu Lore.</em></p>\n<h3>Works-Master Obed Tannhauser — Creature 4</h3>\n<p><strong>Common · CN · Small · Goblin · Humanoid</strong>\\\n<em>Attested · Shaadu liaison staff · on site at the strait</em></p>\n<p>Openly contemptuous of the order's habit of building things three times stronger than they need to be, as he is more fond of the quick and dangerous engineering known to most goblins. He is openly delighted by being allowed to say so, despite any eye rolls he might receive from order engineers.</p>\n<p><strong>Perception</strong> +11\\\n<strong>Languages</strong> Common, Goblin, Shaadu tongues\\\n<strong>Skills</strong> Crafting +14, Engineering Lore +14, Acrobatics +9, Athletics +8, Sailing Lore +9\\\n<strong>Str</strong> +2, <strong>Dex</strong> +3, <strong>Con</strong> +3, <strong>Int</strong> +5, <strong>Wis</strong> +1, <strong>Cha</strong> +1\\\n<strong>Items</strong> tool roll, load tables in three hands of writing, pry bar, flask</p>\n<p><strong>AC</strong> 20; <strong>Fort</strong> +11, <strong>Ref</strong> +9, <strong>Will</strong> +7\\\n<strong>HP</strong> 55</p>\n<p><strong>Darkvision</strong> — Goblin ancestry.</p>\n<p><strong>Load Tables</strong> — When Tannhauser Recalls Knowledge about a structure, hull, bridge or vehicle, treat the result as one degree of success better.</p>\n<p><strong>Tell You What's Wrong With It</strong> — Tannhauser can Aid a Crafting or Engineering Lore check without preparation, and on a success the aided character also learns the single weakest point of whatever they are working on.</p>\n<p><strong>Speed</strong> 25 feet</p>\n<p><strong>Melee</strong> [one-action] <strong>pry bar</strong> +10 (two-hand d8), <strong>Damage</strong> 1d6+4 bludgeoning</p>\n<p><em>Built on: Artisan (Creature 1), scaled three levels, Crafting and a lore pushed to expert.</em></p>\n<h3>Factor Suleima Vosk — Creature 3</h3>\n<p><strong>Common · N · Medium · Azarketi · Humanoid</strong>\\\n<em>Attested · adamantine interests · Sanguilum, third tier</em></p>\n<p>The only Attested who owns her house rather than taking assigned quarters. Sharp, cheerful, entirely transactional.</p>\n<p><strong>Perception</strong> +9\\\n<strong>Languages</strong> Common, Alghollthu, two trade tongues\\\n<strong>Skills</strong> Diplomacy +11, Deception +11, Mercantile Lore +13, Society +9, Athletics +7\\\n<strong>Str</strong> +1, <strong>Dex</strong> +3, <strong>Con</strong> +1, <strong>Int</strong> +3, <strong>Wis</strong> +2, <strong>Cha</strong> +4\\\n<strong>Items</strong> ledger, letter of credit, main gauche, a very good coat</p>\n<p><strong>AC</strong> 18; <strong>Fort</strong> +7, <strong>Ref</strong> +9, <strong>Will</strong> +9\\\n<strong>HP</strong> 40</p>\n<p><strong>Low-Light Vision</strong>, <strong>Amphibious</strong> — Azarketi ancestry. Swim Speed 25 feet, and she can breathe water as easily as air.</p>\n<p><strong>Everything Has a Price</strong> — Once per day, Vosk can produce a contact, a berth, or a shipment the party could not otherwise arrange. She names her price at the time and it is never money.</p>\n<p><strong>Speed</strong> 25 feet, swim 25 feet</p>\n<p><strong>Melee</strong> [one-action] <strong>main gauche</strong> +9 (agile, disarm, finesse, parry), <strong>Damage</strong> 1d4+3 piercing</p>\n<p><em>Built on: Merchant (Creature 1), scaled two levels, azarketi swim and senses added.</em></p>\n<h3>Broker Anselm Krait — Creature 5</h3>\n<p><strong>Uncommon · N · Medium · Dwarf · Humanoid</strong>\\\n<em>Attested · adamantine broker · Terrinbar, resident fifteen years</em></p>\n<p>Immaculate paperwork, and on more manifests than the volume of his trade accounts for. Twice considered for non-renewal. Nothing has ever been proven.</p>\n<p><strong>Perception</strong> +13\\\n<strong>Languages</strong> Common, Dwarven, Terrinbar tongues, one more he does not mention\\\n<strong>Skills</strong> Deception +16, Mercantile Lore +14, Society +12, Thievery +12, Diplomacy +12\\\n<strong>Str</strong> +2, <strong>Dex</strong> +4, <strong>Con</strong> +3, <strong>Int</strong> +4, <strong>Wis</strong> +2, <strong>Cha</strong> +4\\\n<strong>Items</strong> three sets of books, assay seals, dagger, hand crossbow with 10 bolts</p>\n<p><strong>AC</strong> 21; <strong>Fort</strong> +11, <strong>Ref</strong> +13, <strong>Will</strong> +11\\\n<strong>HP</strong> 70</p>\n<p><strong>Darkvision</strong> — Dwarf ancestry.</p>\n<p><strong>Immaculate Paperwork</strong> — +2 circumstance bonus to Deception checks to pass off a document. On a failure rather than a critical failure, the discrepancy reads as a clerical error and not as a lie.</p>\n<p><strong>Slip the Manifest</strong> [reaction] — <strong>Trigger</strong> Krait learns that his papers are about to be examined. <strong>Effect</strong> He substitutes a clean set. The examination finds nothing. This works once per set of premises, and the Assay Office has noticed that it keeps working.</p>\n<p><strong>Speed</strong> 20 feet</p>\n<p><strong>Melee</strong> [one-action] <strong>dagger</strong> +13 (agile, finesse, thrown 10 feet), <strong>Damage</strong> 1d4+6 piercing</p>\n<p><strong>Ranged</strong> [one-action] <strong>hand crossbow</strong> +13 (range 60 feet, reload 1), <strong>Damage</strong> 1d6+4 piercing</p>\n<p><em>Built on: Charlatan (Creature 3), scaled two levels, Deception pushed to master, dwarf senses and Speed.</em></p>\n<h3>Factor Deshi Nyoro — Creature 2</h3>\n<p><strong>Common · NG · Medium · Human · Humanoid</strong>\\\n<em>Attested · Portovel sea freight · Sanguilum, the Attested quarters</em></p>\n<p>Talkative, generous, and genuinely fond of the order in the exasperated way of a man who has watched it refuse to do the profitable thing for nine straight years.</p>\n<p><strong>Perception</strong> +7\\\n<strong>Languages</strong> Common, two coastal tongues\\\n<strong>Skills</strong> Diplomacy +10, Sailing Lore +10, Mercantile Lore +8, Society +8, Athletics +6\\\n<strong>Str</strong> +1, <strong>Dex</strong> +2, <strong>Con</strong> +1, <strong>Int</strong> +3, <strong>Wis</strong> +2, <strong>Cha</strong> +4\\\n<strong>Items</strong> manifests, a flask worth sharing, sap</p>\n<p><strong>AC</strong> 17; <strong>Fort</strong> +6, <strong>Ref</strong> +6, <strong>Will</strong> +8\\\n<strong>HP</strong> 30</p>\n<p><strong>Nine Years of Watching</strong> — +2 circumstance bonus to Recall Knowledge about the order's habits, and he will volunteer it unasked. Anything he says about the Beheaded is affectionate, accurate, and slightly baffled.</p>\n<p><strong>Speed</strong> 25 feet</p>\n<p><strong>Melee</strong> [one-action] <strong>sap</strong> +6 (agile, nonlethal), <strong>Damage</strong> 1d6+2 bludgeoning</p>\n<p><em>Built on: Merchant (Creature 1), scaled one level, Sailing Lore added.</em></p>\n<h3>Mistress Ilva Corrant — Creature 4</h3>\n<p><strong>Common · LN · Small · Gnome · Humanoid</strong>\\\n<em>Attested · marine insurer · Terrinbar, resident three years</em></p>\n<p>The only underwriter who would cover the order's fleet, in Sanguilum to see with her own eyes what she is carrying. Appalled twice, impressed more often.</p>\n<p><strong>Perception</strong> +12\\\n<strong>Languages</strong> Common, Gnomish, Fey, two trade tongues\\\n<strong>Skills</strong> Society +14, Mercantile Lore +14, Sailing Lore +12, Diplomacy +10, Nature +10\\\n<strong>Str</strong> +0, <strong>Dex</strong> +3, <strong>Con</strong> +2, <strong>Int</strong> +5, <strong>Wis</strong> +4, <strong>Cha</strong> +3\\\n<strong>Items</strong> the private ledger, a brass slide rule, spectacles, stout cane</p>\n<p><strong>AC</strong> 19; <strong>Fort</strong> +8, <strong>Ref</strong> +10, <strong>Will</strong> +12\\\n<strong>HP</strong> 45</p>\n<p><strong>Low-Light Vision</strong> — Gnome ancestry.</p>\n<p><strong>The Private Ledger</strong> — Corrant knows the true figure for any loss the order's fleet has taken in the last three years, and her numbers are better than the Counting House's. She would not sell the ledger. She might show it to someone she trusted.</p>\n<p><strong>Appraise Risk</strong> [two-actions] — Corrant studies a plan, a vessel or a structure and names the single most likely way it fails. The GM answers honestly. She is right about eight times in ten, and the two are usually the interesting ones.</p>\n<p><strong>Speed</strong> 20 feet</p>\n<p><strong>Melee</strong> [one-action] <strong>stout cane</strong> +8, <strong>Damage</strong> 1d6+2 bludgeoning</p>\n<p><em>Built on: Noble (Creature 2), scaled two levels, Athletics and Warfare Lore traded for Mercantile and Sailing Lore.</em></p>"},{"name":"Where To From Here","html":"<p>The party is mobile, healthy, resupplied, and out of patience. Every option below is reachable from Sanguilum by rail, and none of them is the “right” one.</p>\n<table>\n<thead>\n<tr>\n<th><strong>Destination</strong></th>\n<th><strong>Why go</strong></th>\n<th><strong>Time from Sanguilum</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Ottojikk</strong></td>\n<td>Where they arrived on this continent. Rail junction, merchant hub, and home of the door-circle they arrived through. Still Imperial, inside Beheaded territory.</td>\n<td>\\~4 to 7 days (via Venoqual)</td>\n</tr>\n<tr>\n<td><strong>Venoqual</strong></td>\n<td>The noqual works. Closest major stop. Genuinely hazardous for Fern and Pipsy below ground.</td>\n<td>2.2 to 3.6 days</td>\n</tr>\n<tr>\n<td><strong>Cordevale</strong></td>\n<td>The breadbasket. Quiet. The order at its least performative.</td>\n<td>\\~5 to 8 days</td>\n</tr>\n<tr>\n<td><strong>Portovel Arterium</strong></td>\n<td>The continent’s front door. Passengers, general trade, and every rumour out of Xandar. An order city outright.</td>\n<td>6.3 to 10.5 days</td>\n</tr>\n<tr>\n<td><strong>Vigilsylva</strong></td>\n<td>The frontier post against the northern forest. Jointly held by the Beheaded, the Empire, and the monstrous peoples. The dangerous option.</td>\n<td>\\~10 to 16 days</td>\n</tr>\n</tbody>\n</table>\n<p>Ottojikk is the one with a personal hook already attached, and it sits on the junction, so it’s also the natural first hop toward anywhere else.</p>"}]},{"name":"Part Three: Ottojikk","pages":[{"name":"Overview","html":"<p><em>Rail junction and merchant trade hub, at the crossing where the Sanguilum line meets the Cordevale–Portovel Arterium line. Forested country. Relatively large. </em><em>Empire-influenced, inside Beheaded territory.</em>**</p>\n<p>This is where the party’s five months began, and none of them were conscious for it. It is also the most politically awkward town in the region, and the awkwardness is worth understanding before running it.</p>\n<p>Ottojikk sits squarely inside the triangle the Beheaded hold, Sanguilum to the south, Cordevale to the west, Portovel Arterium to the east, all three firmly theirs. Ottojikk is the hole in the middle. It remains meaningfully under Imperial influence, and it runs on the one thing the order objects to most. The order holds no civil authority here, and everyone involved knows it. It does own the rails the town lives on, and everyone involved knows that too.</p>"},{"name":"Overview: Why Ottojikk Exists","html":"<p>Two reasons, and the second one is the interesting one.</p>\n<p><strong>The junction.</strong> The line up from Sanguilum meets the east–west line between Cordevale and Portovel Arterium here, at right angles, in the middle of forested country. Everything moving between the capital, the breadbasket, and the eastern port passes through. That alone would make a town.</p>\n<p>It is worth being precise about who owns what, because it is the quietest and most important fact in Ottojikk. The town did not build the rails, the marshalling yard, or the station. The order did, and the order still owns all three. Ottojikk grew up around a junction it has no claim on. The merchant houses stacked in the yard are tenants, the freight rates are the order's rates, and the customs staff collect tariffs on goods that arrive on somebody else's trains.</p>\n<p><strong>The Wayhouse.</strong> Ottojikk holds one of the sanctioned door-circles, a linked network of rooms scattered across the world, each connected to the others. Every terminus is an inn, each inn has its own owner, and the Wayhouse is Ottojikk's. The network allows travel between distant points for anyone who can reach a terminus and pay. There is no wandering teleportation on Devulat. There is <em>this</em>, and a handful of places like it, and that is the whole of it. The party knows how it works, because it is how they got here: through a door in an inn in Xandar and out of a door in Sholtan, though none of them walked it this time.</p>\n<p>The Wayhouse is why a rail junction in the woods is a genuinely wealthy town. Goods and people that would otherwise spend two weeks on a ship arrive in an afternoon. The merchant houses followed the door, and the rail followed the merchant houses.</p>"},{"name":"Overview: The Order’s Position","html":"<p>The Beheaded footprint here is a school, a small ward, and a rail liaison office. No garrison, no gate procedure, no named list read to arrivals.</p>\n<p><strong>That is a choice, not a weakness.</strong> The order holds no civil authority in Ottojikk; the Empire does, loosely, in the way it holds most things at this distance. A magistrate hears cases, a customs office collects tariffs, and the order does not interfere with either.</p>\n<p>What the order holds instead is the junction. Ottojikk's connection to the capital, the breadbasket, and the eastern port exists on order rails, on order trains, at order rates, and can be re-timetabled by a clerk in Sanguilum. The Imperial garrison stationed here is supplied along a line it does not control. Nobody on either side says this out loud and nobody needs to. It is the reason the tariff arrangement has never been seriously tested in either direction, and it is a cleaner demonstration of how the order actually works than any sermon.</p>\n<p>On top of that it is quietly, patiently making itself indispensable in the ordinary way. It staffs a clinic nobody else was going to staff, teaches anyone who turns up, and keeps the rail liaison office open because the rail is the town's lifeline. This is the same long game the order plays everywhere: not conquest, just being the people who fixed the well, for as many years as it takes, while owning the well.</p>\n<p>Ask a Beheaded member here whether they’d like Ottojikk brought fully into the fold and you’ll get a careful non-answer. Ask them whether they’d shut down the Wayhouse if they could, and the answer is more complicated than doctrine suggests: the doors move grain into Cordevale’s lean months and medicine to places that would otherwise wait a fortnight, the transits are consensual, and nobody is being forced through one.</p>\n<p>In private, most Beheaded stationed here will still admit the doors make their skin crawl.</p>\n<blockquote>\n<p>The forest opens and the town is just <em>there</em>, filling the gap where two rail lines meet. Timber buildings three and four storeys high, packed tight around a marshalling yard doing more business than the whole of Cordevale. Freight everywhere. Cranes. Stacked crates under tarpaulins in six different house colours.</p>\n<p>And at the centre of it, taller than anything around it, the Wayhouse, a rambling four-storey inn with too many doors on the upper floors and a queue at the entrance that has nothing to do with wanting a bed. People go in with luggage. Different people come out with different luggage. Nobody in the street so much as glances at it.</p>\n<p>You remember the view down the slope toward the yard. What none of you remember is the arrival room upstairs, where six unconscious strangers came through a door in a heap with nobody behind them.</p>\n</blockquote>"},{"name":"Overview: The Room","html":"<p>The party came through the door-circle unconscious and did not wake. What the staff describe, repeated often enough by now to have become the house story, is that the arrival door opened off the schedule, six people came through it in a heap on the floor, the door shut behind them, and one of them was wearing a long red scarf.</p>\n<p><strong>Nobody came with them.</strong> That detail matters and the Wayhouse staff are insistent about it. The door-circles log every transit, and the log shows this one plainly: six travellers from the sister inn in Xandar, unbooked, with no name entered on the sending side. Whoever put them through did not follow them and has sent no word since. The Xandar inn is its own house under its own owner, and the Wayhouse knows it only by its entries in the log. It has quietly unnerved the people who run the place ever since.</p>\n<p>That red scarf is the entire reason any of them are alive. Someone recognized what it meant and went to find Beheaded.</p>\n<p><strong>What the party can learn here, if they ask:</strong></p>\n<ul>\n<li>They came through the door from the Xandar terminus. The log is clear about that and about nothing else.</li>\n<li>Nobody on this side saw who sent them, and nobody on this side knows the man who did.</li>\n<li>There were <strong>six</strong> people in that room. Not seven. Neither Hek nor Keh was ever here.</li>\n<li>Whatever carried them off the field got them as far as an inn in Xandar. What happened before that door is not in any log.</li>\n<li>They were not moved south for a month, and the reason was medical.</li>\n<li>The room has been kept more or less as it was, in the manner of people not certain whether something holy happened in their building.</li>\n</ul>"},{"name":"Overview: The People of Ottojikk","html":"<p><strong>Innkeeper Hessa Varr</strong> <em>(Gnome, Female, 88 — not Beheaded)</em> has run the Wayhouse for forty years and has seen a great deal come through her upper floors. She has been sitting on this story for five months and has told it perhaps four hundred times, and she is still not bored of it.</p>\n<blockquote>\n<p><strong>Voice:</strong> Brisk, theatrical, delighted by her own material. Tells it like a performance because it has become one. Genuinely kind underneath.</p>\n</blockquote>\n<p>She will recognize them instantly and make an enormous fuss. She will also, if pressed past the performance, admit that she has not rented that room since and cannot fully explain why.</p>\n<p><strong>Doorwarden Ilsabet Kroy</strong> <em>(Elf, Female, 210 — not Beheaded)</em> maintains the circles. She is a practising, credentialed, entirely legitimate arcanist living and working in the heart of Beheaded territory, and the arrangement functions because both sides have decided it will.</p>\n<blockquote>\n<p><strong>Voice:</strong> Dry, precise, faintly amused by everything including herself. Explains magic the way an engineer explains a bridge.</p>\n</blockquote>\n<p>She keeps the transit logs and will produce them without being asked twice. She has wanted a competent second opinion on that entry for five months: a transit from Xandar with nobody's name on the sending side. She is the best source in the region on how door-travel actually works, its limits, and what could bypass it. Her professional relationship with the Beheaded liaison is genuinely warm, which some visitors find harder to believe than the doors.</p>\n<p><strong>Proctor Liaison Corbin Ashe</strong> <em>(Halfling, Male, 44 — Civil Corps)</em> is the order’s man in a town built on magic. His job is to be unfailingly reasonable in a place his doctrine tells him is a mistake, and he has done it for eleven years.</p>\n<blockquote>\n<p><strong>Voice:</strong> Measured, diplomatic, careful. Chooses words like a man who has learned what happens when he doesn’t.</p>\n</blockquote>\n<p>He is the right NPC for a conversation about what it costs the order to coexist with something it believes is wrong. He won’t be preachy. Ask him directly what he thinks of the Wayhouse and he’ll be quiet for a moment, then give an honest and complicated answer.</p>\n<p><strong>Factor Bellamy Orr</strong> <em>(Ratfolk, Male, 41 — not Beheaded)</em> represents three merchant houses at once, which is not supposed to be allowed, and everybody knows.</p>\n<blockquote>\n<p><strong>Voice:</strong> Fast, friendly, transactional. Every sentence angles toward what you might need and what he might charge.</p>\n</blockquote>\n<p>He knows what’s moving, what it costs, and who is suddenly buying things they don’t normally buy. Where an economic signal should reach the party before a political one, Bellamy is the delivery mechanism.</p>\n<p><strong>Fellow Orderly Mattias Crowe</strong> <em>(Human, Male, 34 — Medical Corps)</em> ran the ward that kept them alive for a month. Not a brilliant physician and knows it. What he had was persistence, a good textbook, and six patients nobody could diagnose.</p>\n<blockquote>\n<p><strong>Voice:</strong> Nervous, earnest, faintly apologetic. Still visibly cannot believe it worked. Talks about the case the way people talk about the one time they were lucky.</p>\n</blockquote>\n<p>He will be <em>overwhelmed</em> to see them, not fawning, he simply spent a month turning six strangers every four hours and never expected to learn how the story ended. He kept notes. They are meticulous, because he was frightened the whole time and writing things down was the only way to stay calm.</p>\n<p><strong>What’s in the notes.</strong> Left open. This is a clean, unforced way to put physical evidence about the event into the party’s hands, five months of vitals, symptoms, and observations from the only person who watched it from the outside. Mattias produces them without hesitation and is relieved someone finally wants them.</p>\n<p><strong>Why they waited a month.</strong> He’ll explain plainly if asked: moving two deeply magical patients south, toward the noqual, while still unstable, was judged more dangerous than leaving them. He didn’t make the call, but he agreed with it, and he’ll say so.</p>"},{"name":"Overview: Elsewhere in Ottojikk","html":"<p><strong>The Marshalling Yard.</strong> Where everything changes trains. Loud, enormous, and the best place on the continent to find out what’s moving where and who’s paying for it.</p>\n<p><strong>The Six Roads.</strong> Ottojikk’s market, named for a crossroads that only has four. Factors from Sanguilum, Portovel Arterium, Cordevale and points much further out all keep stalls. Goods from all of them at a modest markup, plus a certain amount of genuinely exotic stock that arrived through a door rather than on a cart.</p>\n<p><strong>The Beheaded compound.</strong> School, small ward, liaison office. Modest of necessity as much as by design. The order does not govern here and does not pretend to. What it provides is service, and service is the whole strategy.</p>\n<p><strong>Imperial presence.</strong> Light, administrative, and mostly concerned with tariffs. A magistrate, a small customs staff, and the standing assumption that Ottojikk is Imperial because it has always been listed that way. Nobody in the Empire has looked closely at this town in some years, which is precisely why the order’s slow work is going as well as it is.</p>\n<blockquote>\n<p><strong>Why the doors work here at all.</strong> Worth knowing even if it never comes up: Ottojikk sits at the far end of the junction, a long way from the highlands. The noqual field is thin here. Closer to Venoqual the doors would be unreliable, and directly above the deposit they would not function at all, which is one reason there has never been a terminus in Sanguilum, whatever the official explanation says.</p>\n</blockquote>"},{"name":"Overview: If They’re Looking for Hek","html":"<p>They will be. Ottojikk is the only place on Sholtan with a confirmed connection to the party’s arrival, and the answer it gives is a hard one: <strong>he was never here.</strong> Six people came through the door. Six people were treated. The transit log shows the six and nobody else.</p>\n<p>The log moves the question rather than answering it. The party came through from an inn in Xandar, which means whatever carried them off the field set them down on the far side of an ocean, and the one person who saw them before the door shut is a man at an inn on another continent. Ilsabet Kroy will say exactly that, and will not speculate further, because she does not speculate about things she cannot measure.</p>\n<p>That’s not a dead end so much as a boundary. It rules out Sholtan as a search area, and the order cannot follow the question past that boundary, its reach ends at the southern triangle and everything it knows about Xandar arrives weeks late on a ship.</p>\n<p>What Ottojikk actually leaves the party with is a choice of two unsatisfying directions. <strong>Portovel Arterium</strong> is where anything out of Xandar lands first, which makes the docks the only live pipe on the continent and Ondrei, Ilyana, and Rill the three people standing on it. <strong>Ilsabet Kroy</strong> is the other, and the narrower one: she cannot say what moved them to Xandar, but she keeps the logs, knows the sister inn by its entries, and is the one person on this continent who can put a question through that door rather than onto a ship. Whether anyone on the far side answers is yours to decide.</p>\n<p>Neither answers the question. Both are honest about that, which is the tone the whole thread should keep.</p>"}]},{"name":"Part Four: The Southern Rail","pages":[{"name":"Overview","html":"<p>The order runs rail across its territory, connecting Sanguilum to its major holdings with a great many smaller stops between. Speed is roughly what a period railway would manage. What it does not do is halt every few hours to take on fuel and water. Beheaded engines run considerably longer between stops than they have any business doing, which is one of those Engineer Corps advantages the order shares cautiously and explains to nobody.</p>\n<blockquote>\n<p><strong>Left deliberately open.</strong> The exact power source is not specified here. Whatever it turns out to be, the effect is the same: fewer stops than the period would suggest, ordinary period speed, and the travel times below unchanged.</p>\n</blockquote>\n<h3>Boarding</h3>\n<blockquote>\n<p>Sanguilum’s terminus sits in the middle tiers, a long shed of iron and glass, and it is <em>loud</em>. Steam, iron on iron, a whistle somewhere down the platform, three hundred people all going somewhere. The train is longer than you expected, passenger carriages up front in dark red livery, then a string of freight, then more passenger at the back. No smoke stains on the roof, you notice. Whatever’s driving it burns clean.</p>\n<p>A conductor in a red scarf works down the platform checking passes. She reaches you, glances at the goat, glances at the pass, says “he rides in the vestibule or he rides in freight, your choice,” and moves on before anyone can argue.</p>\n</blockquote>\n<h3>The Line</h3>\n<table>\n<thead>\n<tr>\n<th><strong>Leg</strong></th>\n<th><strong>Distance</strong></th>\n<th><strong>Time</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Sanguilum → Venoqual</td>\n<td>1,545 mi</td>\n<td>2.2 to 3.6 days</td>\n</tr>\n<tr>\n<td>Venoqual → Cordevale</td>\n<td>1,958 mi</td>\n<td>2.7 to 4.5 days</td>\n</tr>\n<tr>\n<td>Cordevale → Portovel Arterium</td>\n<td>2,904 mi</td>\n<td>4 to 6.7 days</td>\n</tr>\n<tr>\n<td>Portovel Arterium → Vigilsylva</td>\n<td>2,571 mi</td>\n<td>3.5 to 6 days</td>\n</tr>\n<tr>\n<td><strong>Sanguilum → Portovel Arterium (through)</strong></td>\n<td><strong>4,579 mi</strong></td>\n<td><strong>6.3 to 10.5 days</strong></td>\n</tr>\n</tbody>\n</table>\n<p>Ottojikk sits on the junction where the Sanguilum line meets the Cordevale–Portovel Arterium line, roughly four to seven days out from the capital via Venoqual, and is the transfer point for anything heading east or west rather than north.</p>\n<p>Every mile of that track, both stations, and the trains themselves belong to the order. The Engineer Corps surveyed the routes, the order paid for the rails and laid them, and the order runs the timetable. Nothing on this network is chartered, leased, or shared. Anyone else who wants to move goods or people along it pays the published rate, and that includes the Imperial administration at Ottojikk.</p>\n<p><strong>By sea.</strong> The crossing from Sanguilum to the Shaadu coast is 1,500 miles, the least dangerous stretch of open water on the planet, which is a low bar rather than a reassurance. An order steamer makes it in 4 to 6 days and holds that time in either direction because it does not care which way the wind sits. Anything under sail is 8 to 12 days outbound and considerably worse coming back. Onward passage to Xandar runs through Shaadu and adds a further 2,800 miles of ocean, which is why everything the order hears from that continent arrives weeks late.</p>\n<p>A party riding the full line is looking at close to two weeks of continuous travel with dozens of minor stops, water towns, mining camps, farming hamlets, all with a lighter Beheaded presence and none needing a writeup. It is a long, believable stretch of downtime for character work, and it is also a very long train to stage something on.</p>\n<p>The engine crews, line mechanics and rail guards a party meets along the way are statted in the statblocks volume under <strong>The Rail</strong>: Fellow Engineman (3), Associate Line Mechanic (4) and Rail Armiger (5).</p>\n<h3>Rail Encounters</h3>\n<p>Roll d12 once or twice per leg, or pick. These work on any route and any train. Mix of combat, social, and strange by design.</p>\n<table>\n<thead>\n<tr>\n<th><strong>d12</strong></th>\n<th><strong>Encounter</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><strong>Herd on the line.</strong> Something large and non-hostile is standing on the track and will not move. The crew asks if anyone aboard is good with animals. Pipsy’s entire skill set, handed to her. Delay of two to six hours if nobody helps.</td>\n</tr>\n<tr>\n<td>2</td>\n<td><strong>The scholar.</strong> A Scholarly Corps Associate riding the same carriage notices something about one of the party, an archaism in how they speak, an ancestry rarely seen this far south, a technique they don’t recognize, and after an agonizing internal struggle works up the nerve to ask about it. Genuinely thrilled. No agenda.</td>\n</tr>\n<tr>\n<td>3</td>\n<td><strong>Fare dispute.</strong> A non-member family is being put off at the next stop over a paperwork error that isn’t their fault. The conductor is sympathetic and following procedure. Fixable with money, argument, or a Beheaded member vouching.</td>\n</tr>\n<tr>\n<td>4</td>\n<td><strong>Something on the roof.</strong> Two to four flying creatures have latched onto the carriages. Real combat, on a moving train, at speed. Falling off is the actual threat.</td>\n</tr>\n<tr>\n<td>5</td>\n<td><strong>The card game.</strong> Freight crew running a friendly game in the rear vestibule, and they’ll happily deal in anyone. Low stakes, high spirits. Flips will clean them out unless someone stops her.</td>\n</tr>\n<tr>\n<td>6</td>\n<td><strong>Signal failure.</strong> The train stops in open country. The crew needs to walk a mile up the line to a signal box and would rather not do it alone after dark.</td>\n</tr>\n<tr>\n<td>7</td>\n<td><strong>The recruit.</strong> A Beheaded Aspirant, eighteen and painfully earnest, is travelling to their first posting alone and terrified. Will attach to whoever is kindest. Asks the party questions about the world they are not remotely prepared to answer honestly.</td>\n</tr>\n<tr>\n<td>8</td>\n<td><strong>Sabotage, or not.</strong> A coupling has been cut between two freight cars. Could be wear, could be deliberate. The crew’s Engineer Corps mechanic is genuinely unsure and says so.</td>\n</tr>\n<tr>\n<td>9</td>\n<td><strong>The other passenger.</strong> Someone in the next compartment is quite obviously using magic to avoid being looked at directly. Not hostile. Not the party’s business. Very much against the spirit of what the party was told during their own orientation.</td>\n</tr>\n<tr>\n<td>10</td>\n<td><strong>Grade stall.</strong> A long climb, a heavy load, and the train slows to walking pace for two hours. Anything that can run alongside a walking horse can reach the train.</td>\n</tr>\n<tr>\n<td>11</td>\n<td><strong>The wake.</strong> A carriage has been given over to a Faith Militant detachment escorting a body home. They are quiet, courteous, and will make room for anyone who wants to sit with them. Nobody asks the party to.</td>\n</tr>\n<tr>\n<td>12</td>\n<td><strong>Nothing at all.</strong> Two days of open country, bad coffee, and each other’s company. Worth rolling more than once.</td>\n</tr>\n</tbody>\n</table>"}]},{"name":"Part Five: Venoqual","pages":[{"name":"Overview","html":"<p><em>Fortified mining town in the highlands, NW of Sanguilum. Population \\~4,500, almost entirely workers and garrison.</em></p>\n<blockquote>\n<p>The train climbs for most of a day out of Sanguilum. When it levels out you’re in high country, bare rock, thin air, and a river running fast and green alongside the track, going the other way.</p>\n<p>Venoqual announces itself with a checkpoint before you can see the town. Then a wall. Then the town: barracks, works buildings, lift housings, and above it all the terraced scar of the excavation itself cut into the mountainside, lit day and night. Something enormous and mechanical is moving up there on rails of its own. The river below is crowded with barges, all of them loaded, all of them heading downstream.</p>\n<p><strong>Before they arrive.</strong> Venoqual is the epicentre of the noqual field, and for Fern and Pipsy that is a physical fact rather than an atmosphere. The hum they’ve carried since waking gets substantially worse here. The town is fine. The shafts are not. Any Beheaded physician who understands what they are will say so plainly and without drama before letting either of them go below ground, and the nearest reference point the party has for what it would feel like is the farm incident. See <em>The Noqual Field</em> in Part One.</p>\n</blockquote>\n<p>Venoqual sits on the largest known deposit of noqual in the world. The crystalline, magic-resistant mineral that gives Sovereign Steel its properties when alloyed with cold iron. Noqual isn’t unique to the order’s territory; smaller pockets turn up elsewhere. But nothing found anywhere comes close to what runs beneath Venoqual, and the order’s engineers have never found the bottom of it.</p>\n<p>One of the continent’s great rivers, a system on the scale of a continent with branches of its own, rises far inland and cuts through these highlands on its way to the sea. It is about three hundred metres wide where it passes the town, fast and green, and it carries loaded barges all the way down to Sanguilum’s harbor. <strong>That is why Sanguilum sits where it does</strong>, a natural harbor at the mouth of the river that connects the capital directly to this deposit, and by one of its branches to the Cordevale valley. Ore still moves by water even now that rail is faster for people; for raw tonnage the river remains cheaper.</p>\n<p>The town is guarded more heavily than anywhere in Beheaded territory outside Sanguilum itself. The Engineer Corps runs a fleet of dedicated mining automatons built for excavation and hauling rather than combat, working the deeper shafts alongside the crews. Faith Militant presence is substantial and visible. Everyone here understands exactly what they’re protecting without needing it explained.</p>\n<p><strong>The crews are the most mixed workforce on the continent, and for a practical reason.</strong> Deep shaft work rewards ancestries the surface world tends to overlook. Dwarves are the largest single group and nobody is surprised by that. Beyond them: lizardfolk, who handle the heat and the wet at depth better than anyone; anadi, who are extraordinary in the vertical shafts; Nagaji, who tolerate the bad air; and a standing minority of jotunborn on the heaviest hauling, rare enough anywhere that seeing two in one shift is worth remarking on. The order pays all of them the same and houses all of them the same, which is not true of any Imperial operation on this continent and is the single most persuasive argument the Beheaded make out here.</p>\n<p>Nobody in Venoqual finds this arrangement notable. Elemir will see more Nagaji in a day here than in the whole of the campaign to date.</p>\n<h3>Points of Interest</h3>\n<p><strong>The Excavation Works.</strong> Graded shafts and lift platforms where the automatons do the heavy work under supervision.</p>\n<p><strong>Overseer Bruun Stonewell</strong> <em>(Dwarf, Male, 112 — Engineer Corps)</em> has run daily operations for three decades and treats Venoqual’s unbroken safety record as a point of professional pride bordering on religion.</p>\n<blockquote>\n<p><strong>Voice:</strong> Loud, proud, safety-obsessed. Will quote his record unprompted. Genuinely wounded if anyone suggests a shortcut.</p>\n</blockquote>\n<p>Director Rubble Copperglass treats Venoqual as something close to a personal project and visits often enough that Bruun keeps a guest room ready, which makes a familiar face available in an unexpected place.</p>\n<p><strong>The Assay House.</strong> Where raw noqual is weighed, graded, and either crated for the barges or sold outright to buyers with the coin and standing to purchase it.</p>\n<blockquote>\n<p><strong>Decide before the party gets here.</strong> Pipsy wears a moonlit seed in a glass vial that reacts unpredictably to magic and to nature. This building is where the purest anti-magic mineral in the world gets weighed in bulk. Whether the seed goes dark, goes still, goes frantic, or does nothing is genuinely open, but answer it deliberately, because a player will absolutely ask. The same question applies in miniature anywhere in Sanguilum, where noqual is common enough to be structural.</p>\n</blockquote>\n<p><strong>The rescue crews.</strong> Four to a crew, with a Medical Corps Fellow and a clockwork orderly, and on call at the head of every shaft. They are the people who go down after a fall, and they know every one of the party's likely ways into trouble underground. Statted in the statblocks volume as the Associate Mine Rescuer.</p>\n<p><strong>The Checkpoint.</strong> The single fortified road in, manned around the clock, impossible to approach unseen.</p>\n<p><strong>Knight Lieutenant Perrin Adair</strong> <em>(Hobgoblin, Male, 45 — Faith Militant)</em> runs it with procedural precision bordering on the theatrical. Every visitor logged, every wagon inspected, every exception noted in writing.</p>\n<blockquote>\n<p><strong>Voice:</strong> Formal, precise, unfailingly polite, never hurried. Treats a routine inspection as a matter of professional dignity.</p>\n</blockquote>\n<p>He isn’t unfriendly. He has simply never once in his career treated this posting as routine, and the party should not get through his checkpoint without a few pointed questions.</p>"}]},{"name":"Part Five and a Half: The Coppice and the Salt Coast","pages":[{"name":"Overview","html":"<p><em>Southern triangle, between Sanguilum and the sea. No town of any size. Roughly 12,000 order members spread across a hundred miles of managed woodland and a hundred more of shoreline.</em></p>\n<p>Neither of these places is a destination and both of them are the reason everything else works. If a player ever asks what Sanguilum burns, or how a valley a thousand miles inland cures its meat, this is the answer.</p>"},{"name":"The Coppice","html":"<p><strong>There is no coal on Sholtan.</strong> Not under the triangle, not under the plains, not anywhere the order has ever surveyed, and the Engineer Corps has surveyed a great deal. What the order runs its foundries, plate yards, traction engines and locomotives on is wood, converted.</p>\n<p>The plantation is managed woodland on a rotation, cut in sequence and regrown, worked the way the Agrarian Corps works anything. The cut timber goes into sealed iron retorts and is heated until everything but the carbon has been driven off, which produces a dense block that burns hot and clean and gives off white steam rather than black smoke. The order calls it hard char. Everyone else calls it Beheaded coal, which irritates the Engineer Corps for accuracy reasons and nobody else at all.</p>\n<blockquote>\n<p>Miles of it, in strips, and every strip a different age. Some of it is standing timber and some is knee-high regrowth and some is bare stumps with new shoots coming, and the pattern repeats to the horizon in a way that is obviously deliberate and takes a moment to read. There are no villages. There are camps, and a narrow-gauge line running between them, and a smell of woodsmoke that never entirely goes away.</p>\n<p>The retort works itself is a long shed with thirty iron vessels in a row, sealed, each with a condenser pipe running off into a collecting house. Nobody is shovelling anything. Two people are watching gauges.</p>\n</blockquote>\n<p><strong>Why this matters more than it sounds.</strong> Coal comes out of the ground in whatever quantity the seam holds. A plantation yields what it yields, on a rotation measured in years, across ground that does not get any larger. The order can improve its retorts and its furnaces forever and it cannot make the triangle bigger.</p>\n<p>So the order's entire industrial lead sits on a fuel supply with a hard ceiling, and its rival has no such ceiling, only no seam found yet. The Engineer Corps knows this precisely and does not discuss it outside the Corps. It is also why the order's warships have shorter legs than their hulls deserve: hard char carries less heat per ton than mineral coal, so the best ships on Devulat cannot go as far as worse ones, which is most of the reason the order cares so much about the crossing to Shaadu.</p>"},{"name":"The Salt Coast","html":"<p>Sanguilum sits on an equatorial southern coast with reliable sun, and salt is the thing that makes a fishery into food and a harvest into a reserve. The pans run in terraces along the shore east and west of the capital, shallow clay-lined beds that fill at high water and are closed off to evaporate, worked down through a series of levels until what is left is raked, dried and bagged.</p>\n<p>No fuel, no excavation, and nothing anyone needs to take on faith. The Agrarian Corps runs the pans, the Civil Corps weighs the output, and the whole operation is exactly the sort of thing the order likes to be seen doing.</p>\n<p><strong>Where the salt goes.</strong> Up the river, in the barges that brought the grain and the ore down, which go back upstream behind a tug and would otherwise go back empty. Cordevale takes its share off the valley branch and Venoqual off the main river, and what Vigilsylva needs goes north on the rail from Portovel Arterium. Cordevale cures its meat with it and Vigilsylva's fever wards run on it, and those two facts alone are why the valley's livestock counts as stored wealth and why the Watchline's month-long rotations can be provisioned at all.</p>\n<blockquote>\n<p><strong>The thing nobody has priced yet.</strong> The order now has the only reliable salt supply within thousands of miles, on rails it owns, and has never had to decide what that costs an outsider. Ottojikk pays the published freight rate and no more, because nobody in the Civil Corps has yet framed salt as anything other than a commodity. The first clerk to notice hands the order a lever it has no policy for, and there are no salt smugglers on Sholtan because there has never been a reason for one.</p>\n</blockquote>"},{"name":"Who the Order Has Here","html":"<table>\n<thead>\n<tr>\n<th><strong>Corps</strong></th>\n<th><strong>What they're doing here</strong></th>\n<th><strong>Rough numbers</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Natural</strong></td>\n<td>Rotation management, regrowth surveys, the plantation itself</td>\n<td>\\~3,000 across the coppice</td>\n</tr>\n<tr>\n<td><strong>Engineer</strong></td>\n<td>The retort works, the condensers, the narrow-gauge line, fuel trains</td>\n<td>\\~5,000</td>\n</tr>\n<tr>\n<td><strong>Agrarian</strong></td>\n<td>The pans, the drying floors, the harvest cycle on both</td>\n<td>\\~3,000</td>\n</tr>\n<tr>\n<td><strong>Civil</strong></td>\n<td>Weighing and recording output of both, and the freight ledgers</td>\n<td>\\~700</td>\n</tr>\n<tr>\n<td><strong>Faith Militant</strong></td>\n<td>Fire watch, more than anything else. A plantation is a fuel depot</td>\n<td>\\~300</td>\n</tr>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Two rotating clinics, burns and heat cases mostly</td>\n<td>4 or 5 at a time</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Playing it.</strong> There is nothing here to fight and no reason to come unless the party is asking the right question. What it is good for is a single scene that reframes the whole order: the most technologically advanced power on the planet, and its industrial base is a wood lot and a beach, worked by twelve thousand people, because it refused the one shortcut everybody else would have taken and then engineered its way around the refusal.</p>"}]},{"name":"Part Six: Cordevale","pages":[{"name":"Overview","html":"<p><em>Inland farming valley, NW of Venoqual. Town center \\~18,000; another \\~100,000 across the farmsteads it anchors.</em></p>\n<p>Cordevale is the order’s breadbasket and, arguably, its single greatest source of goodwill. Some twenty thousand farming families work it, and what the valley ships south feeds a little over forty percent of Sanguilum and a wide stretch of countryside besides. Most of it goes by water: a branch of the great river reaches the valley, and loaded barges run down it to the main river and on to the capital with the current doing the work. The rail carries people, machinery and whatever has to arrive on a date. The rest of the capital’s bread comes in by sea, which is a fact the order does not advertise and every Civil Corps clerk knows. A farmer with a full granary remembers that more readily than a threat that never reached him, which is why Cordevale has done more for the order’s standing with ordinary people than Vigilsylva’s protection ever has.</p>\n<blockquote>\n<p>Green, and then more green. The rail runs through the middle of a valley that goes on for longer than seems reasonable, wheat and barley in strips, orchards on the slopes, irrigation channels catching the light in long straight lines all the way to the hills. Every few miles there’s a farmstead. Every few farmsteads there’s a windmill.</p>\n<p>The passenger platform is one platform and a bell. A dozen people are waiting for the mail. Somebody’s dog is asleep on the boards and nobody seems inclined to move it.</p>\n<p>Then you look left, and the rest of the station keeps going. Six freight roads running side by side, a grain elevator four storeys high with chutes swung out over the hoppers, loading gangs working three trains at once, and a line of wagons queued back down the road waiting their turn at the scales. There is a whole second town over there and all of it is grain.</p>\n</blockquote>"},{"name":"Overview: Who the Order Has Here","html":"<p>Cordevale feeds a city. That makes it the most strategically valuable ground the order holds outside Venoqual, and the presence reflects it, but it is spread thin and pointed outward rather than concentrated in a compound.</p>\n<table>\n<thead>\n<tr>\n<th><strong>Corps</strong></th>\n<th><strong>What they’re doing here</strong></th>\n<th><strong>Rough numbers</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Agrarian</strong></td>\n<td>Advisory Cultivators attached to clusters of three or four farmsteads, living in those villages</td>\n<td>\\~200 across the valley</td>\n</tr>\n<tr>\n<td><strong>Faith Militant</strong></td>\n<td>Garrison on the granary complexes and the rail yards; refuge duty</td>\n<td>\\~600, five companies</td>\n</tr>\n<tr>\n<td><strong>Civil</strong></td>\n<td>Weighing, grading, recording, and tracking every ton that leaves</td>\n<td>\\~75 across the yards and elevators</td>\n</tr>\n<tr>\n<td><strong>Engineer</strong></td>\n<td>Machinists, elevator and pump maintenance, rail plant</td>\n<td>\\~12 plus trained locals</td>\n</tr>\n<tr>\n<td><strong>Natural</strong></td>\n<td>Working animals, draft teams, herding and ratting dogs, pest ecology</td>\n<td>\\~25, mostly itinerant</td>\n</tr>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Rotating physicians and the Fieldhouse clinics</td>\n<td>4 or 5 at a time</td>\n</tr>\n</tbody>\n</table>\n<p>That is a real institutional footprint, and the order is unambiguously the power in this valley. It holds the granary, the rail, the ledger, and the garrison, and everyone knows it.</p>\n<p><strong>What makes Cordevale feel different is the texture, not the reality.</strong> Sanguilum, Venoqual and Portovel Arterium are plainly order cities and read that way at a glance. Cordevale reads like a farmers’ collective that happens to have Beheaded in it. There is no compound at the centre of town, no administration anyone deals with daily, and the most visible order presence in most people’s lives is a Fellow they know by name who lives three farms over. The authority is real and almost never has to be exercised, which is exactly how the order prefers it.</p>\n<p><strong>The framing here matters more than anywhere else in the module.</strong> The Agrarian Cultivators do not own land, do not command anyone, take no share of any harvest, and have no authority to make a farmer do anything. They were invited, farmstead by farmstead, over roughly three generations, and any one of them can be told to go home tomorrow. A few have been. The order’s word for the role is <em>advisory</em>, and it is accurate.</p>\n<p>The garrison is a different arrangement and everyone understands the difference. It guards stored grain and it guards people, and it was asked for.</p>\n<p>What that looks like in practice is a Cultivator in harvest orange walking a field boundary beside the person who owns it, both of them looking at the same soil, and the Cultivator doing considerably more listening than talking. Farmers here argue with their Cultivators constantly and win about half the time. Play them as trusted specialists who happen to live down the road, never as inspectors.</p>\n<p>Nearly everyone in the valley is a non-member believer who has never seen Sanguilum and doesn’t expect to. This is the town that shows what the order looks like when it isn’t performing for anyone, including itself.</p>"},{"name":"Overview: The Machines","html":"<p>Cordevale is where the Engineer Corps’ work stops being abstract. The valley runs on equipment the rest of the world does not have, all of it mechanical and none of it enchanted.</p>\n<blockquote>\n<p>Something is working the far strip and it is enormous, a squat iron thing on wide iron wheels, throwing a thin column of clean smoke, dragging a cutting rig behind it that lays the barley down in a swath twenty feet wide. Two people are walking alongside it rather than riding, watching the rig. Behind them a dozen more are stacking. What would have taken that crew a week is going to take them an afternoon.</p>\n</blockquote>\n<p><strong>Be clear about the scale of this.</strong> The rest of the world farms the way it has for a thousand years: ox and plough, a scythe in every hand at harvest, grain threshed by flail on a barn floor. That is what the party has seen everywhere else they have ever been. Cordevale has steam traction engines pulling gang ploughs, mechanical reaper-binders that cut and tie in one pass, centralized threshing floors serving whole clusters of farms, powered pumps drawing off the irrigation channels, and seed drills that plant at consistent depth across an entire field.</p>\n<p>This is not an incremental advantage. It is several hundred years of difference standing in a barley field, and it is the single most visible demonstration of the order’s whole thesis anywhere in their territory, because none of it is enchanted, and every part of it can be explained to whoever asks.</p>\n<p><strong>Who owns it is the important part.</strong> The order could hold this as a monopoly. A single organization with the only working reaper-binders on the continent would have leverage over the food supply of an entire region, and every institution in history that has stumbled into that position has used it.</p>\n<p>They build the machines and sell or lend them at cost instead, and then teach people to run and repair them. Every cluster of farms has locals who can strip a thresher and rebuild it. The Engineer Corps machinists in the valley exist to handle what is beyond that and to train replacements, not to be indispensable. The order has been deliberate about this for generations, and will say why if asked: a valley that cannot feed itself without them is a valley they have made worse.</p>"},{"name":"Overview: Points of Interest","html":"<p><strong>The Fieldhouse.</strong> Schoolhouse, clinic, and Agrarian advisory post under one low wide roof built for muddy boots.</p>\n<p><strong>Proctor Cultivator Ysolde Penn</strong> <em>(Elf, Female, 96 — Agrarian Corps)</em> has spent her whole career in this valley and has twice asked not to be reassigned. She has turned down Senior Proctor more than once, on the grounds that it would put her in an office. Quietly brilliant with soil in a way that has nothing to do with rank. Walks a farmer’s fields with them rather than lecturing from an office.</p>\n<blockquote>\n<p><strong>Voice:</strong> Quiet, practical, physical. Explains things while crouched with a handful of dirt. Doesn’t do small talk well and knows it.</p>\n</blockquote>\n<p><strong>Proctor Cultivator Tamarisk</strong> <em>(Ghoran, 88 — Agrarian Corps)</em> has worked this valley longer than anyone alive here, which in a ghoran is not a figure of speech, Tamarisk remembers the soil before the irrigation channels went in and will tell you exactly how it has changed. Handles seed stock selection for the whole eastern half of the valley.</p>\n<blockquote>\n<p><strong>Voice:</strong> Unhurried to the point of being restful. Measures conversations in seasons. Refers to specific fields the way other people refer to old friends.</p>\n</blockquote>\n<p>Ghoran are not unusual in the Agrarian Corps. There are perhaps a dozen in Cordevale, and the reason is entirely practical: generational memory is worth more in agriculture than in almost any other discipline. Tamarisk can say what a given field yielded sixty years ago because Tamarisk was standing in it.</p>\n<p><strong>Proctor Machinist Odalie Krenn</strong> <em>(Gnome, Female, 61 — Engineer Corps)</em> keeps the valley’s traction engines and threshers running and has spent twenty years trying to make herself unnecessary. Runs a repair class every winter that anyone can attend.</p>\n<blockquote>\n<p><strong>Voice:</strong> Blunt, cheerful, covered in grease. Explains a machine by taking it apart in front of you.</p>\n</blockquote>\n<p>She is genuinely proud that most breakdowns in the valley now get fixed without her, and will say so at length. This is the order’s actual philosophy on display more clearly than any sermon.</p>\n<p><strong>Ostrid Vale</strong> <em>(Halfling, Female, 52 — not Beheaded)</em> farms the head of the valley and has no Fellow assigned to her land, because she no longer needs one. She learned everything the Agrarian Corps had to teach her, learned the machines from Odalie’s winter classes, and now runs one of the largest and best-yielding operations in Cordevale entirely on her own judgement.</p>\n<blockquote>\n<p><strong>Voice:</strong> Dry, direct, quietly confident. Explains things once and expects you to have listened.</p>\n</blockquote>\n<p><strong>She is what the order is actually trying to produce, and she is the argument in favour of everything they do out here.</strong> Farmers in the upper valley bring their problems to Ostrid now rather than sending for a Cultivator, which is precisely the outcome the Agrarian Corps has spent three generations working toward and precisely the outcome that costs them influence. They are delighted about it anyway. Ysolde consults her as a peer and says so.</p>\n<p>If the party wants to understand the order’s project without hearing it from a member, Ostrid is the person to ask. She takes no orders from them and will tell anyone who asks that they changed her family’s life and then got out of the way.</p>\n<p>She is also honest about the shape of it, if asked directly. Her seed comes from the order's stock. Her traction engine and reaper-binder are order-built and order-serviced. Her yield is weighed at the order's Counting House and travels out of the valley on the order's rail. She runs her land and nobody second-guesses her judgement, and she does all of it inside a system she does not own and could not replace. She does not consider that a grievance. She does consider it a fact, and she will say so plainly to anyone who asks her whether Cordevale is really the order's.</p>"},{"name":"Overview: The Granary Complex","html":"<p>The largest structure in the valley and the reason there is a garrison at all. Sixteen stone granaries and two elevators, walled, with the rail sidings running inside the wall rather than outside it. Grain moves from farm to scale to store to train without ever sitting unguarded.</p>\n<p>There are five smaller complexes on the same pattern spaced along the valley, each with its own wall, sidings and company. The main works handles the eastern half of the harvest on its own.</p>\n<p><strong>It is also a refuge, and the reason the smaller complexes exist at all.</strong> The walls are not there for the grain alone. Cordevale sits in open country with something near a hundred and twenty thousand people scattered across it, and if something comes down the valley the plan is not to defend every farm. It is to get everyone behind a wall inside a day, which is why there are six walls rather than one and why they sit where they do. Every complex is provisioned and laid out for it, drills happen twice a year, and every family in the valley knows which complex is theirs and which gate. Nobody enjoys the drills and everybody attends them.</p>\n<p>The drill is the largest peacetime movement of people anywhere in the order, and the Faith Militant treats it as the valley's real defensive asset. The garrison is not sized to hold the valley. It is sized to run the refuge and keep the granaries from burning.</p>\n<p><strong>Knight Captain Maribel Kosk</strong> <em>(Orc, Female, 44 — Faith Militant)</em> commands the valley garrison, five companies across six walled complexes, from an office at the main works rather than from the town centre. Deeply unglamorous posting, and she considers it the most important work in the order because a granary that burns kills more people than a monster ever will.</p>\n<blockquote>\n<p><strong>Voice:</strong> Practical, warm, and completely unimpressed by anything. Talks about fire suppression the way other officers talk about battle honours.</p>\n</blockquote>\n<p>Her actual enemies are fire, rot, theft, and vermin, roughly in that order. She has fought exactly two engagements in eleven years here and would happily never fight another.</p>"},{"name":"Overview: The Rail Yard","html":"<p>Six freight roads, the elevator, the scales, and a loading operation that runs from before dawn to after dark through harvest. This is where the valley’s output becomes Sanguilum’s food supply.</p>\n<p><strong>Proctor Clerk Aurel Nim</strong> <em>(Human, Male, 39 — Civil Corps)</em> runs weighing and records. Every ton that leaves this valley is weighed, graded, credited to a named farm, and entered in a ledger that Sanguilum audits annually.</p>\n<blockquote>\n<p><strong>Voice:</strong> Precise, friendly, faintly apologetic about the paperwork. Genuinely believes the ledger protects people, and is right.</p>\n</blockquote>\n<p>That ledger is the reason nobody in Cordevale worries about being cheated. A farmer can walk into the Counting House in Sanguilum a thousand miles away and be paid on a number recorded here by a man they know by name.</p>"},{"name":"Overview: The Kennels and Draft Yards","html":"<p>Attached to the granary complex, because the animals that work the grain are the same animals that protect it.</p>\n<p><strong>Proctor Warden Sesk Tallow</strong> <em>(Kholo, Male, 44 — Natural Corps)</em> handles the valley’s working animals: draft teams for the wagons and the non-mechanised farms, herding dogs, and above all the ratting dogs that keep the granaries from becoming a plague vector.</p>\n<blockquote>\n<p><strong>Voice:</strong> Few words, spoken slowly. Talks more to the dogs than to people and is better at it.</p>\n<p><strong>A note on who handles animals.</strong> The division used here is that <strong>Agrarian</strong> owns livestock as a crop, herds, yields, breeding for meat and milk, while <strong>Natural Corps</strong> handles working animals, their training, and the ecology around them, including pest control. The two Corps overlap constantly in Cordevale and neither seems to mind.</p>\n</blockquote>\n<p>Sesk is the natural counterpart for Gobbler and for Pipsy both, and Kitty will be assessed by a professional within about ninety seconds of arriving.</p>\n<p><strong>The Long Green.</strong> The market and gathering square, more grass than stalls most days, ringed by the Fieldhouse, the granary, and the tavern. Harvest turns it into the closest thing Cordevale has to a festival.</p>\n<p><strong>Bram Aldous</strong> <em>(Dwarf, Male, 141 — not Beheaded)</em> is the valley’s unofficial elder and owner of its largest orchard. Holds court here most evenings.</p>\n<blockquote>\n<p><strong>Voice:</strong> Slow, fond, repetitive. Tells the story about the Fellow who fixed the well two generations back every single time, with the same pauses.</p>\n</blockquote>\n<p>That story is worth letting him finish. It is the whole of the order’s strategy in one anecdote, told by someone who has no idea he is describing a strategy: somebody turned up, fixed a thing nobody else would fix, asked for nothing, and stayed. A hundred and forty years later the valley would fight for them.</p>\n<p><strong>The people in the square.</strong> Cordevale is less exotic than Venoqual and more mixed than a farming valley has any right to be. Humans are the largest group, then halflings and dwarves in roughly equal number, with a steady presence of elves and gnomes and the valley’s dozen-odd ghoran. The Fellows in harvest orange are as likely to be any of these as human. Nobody remarks on it, here least of all.</p>"}]},{"name":"Part Seven: Vigilsylva","pages":[{"name":"Overview","html":"<p><em>Frontier post against the northern forest. Far terminus of the line. Population \\~11,000. </em><em>Not a Beheaded town, a joint operation.</em>**</p>\n<blockquote>\n<p>The line runs north and the air changes before the country does. It gets heavier. By the time farms thin out you have stopped noticing individual smells and started noticing that everything smells like wet green growing things.</p>\n<p>Then the trees start, and they do not start gradually. A wall of them, and <em>tall</em>. The ones holding the canopy are two hundred feet if they’re a foot, with trunks you could build a house inside, and everything beneath them layered so thick that the treeline reads as a solid face rather than a boundary you could walk through. It runs east and west as far as the horizon in both directions and it is loud even from here. Birds, insects, and something further in that is neither.</p>\n<p>Vigilsylva sits with its back to that, on the river, in a cleared strip that people are visibly working to keep cleared. Watchtowers on stilts and stone every few hundred yards, all facing the same way. The town behind them is tight and practical and built high, stilts, steep roofs, everything a foot off the ground, nothing wooden touching soil.</p>\n<p>What you notice, once you’re inside it, is the uniforms. Forest green and red scarves, yes, but also Imperial colours on the next tower along, and a work crew coming off shift who are not human, not Beheaded, and clearly not taking orders from either. Three flags. One wall.</p>\n</blockquote>"},{"name":"Overview: The Arrangement","html":"<p><strong>Vigilsylva is the one place on the continent where the Beheaded, the Empire, and the monstrous peoples of the middle continent cooperate directly, and it works because none of them can hold the forest alone.</strong></p>\n<p>The order supplied the fortification designs and trains the officers. The Empire supplies materiel and a garrison of its own. The monstrous peoples supply the overwhelming majority of the actual bodies on the wall, because they live nearest to it and have the most to lose. Nobody commands the whole thing. Postings rotate roughly monthly, and the three parties coordinate rather than integrate.</p>\n<p><strong>It is not a warm alliance.</strong> It is three powers who dislike each other’s politics standing in a line facing the same direction. Imperial officers and Beheaded officers are professionally correct with one another and nothing more. The monstrous contingents deal with the Beheaded far more readily than with the Empire, for reasons that are not subtle: the order treats them as colleagues, and the Empire treats them as a treaty obligation living on substandard support.</p>\n<p>The party will notice that dynamic within an hour of arriving. Nobody will explain it to them, because everyone stationed here considers it too obvious to mention.</p>"},{"name":"Overview: What the Forest Actually Is","html":"<p>State this plainly, because it is not the forest anyone at the table is picturing.</p>\n<p>The northern reach is rainforest, hot, wet, and enormous, covering most of a continent. It is not dark woods with monsters in it. It is a living system so dense and so old that it does not need monsters to kill you, and the monsters are there anyway.</p>\n<p><strong>What makes it lethal, in rough order of how many people it has actually killed:</strong></p>\n<ul>\n<li><strong>Water and rot.</strong> Nothing dries. Boots rot, packs rot, wounds go bad in a day and a half. Half the deaths on record are infections that started as scratches.</li>\n<li><strong>Fever.</strong> Every expedition brings back illnesses the Medical Corps has to name after them. This is why Vigilsylva has a fever ward larger than its barracks infirmary.</li>\n<li><strong>Getting lost.</strong> Perpetual half-light under a canopy that never fully breaks, no horizon, no landmarks, and paths that close over within days of being cut. Compasses work; they are not the problem. Knowing where you are is not the same as knowing how to get back.</li>\n<li><strong>The small things.</strong> Insects in numbers that are difficult to convey, some of them dangerous on their own and many of them carrying something worse.</li>\n<li><strong>Then the large things.</strong> And there are a great many large things.</li>\n</ul>\n<p><strong>The rivers are the only real roads.</strong> Ground vehicles cannot operate and never will. Everything that moves in there moves on water or on foot, which is why Vigilsylva sits where the river meets the line and why boats matter more than wagons this far north.</p>\n<p>Both the Empire and the order have mounted large, well-resourced expeditions past the treeline over the decades. Every one has failed, and most failed without ever meeting anything hostile. Smaller and more careful parties fare considerably better, and still come back missing people more often than not. Even the order’s comm units lose signal a few hundred feet in.</p>"},{"name":"Overview: The Large Things","html":"<p>This is rumour and the garrison is honest about that, which makes it better material than certainty would.</p>\n<p>Trackers working the fringe bring back consistent reports of browse damage forty feet up, of trees pushed over rather than fallen, and of tracks in river mud that do not match anything the Scholarly Corps has catalogued. The descriptions that come back secondhand tend to agree on a few points, very large, reptilian, moving in groups, and unbothered by anything a patrol could bring to bear. Some of the older accounts use the word <em>lizard</em> and then immediately apologise for how inadequate it is.</p>\n<p><strong>Nobody has gone deep enough and come back to confirm any of it.</strong> That is the actual state of knowledge. The order’s position is that something large is in there, that the evidence is real, and that they do not know what it is. An Archivist in Sanguilum will tell the party exactly that and will not embellish.</p>\n<p>What is not in doubt is that the forest holds magical beasts well past anything the south has to deal with, and that the further in anyone goes the less reliably the ordinary rules seem to hold.</p>"},{"name":"Overview: Who Lives In It","html":"<p>The monstrous peoples of the middle continent live <em>at</em> the forest rather than inside it. Their settlements sit in the first belt, river margins, the more open ground where the canopy breaks, the fringe where a person can still see the sky. They know that belt better than anyone alive and have for a very long time.</p>\n<p>The peoples most associated with this country are <strong>tripkee</strong> in the wettest ground near the water, <strong>vanara</strong> in the canopy edge, and <strong>lizardfolk</strong> and <strong>anadi</strong> through the river margins, alongside a scattering of everyone else. Between them they supply most of the watchstanders on this stretch of the line.</p>\n<p>Past a certain depth they do not go either, and they are entirely matter-of-fact about why.</p>\n<p><strong>That distinction is worth protecting at the table.</strong> These are not jungle mystics holding secret knowledge of the interior. They are people who live next door to something enormous and have a practical, hard-won, generational understanding of exactly how far in is survivable and what the warning signs are. Ask one what is in the deep forest and the honest answer is that they do not know, have no plans to find out, and think anyone who does is being stupid about it.</p>\n<p><strong>People do live in there.</strong> The monstrous peoples who supply most of the Watchline hold territory inside the forest edge, and they are not living deeper in it than anyone else. They are living at the margin, competently, the way people live on the edge of any hostile country. Nobody holds the deep forest. The distinction matters, and getting it wrong is how outsiders end up insulting people they need.</p>"},{"name":"Overview: The Watchline","html":"<p>The fortified boundary Vigilsylva sits on runs roughly four thousand two hundred miles. It was never meant to be a solid wall. That isn’t remotely possible at this scale, and it isn’t one. Long stretches are deliberately left open, corridors the forest peoples and other non-hostile races use to move and trade without passing a checkpoint. What actually exists is a chain of posts staffed on roughly month-long rotations, watching the stretches that matter rather than the whole boundary at once.</p>\n<p>No single power holds it. The order supplied the designs and trains officers, the Empire contributes materiel and garrisons, and the local and monstrous peoples who live nearest the boundary supply most of the actual watchstanders. A four-thousand-mile line was never something any one of them could hold alone, which is precisely why it is the one thing they have all agreed to do together.</p>\n<blockquote>\n<p><strong>DM note.</strong> The Watchline gets the credit for the south’s safety. It deserves some of it. But the reason the deep south around Sanguilum is as quiet as it is has more to do with what’s buried under Venoqual than with anything the garrison does. Nobody here knows that, including the garrison.</p>\n</blockquote>"},{"name":"Overview: Points of Interest","html":"<p><strong>The Watchline at Vigilsylva.</strong> Towers and cleared ground, manned around the clock by all three parties in rotation, and the most heavily fortified stretch of the entire boundary.</p>\n<p><strong>Sentinel Darro Ashfen</strong> <em>(Lizardfolk, Male, 51 — Faith Militant)</em> has made this posting his own and turned down promotion more than once to stay.</p>\n<blockquote>\n<p><strong>Voice:</strong> Very few words, long pauses before each. Never small talk. When he does speak at length it’s about the forest, and everyone stops to listen.</p>\n</blockquote>\n<p><strong>What he’s for.</strong> The commanding officer defers to him when something in the treeline looks wrong, regardless of what the insignia say. He has read that boundary for twenty years and is right often enough that nobody argues.</p>\n<p><strong>Why he matters politically.</strong> A lizardfolk wearing the red scarf is the one figure in Vigilsylva that all three parties will actually listen to, Beheaded because he is one of theirs, the contingents because he is one of theirs, and the Empire because he is demonstrably the best reader of the forest on the wall. He did not ask for that role and does not enjoy it, and he will hand a negotiation off to someone else the moment it becomes possible.</p>\n<p><strong>What happened to him.</strong> His people were worn away by a fey incursion the order reached late enough to only partly stop. He has spent every year since studying what took his home well enough to make sure it cannot take anyone else’s. He does not discuss it. If a guest jokes about mind-affecting magic in his hearing he simply stops talking and does not start again, which is considerably worse than being argued with.</p>"},{"name":"Overview: The Fever House","html":"<p>The Medical Corps hospital, and the largest single building in Vigilsylva, bigger than the barracks infirmary, bigger than the Imperial depot. That is not an accident of planning. The forest kills more people here with rot and fever than with teeth, and everyone stationed on this wall knows it.</p>\n<p>Long open wards, high louvred windows, mosquito netting on everything, and a smell of antiseptic that never fully covers the smell of the river. It treats all three parties without distinction and always has. The Imperial garrison’s own surgeon refers cases here, which is the single clearest evidence that whatever the politics are, they stop at the door.</p>\n<p><strong>Associate Chirurgeon Vashti Rell</strong> <em>(Nagaji, Female, 96 — Medical Corps)</em> runs it. Ninety-six years in and she has named four diseases, which she considers a professional embarrassment rather than an achievement, because naming a thing is what you do when you cannot cure it.</p>\n<blockquote>\n<p><strong>Voice:</strong> Direct, tired, and very hard to alarm. Delivers appalling news in the same tone as the weather.</p>\n</blockquote>\n<p>She is the right person for anything involving what the forest does to a body, and she will talk shop with Bael instantly and at length. She is also the only person in town who can tell the party, from records, roughly how many people the deep forest has actually killed and how few of those deaths involved anything hunting them.</p>"},{"name":"Overview: The Landing","html":"<p>Vigilsylva sits where the river meets the line, and the landing is where the two connect. Flat-bottomed boats, a crane, a customs shed, and the loading ground where anything coming out of the forest is transferred to rail.</p>\n<p>Rivers are the only roads past the treeline, so this is the actual gateway north, not the wall. Everything and everyone that goes in or comes out does it from these steps.</p>"},{"name":"Overview: The Depot","html":"<p>The joint supply yard, where the three-way arrangement is most visible and least comfortable. Beheaded stores on one side, Imperial on the other, and the contingents’ allocation in the middle, drawn from both and never quite enough.</p>\n<p><strong>Captain Verel Ashcombe</strong> <em>(Elf, Female, 180 — Imperial Army)</em> commands the Imperial garrison. She is not a villain and playing her as one wastes her. She is a competent professional soldier running an under-resourced posting four thousand miles from anyone who could help, and she is entirely aware that the order does her job better than she does because they are permitted to actually spend money on it.</p>\n<blockquote>\n<p><strong>Voice:</strong> Clipped, correct, formal to the point of coldness. Thaws slightly around anyone who is good at their job.</p>\n</blockquote>\n<p>Her relationship with the Beheaded officers is professionally impeccable and personally nonexistent. Her relationship with the contingents is worse, and she knows it, and she cannot fix it because the terms are set several thousand miles away by people who have never been here. Ask her about it directly and you will get a long pause and then a change of subject, not because she disagrees with the criticism, but because agreeing with it out loud would end her career.</p>\n<p><strong>Yeleth Vaar</strong> <em>(Anadi, Female, 73 — the contingents)</em> speaks for the monstrous peoples’ watchstanders. Her title is <em>Wall-Speaker</em>, which is a role rather than a rank; she was chosen for it and can be un-chosen.</p>\n<blockquote>\n<p><strong>Voice:</strong> Warm, blunt, and completely unimpressed by hierarchy. Says the thing everyone is avoiding, then waits.</p>\n</blockquote>\n<p>Roughly two-thirds of the bodies on this wall are hers, and she negotiates their supply, rotation, and treatment with both other powers. She gets considerably further with the order than with the Empire and will tell the party exactly why in about one sentence. She has known Darro for fifteen years and the two of them do most of the real coordination in a back room over food, after the formal meeting has produced nothing.</p>\n<p><strong>The Green Market.</strong> Where forest goods change hands, hardwoods, resins, medicinal bark, river fish, dyes, and animals nobody in the south has a name for. Run by the fringe peoples, priced by them, and the one place in Vigilsylva where the contingents are unambiguously in charge.</p>\n<p><strong>The Hunters’ Rest.</strong> A lodge just inside the wall where garrison scouts and independent trackers drink in the same room without much distinction between them.</p>\n<p><strong>Coen Vask</strong> <em>(Half-Elf, Male, 41 — not Beheaded)</em> is the person the garrison calls when a patrol needs to go <em>past</em> the treeline rather than along it. That distinction matters enormously. He has taken experienced Beheaded patrols in and brought them back out, repeatedly, with enough of them breathing that the garrison’s respect for him is not remotely casual.</p>\n<blockquote>\n<p><strong>Voice:</strong> Flat, dry, direct. Answers exactly the question asked and nothing more. Not unfriendly, economical.</p>\n</blockquote>\n<p><strong>Why he won’t take their coin.</strong> He’ll tell anyone who asks. Twenty-some years ago his young daughter was hurt badly enough by something out of the treeline that the local healer had nothing for it. A Beheaded medical detachment, stationed here long before Coen was born, reached her in time. They didn’t know her and had no reason to; they’d have done the same for any stranger’s child. He watched an organization he had every reason to be wary of act with total, uncomplicated decency toward someone who was nothing to them, and he’s spent every year since making sure the people who do that work come back out of his forest alive.</p>\n<p>His daughter is grown now, still living in Vigilsylva. He’s turned down more than one genuine offer to enlist. What he pays out isn’t loyalty to an institution. It’s a debt to specific people, settled patrol by patrol, on his own terms. It also means he can refuse a job his instincts tell him not to take. A member can’t, and he’s watched that cost people.</p>\n<p><strong>What makes him different from the fringe peoples.</strong> Yeleth’s people know the first belt better than anyone alive and stop where their generational knowledge stops, which is sensible and which is why they are still alive. Coen goes further in than that, deliberately, and has built two decades of hard-won route knowledge in ground the contingents consider nobody’s business. That is precisely why the garrison needs him and precisely why Yeleth thinks he is reckless. The two of them are perfectly cordial and neither has ever persuaded the other of anything.</p>\n<p>He is exactly the kind of professional peer Gobbler would recognize on sight, not an equal to be polite to, but someone whose skill is worth measuring himself against.</p>"}]},{"name":"Part Eight: Portovel Arterium","pages":[{"name":"Overview","html":"<p><em>Eastern coast, roughly 4,600 rail miles north of Sanguilum. Population \\~24,000.</em></p>\n<p><strong>Portovel Arterium is a Beheaded city, without qualification.</strong> The order built the harbour works, runs the customs house, staffs the clinic and the school, and is the plain and undisputed authority here. Nobody in this town is confused about who is in charge, and nobody resents it much either. Most of the population have never taken a vow and never will, but they live in an order city and know it.</p>\n<p>What makes it different from Sanguilum is what comes through it.</p>\n<p><strong>Portovel Arterium is where people arrive.</strong> Anyone crossing from Xandar takes the narrow neck of Shaadu and catches a second ship east, and this is where that ship puts in, not because it is the closest harbour but because it is the <em>useful</em> one. Portovel sits far enough up the coast to be central to the continent, which means from these docks a traveller can be on the rail to Ottojikk, Cordevale, or Vigilsylva the same week. Sanguilum sits at the southern tip and is a terminus; you go there because you are going <em>there</em>.</p>\n<p>So this is the passenger port, the general-cargo port, and the news port. Finished goods, foodstuffs, textiles, livestock, mail, rumour, and people. Every scrap of information out of Xandar lands on this dock weeks before Sanguilum hears a cleaned-up version of it.</p>\n<blockquote>\n<p><strong>What does <em>not</em> come through here.</strong> Bulk adamantine and the heavy Shaadu ore trade go to Sanguilum, which is several hundred miles closer to the Shaadu coast and is where the foundries are anyway. Raw material sails south. People and general trade come here.</p>\n</blockquote>"},{"name":"Overview: Arriving by Rail","html":"<blockquote>\n<p>The line comes down out of the hills and the sea opens up on your right, and it keeps opening, and then the land folds inward and you’re running along the edge of the bay. Portovel Arterium sits in the crook of it, a working harbor, all timber and tar and grey stone, with maybe forty ships at anchor and twice that many small boats working between them. Gulls everywhere. The smell reaches the carriages before the station does: salt, fish, hot pitch, coal smoke.</p>\n<p>Something else reaches you too, or rather stops reaching you. The pressure you’ve been carrying since you woke, that low wrongness under everything, is <em>thinner</em> here. Not gone. Thinner. You are a very long way from the highlands now.</p>\n<p>Beyond the docks the town climbs the slope in tiers. Somewhere up there a bell rings twice, unhurried, and a few dozen children spill out of a low stone building and go tearing down the street.</p>\n</blockquote>"},{"name":"Overview: The Docks","html":"<p><strong>Harbormaster Ondrei Kolt</strong> <em>(Tengu, Male, 58 — not Beheaded)</em> runs the harbor and has for nineteen years. He is perpetually mid-task, will conduct an entire conversation while walking away mid-sentence, and knows exactly which ship is carrying what.</p>\n<blockquote>\n<p><strong>Voice:</strong> Fast, clipped, never fully stops moving. “Right, right, no, <em>that</em> one goes to bay four. Sorry. You were saying?”</p>\n</blockquote>\n<p><strong>He is not a member and never has been</strong>, which in an order city running an order harbour is worth a sentence of explanation. Nineteen years ago the Engineer Corps needed a harbormaster and Ondrei was the best one on this coast. That was the entire deliberation. Nobody asked him about his faith then and nobody has since, and he is paid and empowered exactly as a member in the same post would be.</p>\n<p>He gets mildly irritated when travellers assume he took a vow, and considerably more irritated when they imply he must have. The order finds his irritation reasonable and has never once pressed him on it.</p>\n<p>He is the right person for: what ships are in, what’s leaving, who’s been asking questions, and any rumor that arrived by sea in the last week.</p>\n<p><strong>What’s in the harbor is worth describing.</strong> Imperial vessels are conventional hulls carrying assigned battle-mages, because that is how the Empire crosses four thousand miles of monster-infested water. Beheaded vessels cannot do that and have gone the other way entirely: armoured hulls, iron plate, and progressively heavier guns, on the theory that a sea beast can be shot even if it cannot be warded. The newest ships in the order’s berths look less like merchantmen than like something built for a war nobody has declared yet, and the arms race between the two approaches is visibly ongoing.</p>"},{"name":"Overview: Customs","html":"<p>Every arrival by sea is processed at a plain building at the head of the docks. The party came in by rail and won’t go through it themselves, but it’s the best place to watch the order’s guest procedure applied to someone else, and to see how completely routine it is.</p>\n<p><strong>Knight Ilyana Marsh</strong> <em>(Gnome, Female, 52 — Faith Militant)</em> runs it. Easygoing, chatty, apparently unbothered. She has an actual talent for reading a person the moment they step off a gangplank, and travellers consistently underestimate how little she misses.</p>\n<blockquote>\n<p><strong>Voice:</strong> Warm and conversational. Delivers the serious questions in exactly the same tone as “how was the crossing?”</p>\n</blockquote>\n<p><strong>The two questions.</strong> Every visitor gets both, in a flat, friendly, faintly bored tone. Neither is a challenge. She’s done this four hundred times this month. <em>Can you work magic, and roughly what can you do?</em>. Nobody wants a spell list, a general sense is the whole point. And <em>what are you carrying?</em>, everything declared, everything expected to stay holstered, sheathed, or cased.</p>\n<p>Then passes, a printed map, and the next name. It is the same content the party had read to them over tea months ago, delivered here in ninety seconds to a queue of sailors.</p>\n<p>If any of them want to talk to her, she’s happy to. She’ll recognize the red scarf immediately and treat Bael as a colleague, and she has the specific gift of asking a genuinely searching question in exactly the tone of small talk.</p>"},{"name":"Overview: Portovel Arterium: Points of Interest","html":"<p><strong>Tidewarden Ashek-Vel</strong> <em>(Azarketi, Male, 48 — Engineer Corps)</em> handles hull inspection and underwater repair for the order’s berths, which he does by going down and looking at them. Azarketi are a northern-shoreline people the south rarely sees, and Ashek-Vel took the scarf because the order was the only institution on the continent that responded to his existence by asking what he could do rather than what he was.</p>\n<blockquote>\n<p><strong>Voice:</strong> Blunt to the point of rudeness, entirely without malice. Says the shortest true thing and stops.</p>\n</blockquote>\n<p>He is the right NPC for anything involving the harbor floor, the ironclad programme, or what has been washing up lately. He also has strong and unsolicited opinions about the order’s newer armoured hulls, most of them critical.</p>"},{"name":"Overview: The Refit Yard","html":"<p><strong>The order’s warships are built in Sanguilum.</strong> That is where the foundries, the ore, the armour plate and the gun works are, and nothing here competes with it. What Portovel Arterium has is the dry dock those ships come back to.</p>\n<p>Two graving docks cut into the headland, a boiler shop, and a plate yard, running six days a week. Every armoured hull the order operates on this coast comes here to be opened up, assessed, and put back together, and that gives this yard something Sanguilum does not have: it is where the order finds out what the ocean actually does to its designs.</p>\n<p><strong>The problem the ships exist to solve.</strong> Four thousand miles of open water separates Sholtan from anywhere that matters, and that water holds things large enough to take a ship apart. The Empire’s answer is a battle-mage on every deck. The order does not have that option and never will, so Sanguilum builds hulls that do not need one, iron plate over timber, compartmented below the waterline, guns heavy enough that the theory holds. A sea beast can be shot even if it cannot be warded.</p>\n<p><strong>Whether the theory holds is genuinely unsettled, and this is the yard that would know.</strong> Two of these ships have been lost. The programme continues because the alternative is conceding the ocean, and the order has never once conceded anything on the grounds that it was difficult.</p>\n<blockquote>\n<p>The graving dock is drained and there is a ship sitting in it that does not look like a ship, no masts to speak of, a hull sheathed in overlapping iron plate, a low armoured house amidships with gun ports cut into it. A section of that plate has been unbolted and laid out on the stones, and the timber underneath is stove in over about fifteen feet. People are standing around the gap arguing. Sparks are coming off the hull in three places at once and the hammering is physical.</p>\n</blockquote>\n<p><strong>Proctor Ordnancer Hadria Volk</strong> <em>(Dwarf, Female, 118 — Engineer Corps)</em> runs the yard’s assessment work and, in practice, its design arguments. Thirty years on the question of how much armour a hull can carry before it stops being a hull, and every one of her findings goes south to Sanguilum, where the yards may or may not act on it.</p>\n<blockquote>\n<p><strong>Voice:</strong> Loud, direct, and openly delighted by her own work. Assumes anyone she’s talking to is interested, and is usually right.</p>\n</blockquote>\n<p>She will show the party anything they want to see and explain all of it, because the order has no secrets here that a shipwright couldn’t work out from a drawing. She will not sell them anything, and she will say so cheerfully and without apology.</p>\n<p><strong>The tension worth playing.</strong> Hadria and Ashek-Vel have disagreed about the current hull design for four years, and they are the two people best placed to know. She reads the damage from above, with the plate off and the frames exposed, and thinks the armour is where the survival margin comes from. He goes down and reads the same hulls in the water, and thinks she is defending ships that sink beautifully. Their reports go to Sanguilum separately and contradict each other, which everyone finds tiresome except the two of them. Both would like a third opinion, and a party with a well-read engineer or a decent Crafting check is exactly that.</p>\n<p><strong>The Tidewatch House.</strong> Schoolhouse and clinic under one roof, squat and sturdy, smelling of brine and antiseptic in equal measure. Free on fever days.</p>\n<p><strong>Associate Chirurgeon Perpetua Vance</strong> <em>(Half-Elf, Female, 58 — Medical Corps)</em> runs both halves without apparent effort. Mornings are fishhook wounds and split knuckles; afternoons are a room of children and adults learning to read. She’s been here longer than the current harbor watch has existed and delivered a meaningful fraction of the town’s population herself.</p>\n<blockquote>\n<p><strong>Voice:</strong> Unhurried, motherly, faintly bossy. Calls everyone “love.” Will interrupt a serious conversation to tell someone to sit down and let her look at that.</p>\n</blockquote>\n<p>She will clock Bael as Medical Corps within a sentence and treat him as a colleague immediately, which, for a man walking back into his order’s territory with a pack of outsiders, is a quietly enormous thing to receive from a stranger.</p>\n<p><strong>She is one of the two NPCs in this module carrying something personal.</strong> Twenty years ago she delivered a child to a woman who had been charmed into a marriage she had not chosen and could not explain to anyone, including herself. Perpetua has never told that story to a stranger and will not tell it now.</p>\n<p>It surfaces in exactly one way. If someone at her table treats enchantment as a clever tactic, the warmth drops out of her voice for a single sentence and then comes straight back, and she changes the subject herself before anyone else can. She does not argue. She does not lecture, and she will be just as kind to that person five minutes later. Play it once and do not explain it.</p>\n<p><strong>The Drowned Bell.</strong> A dockside tavern and inn, entirely unaffiliated with the order and proud of it.</p>\n<p><strong>“Old Rill” Kestrel</strong> <em>(Minotaur, Male, 74 — not Beheaded)</em> keeps it running on secondhand gossip and cheap ale. Forty years at sea, horns worn smooth from ducking through low doorways, more stories than teeth.</p>\n<blockquote>\n<p><strong>Voice:</strong> Booming and digressive. Gets three stories deep before answering the question. Every story features a ship that no longer exists.</p>\n</blockquote>\n<p>He’s the release valve for anything that hasn’t reached official channels. If you need the party to hear a rumor the order wouldn’t volunteer, it comes from this bar.</p>"},{"name":"Overview: What Is Coming Off the Ships","html":"<p>This is the reason to bring the party here, and it should not be an empty shelf. Whatever is happening in Xandar, its edges wash up on this dock first, weeks before Sanguilum hears a cleaned-up version.</p>\n<p><strong>The general shape of it, which nobody has to dig for:</strong></p>\n<ul>\n<li><strong>Sailings are being cancelled.</strong> Not by the order and not by any authority, by captains, individually, who have decided a route is no longer worth it. The cancellations have been increasing for months and no two captains give the same reason.</li>\n<li><strong>The crossing is taking longer.</strong> Ships that used to make the Shaadu neck on a reliable schedule are arriving late, arriving light, or arriving with fewer crew than they left with.</li>\n<li><strong>People are arriving with nothing.</strong> Not a flood, and not organized. A few dozen a month, off ordinary passenger berths, who paid everything they had for a ticket east and have no plan past the gangplank. The Tidewatch House has been quietly absorbing them.</li>\n<li><strong>Cargo is getting strange.</strong> Shipments arriving unaccompanied, consignees who never turn up, and an increase in things being shipped <em>away</em> from Xandar by people who clearly do not expect to follow them.</li>\n</ul>\n<p><strong>Who gives the party what:</strong></p>\n<table>\n<thead>\n<tr>\n<th><strong>Source</strong></th>\n<th><strong>What they have</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Ondrei Kolt</strong></td>\n<td>Hard facts. What came in, from where, how late, how heavy, and which berths have been empty for months. He does not speculate and gets irritated by people who do.</td>\n</tr>\n<tr>\n<td><strong>Knight Ilyana Marsh</strong></td>\n<td>The customs ledgers, and the people. Who came in, what they declared, what they were carrying, and which arrivals struck her as wrong. She notices a great deal she does not write down.</td>\n</tr>\n<tr>\n<td><strong>Perpetua Vance</strong></td>\n<td>Who is sick, who is hurt, and what the people arriving with nothing have said to her while she was stitching them up. She will not repeat anything a patient told her in confidence, and she will tell the party exactly where that line is.</td>\n</tr>\n<tr>\n<td><strong>“Old Rill” Kestrel</strong></td>\n<td>Everything the other three won’t say. Rumour, exaggeration, three stories deep, and roughly a third of it true.</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><strong>A note on how the order handles this.</strong> Nobody is being turned away. Nobody is being processed into a camp, and nobody is being recruited. Arrivals with nothing get fed, treated, taught if they want it, and left alone. Ilyana logs them and that is the end of the paperwork. If the party is waiting for the catch, there isn’t one, and their inability to find it should be mildly unsettling.</p>\n</blockquote>"},{"name":"Overview: Onward","html":"<p>Portovel Arterium is the end of the through line but not the end of the network, Vigilsylva is another three and a half to six days further north, and the east–west line back through Ottojikk runs from here as well.</p>\n<p>If the party came here for word of Keh, this is the only place on the continent where that question has any traction at all, not because anyone here knows anything, but because everything that leaves Xandar passes through this harbour eventually.</p>"}]},{"name":"Appendix A: NPC Statblocks","pages":[{"name":"Appendix A: NPC Statblocks","html":"<p>The NPC stat blocks are imported as actors by the Beheaded NPC Import macro, in the <b>The Beheaded</b> actor folder under <b>Sholtan Module NPCs</b>. Open them there rather than reading them here, so the numbers you roll are the numbers on the sheet.</p><ul><li>Fellow Orderly Mattias Crowe</li><li>Innkeeper Hessa Varr</li><li>Doorwarden Ilsabet Kroy</li><li>Proctor Liaison Corbin Ashe</li><li>Factor Bellamy Orr</li><li>Associate Chirurgeon Vashti Rell</li><li>Captain Verel Ashcombe</li><li>Yeleth Vaar</li><li>Knight Captain Maribel Kosk</li><li>Proctor Clerk Aurel Nim</li><li>Proctor Warden Sesk Tallow</li><li>Proctor Cultivator Tamarisk</li><li>Proctor Machinist Odalie Krenn</li><li>Ostrid Vale</li><li>Proctor Ordnancer Hadria Volk</li><li>Archivist Sesh Nemeth</li><li>Cultivator Oleander</li><li>Tidewarden Ashek-Vel</li><li>Harbormaster Ondrei Kolt</li><li>Chair Nathaniel Bael</li><li>Penitent Confessor Zacchaeus</li><li>Knight Lieutenant Torvis Amsel</li><li>Instructor Callo Verrienne</li><li>Associate Chirurgeon Perpetua Vance</li><li>Knight Ilyana Marsh</li><li>\"Old Rill\" Kestrel</li><li>Proctor Cultivator Ysolde Penn</li><li>Bram Aldous</li><li>Coen Vask</li><li>Overseer Bruun Stonewell</li><li>Knight Lieutenant Perrin Adair</li></ul>"}]},{"name":"Appendix B: Goods and Prices","pages":[{"name":"Overview","html":"<p>Everything the order sells to outsiders, what it does, and what it costs. Every item here is Analog and non-magical by the setting’s core rule. Nothing accepts a rune, nothing is a weapon beyond what anyone could already buy, and nothing does anything a careful person with good materials couldn’t explain.</p>\n<p>The order's technology is late-19th-century in register and steampunk, solarpunk and davincipunk in execution, so pseudo-scientific is fine and supernatural is not. Anything on these lists can be taken apart on a bench and explained to whoever asks. Nothing here is extradimensional and nothing heals by intention rather than by chemistry. An instrument that measures, reveals or physically settles something magical is still an instrument, and the order sells several.</p>\n<p>The <strong>Source</strong> line tracks any item renamed or reflavored from a published listing so the original can be found quickly. Items marked <em>estimated</em> have no clean published equivalent and were priced on the same tier as their neighbours. Items marked <em>ordinary trade goods</em> were never technology to begin with.</p>\n<p>Technological items are priced from their SF2e credit values in Player Core and Tech Core, converted at 1 credit = 1 sp.</p>\n<blockquote>\n<p>This appendix also exists as a standalone document, <strong>The Beheaded: Goods and Prices</strong>, which can be handed to players directly. Removing the Source lines turns it into a clean player-facing price list.</p>\n</blockquote>"},{"name":"Medical Corps","html":"<p><strong>Field Remedy Case</strong> — 5 gp; Bulk 1; Hands 2\n<em>Source: Medkit (SF2e)</em></p>\n<p>A civilian-grade kit of analgesics, bandages, sterile gauze and suturing tools. The standard commercial case the order equips every traveler's clinic with, and the most widely distributed thing the Beheaded make.</p>\n<p><strong>Effect:</strong> Functions as a healer's toolkit. Required to Treat Wounds, Treat Disease, Treat Poison or Administer First Aid without penalty.</p>\n<p><strong>Advanced Field Kit</strong> — 50 gp; Bulk 1; Hands 2\n<em>Source: Advanced Medkit (SF2e)</em></p>\n<p>The professional-grade version. Better organized, better instruments, noticeably more effective in hands that know what to do with it.</p>\n<p><strong>Effect:</strong> Functions as an expanded healer's toolkit and grants a <strong>+1 item bonus</strong> to Medicine checks made with it.</p>\n<p><strong>Antiseptic Wash</strong> — 3 sp; Bulk L; 4 doses\n<em>Source: estimated</em></p>\n<p>A carbolic-based solution in a stoppered bottle. One of the order's earliest medical exports and the reason Beheaded field hospitals lose fewer patients after surgery than anyone else's.</p>\n<p><strong>Effect:</strong> Spend one dose while treating an open wound with a successful Medicine check. The patient gains a <strong>+2 item bonus to Fortitude saves against disease and infection</strong> arising from that wound for 24 hours. On a critical success when using the wash to Treat Disease, reduce the disease's stage by an additional step.</p>\n<p><strong>Hypo-Injector Kit</strong> — 1 gp 5 sp; Bulk L; Hands 1\n<em>Source: estimated</em></p>\n<p>A reusable brass injector with interchangeable needles, for administering tinctures and remedies with far more accuracy than a dropper allows.</p>\n<p><strong>Effect:</strong> Administer an elixir or similar consumable to an adjacent willing or unconscious creature as a <strong>single action</strong> rather than two. Cannot be used on an unwilling target.</p>\n<p><strong>Medicated Patch</strong> — 4 gp (lesser), 25 gp (moderate); Bulk L; one use\n<em>Source: Medpatch (SF2e)</em></p>\n<p>A sterile adhesive pad loaded with coagulants, analgesics and cultured biological matter, sealed in waxed paper. Slap it on and it does the work. No skill required and nothing about it is magical, which is the entire point: the order will hand these to anyone.</p>\n<p><strong>Effect:</strong> Apply to an adjacent willing, unconscious or restrained creature as a <strong>two-action activity</strong>. The lesser patch restores <strong>1d8 Hit Points</strong>; the moderate restores <strong>3d8+5</strong>. Either grants a <strong>+1 item bonus to Fortitude saves against disease and poison for 10 minutes</strong>. A creature can benefit from only one patch at a time.</p>\n<p><strong>Rousing Ampoule</strong> — 3 gp; Bulk L; one use\n<em>Source: Smelling Salts (PF2e)</em></p>\n<p>A crushable glass ampoule of ammoniac salts in a brass sleeve. Unpleasant and extremely effective.</p>\n<p><strong>Effect:</strong> Crack under the nose of an adjacent unconscious creature that has at least 1 Hit Point as a <strong>single action</strong> to wake it. Also reduces the <strong>sickened</strong> condition by 1.</p>\n<p><strong>Tourniquet Clamp</strong> — 2 gp; Bulk L; Hands 1\n<em>Source: estimated</em></p>\n<p>A ratcheting strap and windlass in a canvas pouch. Ugly, reusable, and it has saved more limbs than any single thing the Medical Corps makes.</p>\n<p><strong>Effect:</strong> Apply to an adjacent creature as a <strong>single action</strong> to attempt a DC 15 flat check to end the <strong>persistent bleed damage</strong> on it. On a success the bleed ends. On a failure the clamp is still applied and you may try again next round.</p>\n<p><strong>Fever Draught</strong> — 8 gp; Bulk L; one use\n<em>Source: estimated</em></p>\n<p>A bitter tincture of cinchona bark and half a dozen things the Medical Corps will name on request. Developed for the Vigilsylva fever wards and now carried by anyone going north.</p>\n<p><strong>Effect:</strong> Drink as a <strong>single action</strong>. For 8 hours you gain a <strong>+2 item bonus to saves against disease</strong>, and you immediately attempt a counteract check with a <strong>+2 item bonus</strong> against one disease already affecting you, using your Fortitude modifier as the counteract modifier.</p>\n<p><strong>Antitoxin</strong> — 1 gp (common), 3 gp (strong); Bulk L; one use\n<em>Source: Antitoxin, commercial and tactical (SF2e Tech Core)</em></p>\n<p>A chalky suspension in a stoppered vial that binds poison in the gut and the blood. Every snakebite kit south of the Watchline carries two.</p>\n<p><strong>Effect:</strong> Drink as a <strong>single action</strong>. For 6 hours you gain a <strong>+1 item bonus</strong> (common) or <strong>+2 item bonus</strong> (strong) to Fortitude saves against poison.</p>\n<p><strong>Settling Draught</strong> — 3 gp; Bulk L; one use\n<em>Source: Antiemetic, commercial (SF2e Tech Core)</em></p>\n<p>Ginger, peppermint and something the Medical Corps distils from it, in a flat green bottle. Sold at every quay in Portovel Arterium and at the Sanguilum steamer berths, because the crossing to Shaadu is 1,500 miles of open water.</p>\n<p><strong>Effect:</strong> Drink as a <strong>single action</strong>. For 10 minutes, reduce the value of the <strong>sickened</strong> condition by 1. A condition reduced to 0 this way isn't removed; after 8 hours it returns to its original value unless it has expired or been removed some other way.</p>\n<p><strong>Coagulant Powder</strong> — 3 gp (common), 9 gp (strong); Bulk L; one use\n<em>Source: Coagulant, commercial and tactical (SF2e Tech Core)</em></p>\n<p>A styptic powder in a waxed paper twist, meant to go into a wound before the tourniquet clamp comes off. The Medical Corps sells the two side by side.</p>\n<p><strong>Effect:</strong> Take it as a <strong>single action</strong>. For 10 minutes you gain <strong>resistance 3</strong> (common) or <strong>resistance 5</strong> (strong) to persistent bleed and persistent poison damage, and the flat check to end either is made as though you had received particularly appropriate aid.</p>\n<p><strong>Nerve Tonic</strong> — 7 gp; Bulk L; one use\n<em>Source: Adrenosuppressant serum, commercial (SF2e Tech Core)</em></p>\n<p>A bright pink tonic that steadies the hands and slows the heart. The Faith Militant buys it by the crate for new Sentinels, and the Arts Corps buys it for opening nights.</p>\n<p><strong>Effect:</strong> Drink as a <strong>single action</strong>. For 1 hour you gain a <strong>+1 item bonus to Will saves</strong>, or <strong>+2 against fear effects</strong>.</p>\n<p><strong>Foundry Draught</strong> — 3 gp 6 sp; Bulk L; one use\n<em>Source: Corona serum, commercial (SF2e Tech Core)</em></p>\n<p>A warm, frothy red draught developed for the harbour foundries and the retort sheds, where the work is done a few feet from open iron. It leaves the drinker running hot, which is the point and also the cost.</p>\n<p><strong>Effect:</strong> Drink as a <strong>single action</strong>. For 1 hour you gain <strong>resistance 5 to fire</strong> and <strong>weakness 2 to cold</strong>, and treat environmental heat as one step less severe.</p>"},{"name":"Engineer Corps, non-combat","html":"<p><strong>Recording Tablet</strong> — 7 sp; Bulk L; Hands 1\n<em>Source: Comm Unit (SF2e)</em></p>\n<p>A compact device that transcribes and stores spoken notes and short recordings. There is no network for it to connect to and no expectation that there ever will be. It talks to nothing but itself.</p>\n<p><strong>Effect:</strong> Records up to one hour of audio, retained until overwritten. A recording plays back exactly and serves as evidence anywhere testimony would. Grants a <strong>+1 item bonus</strong> to Society checks to establish the precise contents of a conversation you recorded.</p>\n<p><strong>Clockwork Pocket Lantern</strong> — 7 sp; Bulk L; Hands 1\n<em>Source: estimated</em></p>\n<p>A wind-up mechanical light. No oil, no flame, nothing to spill or blow out.</p>\n<p><strong>Effect:</strong> Sheds bright light in a 20-foot radius and dim light for another 20 feet. Runs roughly two hours per winding; rewinding takes a single action. Cannot be extinguished by wind or water and will not ignite anything.</p>\n<p><strong>Portable Water Filtration Flask</strong> — 1 gp 2 sp; Bulk L; Hands 2\n<em>Source: estimated</em></p>\n<p>A personal-scale filtration unit built into a hard flask. Slow, but it works.</p>\n<p><strong>Effect:</strong> Renders one pint of questionable water safe to drink per ten minutes of filtering. Water treated this way cannot transmit disease. The filter element lasts about three months of daily use; replacements cost 2 sp.</p>\n<p><strong>Precision Pocket Compass</strong> — 6 sp; Bulk —; Hands 1\n<em>Source: estimated</em></p>\n<p>Reliable and well-machined. Nothing supernatural about it beyond being better made than most.</p>\n<p><strong>Effect:</strong> Grants a <strong>+1 item bonus</strong> to Survival checks to Sense Direction or to avoid becoming lost while travelling.</p>\n<p><strong>Expedition Pack Frame</strong> — 4 gp; Bulk 1; Hands 2 to don\n<em>Source: estimated</em></p>\n<p>A shaped and jointed carrying frame that distributes load across the hips rather than the shoulders. Unremarkable to look at and startlingly effective.</p>\n<p><strong>Effect:</strong> While worn, increase your Bulk limits by <strong>1</strong>. Donning or removing it takes one minute.</p>\n<p><strong>Portable Arc Lamp</strong> — 20 gp; Bulk 1; Hands 2\n<em>Source: estimated</em></p>\n<p>A carbide lamp with a polished parabolic reflector on a shoulder yoke. Considerably brighter than anything with a wick, and bright enough that experienced users learn not to look into the reflector.</p>\n<p><strong>Effect:</strong> Sheds <strong>bright light in a 60-foot cone</strong> and dim light for another 60 feet. Runs four hours per charge of carbide, and spare charges cost 1 sp. Aiming it takes a single action. Anyone in the cone within 20 feet who relies on <strong>darkvision or low-light vision</strong> is <strong>dazzled</strong> while the beam is on them unless they look away.</p>\n<p><strong>Hand Dynamo and Cell Set</strong> — 12 gp; Bulk 1; Hands 2\n<em>Source: Battery (SF2e)</em></p>\n<p>A crank generator and three sealed lead cells in a padded case. This is what powers everything electrical the order lets out of the city.</p>\n<p><strong>Effect:</strong> Ten minutes of cranking fully charges one cell. A cell runs any of the order's electrical devices for its listed duration. Also functions as a <strong>nonmagical light source</strong> through a fitted bulb, shedding dim light in 10 feet.</p>\n<p><strong>Auditory Amplifier</strong> — 10 gp; Bulk L; Hands 2\n<em>Source: estimated</em></p>\n<p>A conical brass listening horn with a rubber ear cup and a contact plate for pressing against surfaces.</p>\n<p><strong>Effect:</strong> While used against a wall, door or floor no thicker than a few inches, gain a <strong>+2 item bonus to Perception checks to Listen</strong> through it, and you can attempt to Listen through the barrier as though it were not there. Each attempt takes a full action and leaves you <strong>off-guard</strong> while you make it.</p>\n<p><strong>Grapnel Launcher</strong> — 25 gp; Bulk 2; Hands 2\n<em>Source: estimated</em></p>\n<p>A compressed-air line thrower with a folding grapnel and fifty feet of braided cord on a drum. The Engineer Corps built it for bridge survey work and the Faith Militant immediately found other uses.</p>\n<p><strong>Effect:</strong> Fire as a <strong>two-action activity</strong> to place the grapnel at a point up to <strong>60 feet</strong> away that could plausibly hold it. The cord supports up to 10 Bulk. Recovering and rewinding takes a minute. Climbing the deployed line reduces the Athletics DC to Climb by 5.</p>\n<p><strong>Survey Theodolite</strong> — 30 gp; Bulk 2; Hands 2\n<em>Source: estimated</em></p>\n<p>A precision sighting instrument on a folding tripod, with vernier scales on both axes. Every mile of the order's rail was laid with one of these.</p>\n<p><strong>Effect:</strong> Grants a <strong>+2 item bonus</strong> to Crafting checks to survey ground, assess a structure, or produce an accurate map of an area you can see, and to Society checks to identify how and when a building was constructed. Requires ten minutes of setup and a clear line of sight.</p>\n<p><strong>Glare Goggles</strong> — 5 gp; Bulk L\n<em>Source: estimated</em></p>\n<p>Smoked glass in a leather surround with side blinkers. Standard issue anywhere there is a furnace, a snowfield, or an arc lamp.</p>\n<p><strong>Effect:</strong> While worn, gain a <strong>+1 item bonus to saves against visual effects</strong> and you are not <strong>dazzled</strong> by sudden bright light. Wearing them in dim light or darkness imposes a <strong>-2 penalty to Perception checks relying on sight</strong>.</p>\n<p><strong>Vacuum Compression Case</strong> — 40 gp; Bulk 2 empty; Hands 2\n<em>Source: estimated</em></p>\n<p>A ribbed iron case with a hand pump, a rubber gasket and a screw press in the lid. It compresses and evacuates its contents rather than doing anything clever with space. Cloth, rations, rope, paper and powder all come out smaller than they went in. Rigid objects do not compress and the order says so on the label.</p>\n<p><strong>Effect:</strong> Ten minutes of pumping and pressing reduces the Bulk of <strong>soft or compressible contents</strong> by half, to a maximum of 8 Bulk of such goods reduced to 4. Rigid items gain no benefit. Opening the case releases the seal and the contents expand again. <strong>This is not extradimensional storage, holds nothing larger than the case, and has no effect on living creatures.</strong></p>\n<p><strong>Clockwork Lock Set</strong> — 8 gp; Bulk L\n<em>Source: estimated</em></p>\n<p>A keyed lever lock of the order's manufacture, sold with two keys and a mounting plate. The Engineer Corps regards the sale of these as a public service and the Assay Office regards it as a mild risk.</p>\n<p><strong>Effect:</strong> A superior lock. The DC to Pick the Lock is <strong>30</strong>, and it requires four successes. Forcing it open is DC 25 Athletics.</p>\n<p><strong>Magnetic Jack</strong> — 15 gp; Bulk 2; Hands 2\n<em>Source: Magnetic jack (SF2e Tech Core)</em></p>\n<p>Two heavy electromagnets on a ferrous plate, run off a dynamo cell. Every rail yard, dock and granary the order runs keeps several, and the Engineer Corps sells them to anyone who has to move something they can't lift.</p>\n<p><strong>Effect:</strong> Place it under an object of up to <strong>200 Bulk</strong> and activate it as a <strong>single action</strong>. The object lifts clear of the ground and can be pushed or pulled at a creature's Speed using two hands. A creature standing on a lifted load is <strong>off-guard</strong>.</p>\n<p><strong>Hazard Suit</strong> — 1 gp; Bulk L; worn\n<em>Source: Lifesuit (SF2e Tech Core)</em></p>\n<p>An oilcloth-and-rubber coverall with a hood, sealed cuffs and a filtered mask. Issued at Venoqual, in the retort sheds and on the salt pans, and sold to anyone who asks.</p>\n<p><strong>Effect:</strong> Provides basic environmental protection (Starfinder Player Core) for 10 days of use. A dynamo cell clipped to the belt extends it by 1 day per charge.</p>\n<p><strong>Atomiser</strong> — 2 gp; Bulk L; Hands 1\n<em>Source: Aerosol spray nozzle (SF2e Tech Core)</em></p>\n<p>A brass spray nozzle on a hand-pumped reservoir, sold for spraying crops, disinfecting wards and marking walls. The Faith Militant noticed early what a fine mist does to something standing in it that nobody can see.</p>\n<p><strong>Effect:</strong> Requires a chemical reservoir, sold separately at the price of a commercial chem tank. Expend one charge to spray an adjacent square as an <strong>Interact</strong> action. An invisible creature, object or light in that square becomes <strong>observed</strong> until the end of your turn, though it still has concealment from its invisibility.</p>"},{"name":"Small Automatons","html":"<p>The Engineer Corps builds a line of small clockwork automatons for sale, well below the labour automaton in size and price. Each is a Tiny construct that flies on a small propeller, runs off a dynamo cell, and follows plain spoken commands. None of them fight, and the order does not build them to.</p>\n<p>All of them use the minibot statistics printed in <em>Tech Core</em>. The order's cells take the place of the printed battery throughout.</p>\n<p><strong>Porter</strong> — 15 gp; Bulk 1\n<em>Source: Bellbot, commercial (SF2e Tech Core)</em></p>\n<p>A lidded trunk on four legs that follows its owner through stations and hotels. The commercial pattern only. It walks rather than flies.</p>\n<p><strong>Effect:</strong> Speed 25 feet, no fly Speed. Carries up to 4 Bulk, and the first Bulk of its contents doesn't count toward its own. Activate as a <strong>single action</strong> to have it follow you for 1 hour, using 1 charge.</p>\n<p><strong>Orderly</strong> — 25 gp; Bulk 1\n<em>Source: Medbot, commercial (SF2e Tech Core)</em></p>\n<p>A small automaton built around a field remedy case, standing by at public events and following Medical Corps staff through the wards.</p>\n<p><strong>Effect:</strong> Its integrated field remedy case works as a healer's toolkit even when the orderly isn't activated.</p>\n<p><strong>Fire Warden</strong> — 105 gp; Bulk 1\n<em>Source: Firebot, commercial (SF2e Tech Core)</em></p>\n<p>A squat iron automaton with a chemical extinguisher in its belly. Every granary complex in Cordevale keeps a rack of them, and Maribel Kosk would like more.</p>\n<p><strong>Effect:</strong> It has <strong>resistance 12 to fire</strong> and holds twice the chemical of any extinguisher installed in it. Activate as a <strong>single action</strong> to have it fly to a fire and use its extinguisher.</p>\n<p><strong>Valet</strong> — 100 gp; Bulk 1\n<em>Source: Butlerbot, commercial (SF2e Tech Core)</em></p>\n<p>A lacquered and brass-trimmed automaton that brushes coats, keeps appointments and remembers where the keys went. Made in small numbers, and something of a status piece in the upper tiers of Sanguilum. The commercial pattern only.</p>\n<p><strong>Effect:</strong> Activate as a <strong>two-action</strong> order to have it clean an object of Light Bulk or less, recall where an object was left (or give a <strong>+1 item bonus</strong> to Seek it), or deliver reminders set during your daily preparations.</p>\n<p><strong>Grabbing Automaton</strong> — 25 gp; Bulk 1\n<em>Source: Grabot, commercial (SF2e Tech Core)</em></p>\n<p>A flying cylinder with a claw on a retractable line, sold to warehouses and the infirm. Every one leaves the Engineer Corps with a card explaining that it is not for burglary, and some of them are used for burglary anyway.</p>\n<p><strong>Effect:</strong> Activate as a <strong>single action</strong> to have it pick up an unattended object of Light Bulk or less up to 10 feet below it.</p>\n<p><strong>Recording Automaton</strong> — 10 gp; Bulk 1\n<em>Source: Camerabot, commercial (SF2e Tech Core)</em></p>\n<p>A floating clockwork recorder that captures sound and image as it circles its operator. The Scholarly Corps takes them on every excavation, and Casiveth Null still has opinions about the image quality.</p>\n<p><strong>Effect:</strong> Records audio and images of its operator's surroundings while the operator performs another exploration activity. Uses 1 charge per hour. It stores its record and connects to nothing.</p>\n<p><strong>Pathfinder</strong> — 10 gp; Bulk 1\n<em>Source: Glampbot, commercial (SF2e Tech Core)</em></p>\n<p>A small automaton with a sun-plate on its back that remembers every step of the road it has travelled. Sold to surveyors, drovers and anyone going somewhere they may need to come back from.</p>\n<p><strong>Effect:</strong> Activate as a <strong>two-action</strong> command to have it guide you back to a location it has physically been. It recharges from 6 hours of sunlight a day.</p>\n<p><strong>Pet Automaton</strong> — 5 gp; Bulk 1\n<em>Source: Petbot (SF2e Tech Core)</em></p>\n<p>A Tiny clockwork animal of the buyer's choice, obviously mechanical, popular with children and the Charge wards. It has a hidden compartment.</p>\n<p><strong>Effect:</strong> It can hide an object of Light Bulk, which takes 1 minute to reach, and grants a <strong>+1 item bonus</strong> to Stealth checks to Conceal an Object inside it.</p>"},{"name":"Armour Fittings","html":"<p>Fittings the Engineer Corps makes for ordinary armour and sells to anyone with a reason to want them. Each installs in an armour upgrade slot.</p>\n<p><strong>Speaking Horn</strong> — 12 gp; Bulk 1\n<em>Source: Sound system, commercial (SF2e Tech Core)</em></p>\n<p>A brass horn and diaphragm fitted at the collar. Standard on Civil Corps watch officers and anyone who has to be heard over a rail yard.</p>\n<p><strong>Effect:</strong> A <strong>+1 item bonus</strong> to Diplomacy, Intimidation and Performance checks for auditory actions.</p>\n<p><strong>Stride Dynamo</strong> — 55 gp; Bulk L\n<em>Source: Kinetic generator, commercial (SF2e Tech Core)</em></p>\n<p>A small dynamo geared to the knee that charges a cell as the wearer walks. Popular with anyone who travels far from a crank and a bench.</p>\n<p><strong>Effect:</strong> Holds one dynamo cell and charges it by 1 charge per 10 minutes of movement. Sitting still or sleeping produces nothing. The stored charge can also be dumped into a creature that strikes the wearer in melee, as printed.</p>\n<p><strong>Survey Sensor</strong> — 50 gp; Bulk L\n<em>Source: Full-spectrum sensor suite, commercial (SF2e Tech Core)</em></p>\n<p>A set of contact plates and a listening helm that read vibration through the ground. Mine rescue teams at Venoqual wear them to find people under a fall.</p>\n<p><strong>Effect:</strong> Once per day, activate as a <strong>single action</strong> to gain <strong>tremorsense</strong> (imprecise, 30 feet) for 10 minutes.</p>\n<p><strong>Propeller Pack</strong> — 60 gp; Bulk L\n<em>Source: Aqua jets, commercial (SF2e Tech Core)</em></p>\n<p>A pair of clockwork screws at the hips for swimming heavy. Sold to divers and hull crews at Portovel Arterium.</p>\n<p><strong>Effect:</strong> Activate as a <strong>single action</strong> to gain a <strong>swim Speed of 20 feet</strong> for 1 minute.</p>\n<p><strong>Boring Cutters</strong> — 160 gp; Bulk 1\n<em>Source: Micro-cutters, commercial (SF2e Tech Core)</em></p>\n<p>Rows of small toothed wheels set into the forearms and shins, built for the shafts at Venoqual and sold to miners across the south.</p>\n<p><strong>Effect:</strong> Activate as a <strong>single action</strong> to gain a <strong>burrow Speed of 20 feet</strong> in loose material for 1 minute. Once per day, bore a hole 5 feet wide, 5 feet tall and 1 foot deep through a non-metal surface, taking 5 minutes per point of the surface's Hardness.</p>\n<p><strong>Helm Fittings</strong> — 160 gp; Bulk 1\n<em>Source: Piloting instruments, commercial (SF2e Tech Core)</em></p>\n<p>Gauges at the wrist and a set of linkages that couple the wearer's harness to a vehicle's controls. Standard for traction engine drivers and rail crews.</p>\n<p><strong>Effect:</strong> A <strong>+1 item bonus</strong> to Piloting checks, and you can Take Control of a vehicle as a free action once per turn unless it would normally take more than one action.</p>\n<p><strong>Condensing Mantle</strong> — 310 gp; Bulk L\n<em>Source: Moisture harvester (SF2e Tech Core)</em></p>\n<p>A cooling and condensing layer worn under the armour that recovers water from the wearer's own sweat. Built for the foundry floors and the southern salt pans.</p>\n<p><strong>Effect:</strong> You're protected from severe heat and can go four times as long as normal without water. Once per day, as a <strong>two-action</strong> activation, vent a 15-foot cone of steam that makes everyone in it concealed for 1 minute.</p>\n<p><strong>Field Dressing Arm</strong> — 150 gp; Bulk 1\n<em>Source: Easypatcher, commercial (SF2e Tech Core)</em></p>\n<p>A folding brass arm at the ribs that holds two medicated patches and applies them where they're needed. Sold through the Medical Corps to anyone who works alone.</p>\n<p><strong>Effect:</strong> Holds up to two medicated patches (loading takes 10 minutes). Activate as a <strong>single action</strong> to apply one to yourself with its full effect.</p>\n<p><strong>Honing Arm</strong> — 85 gp; Bulk L\n<em>Source: ZeroEdge blade sharpener (SF2e Tech Core)</em></p>\n<p>A spring-loaded whetstone at the wrist. Cooks swear by it, and so do the Natural Corps' skinners.</p>\n<p><strong>Effect:</strong> Once per hour, as a <strong>single action</strong>, a slashing melee weapon you're wielding without the deadly trait gains <strong>deadly d6</strong> until the start of your next turn. The weapon can't benefit again for 24 hours.</p>"},{"name":"Prosthetics and Fitted Work","html":"<p>The Medical Corps' prosthetics and grafts are not sold over a counter. They are fitted at the Sanctum Medica or one of the larger regional hospitals, by a surgeon, and the price covers the work. All of them are ordinary engineering and surgery.</p>\n<p><strong>Steel Spinal Rods</strong> — 15 gp\n<em>Source: Spinal struts, commercial (SF2e Tech Core)</em></p>\n<p>Steel rods set alongside the spine, fitted to rail crews, porters and anyone whose back has already given out once.</p>\n<p><strong>Effect:</strong> You can carry 1 additional Bulk without becoming encumbered, and gain a <strong>+1 item bonus</strong> to your Fortitude DC against attempts to Reposition or Shove you.</p>\n<p><strong>Nerve Sensor</strong> — 160 gp\n<em>Source: Danger sensor, commercial (SF2e Tech Core)</em></p>\n<p>A fine sensor wired into the nerves of the neck that sharpens reaction to sudden motion. Fitted mostly to Faith Militant scouts and Watchline officers.</p>\n<p><strong>Effect:</strong> A <strong>+1 item bonus</strong> to Perception checks for initiative and against hostile creatures and hazards within 60 feet.</p>\n<p><strong>Woven Muscle</strong> — 340 gp\n<em>Source: Mobility enhancer, commercial (SF2e Tech Core)</em></p>\n<p>Woven muscle fibre grafted into the fins, wings or digging limbs of peoples who have them. The Medical Corps fits more of these at Portovel Arterium than anywhere else.</p>\n<p><strong>Effect:</strong> A <strong>+5-foot item bonus</strong> to one burrow, climb, fly or swim Speed you already have, chosen when it's fitted.</p>\n<p><strong>Clockwork Hand</strong> — 365 gp\n<em>Source: Quantum multitool appendage, commercial (SF2e Tech Core)</em></p>\n<p>A clockwork prosthetic hand of the Medical Corps' own design, with fold-out tools in the palm and fingers. Fitted as a replacement for a lost hand, and occasionally fitted to engineers who asked.</p>\n<p><strong>Effect:</strong> Unfolds as an <strong>Interact</strong> action into a tactical infiltrator's, maker's or repair toolkit. Once per day, when you critically fail a Crafting or Thievery check while it's unfolded, you fail instead.</p>"},{"name":"Natural and Agrarian Corps","html":"<p><strong>Weatherglass</strong> — 18 gp; Bulk L; Hands 2\n<em>Source: estimated</em></p>\n<p>A portable atmospheric pressure instrument in a padded case. Reads changes in pressure a few hours ahead of the sky showing them.</p>\n<p><strong>Effect:</strong> Grants a <strong>+2 item bonus</strong> to Survival checks to predict weather within the next 12 hours. On a critical success you also know roughly when the change will arrive.</p>\n<p><strong>Chemical Test Kit</strong> — 22 gp; Bulk 1; Hands 2; 10 uses\n<em>Source: estimated</em></p>\n<p>Reagent vials, test papers and a comparison chart, for checking water and soil against common contaminants.</p>\n<p><strong>Effect:</strong> Spend one use and ten minutes to attempt a Crafting or Nature check against the relevant DC to identify a mundane poison, contaminant or spoilage in a sample, with a <strong>+2 item bonus</strong>. It does not detect anything magical and the order is upfront about that.</p>\n<p><strong>Beheaded Seed Stock</strong> — 5 gp per sack; Bulk 1\n<em>Source: ordinary trade goods</em></p>\n<p>Hardier and more disease-resistant than most regions produce locally, bred over generations by the Agrarian Corps and sold at cost.</p>\n<p><strong>Effect:</strong> A sack sows roughly an acre. Crops grown from it resist blight and drought substantially better than local stock. Mechanically relevant in downtime, settlement or holding rules, where it should meaningfully improve yield.</p>\n<p><strong>Coarse Salt</strong> — 4 cp per pound; <strong>Curing Salt, bagged</strong> — 2 sp per 25 lb bag; Bulk 1\n<em>Source: ordinary trade goods</em></p>\n<p>Raked from the order's solar evaporation pans on the southern coast, dried, bagged and carried inland by barge and rail. The coarse grade is table and kitchen salt. The curing grade is sold by the bag to anyone putting meat or fish down for storage.</p>\n<p><strong>Effect:</strong> A 25 lb bag preserves roughly 100 lb of meat or fish. Relevant in downtime, settlement and holding rules, and in any situation where food has to last. Outside the order's network the same bag costs three to six times as much, where it can be got at all.</p>\n<p><strong>Hard Char</strong> — 1 sp per 20 lb; Bulk 2\n<em>Source: estimated</em></p>\n<p>The order's fuel, and not coal. Coppiced timber charred in sealed retorts until only carbon remains. Burns hotter and far cleaner than firewood or ordinary charcoal, with pale smoke and almost no smell.</p>\n<p><strong>Effect:</strong> Sold mainly to smiths, cooks and anyone running a boiler. Burns roughly three times as long as an equivalent weight of firewood at a higher temperature, which matters for any Crafting activity that needs sustained forge heat. The order sells it freely and will not sell the retort design.</p>\n<p><strong>Preserved Rations</strong> — 2 gp per week's supply; Bulk 1\n<em>Source: ordinary trade goods</em></p>\n<p>Dried and treated food developed for extended field deployments. It keeps for years and tastes like it.</p>\n<p><strong>Effect:</strong> One week of food for one creature. Does not spoil under ordinary conditions and resists damp far better than standard rations, which matters a great deal north of the Watchline.</p>\n<p><strong>Smudge Coil</strong> — 1 gp per box of ten; Bulk L\n<em>Source: estimated</em></p>\n<p>A slow-burning coil of treated pyrethrum. Lit at dusk and left at the edge of a camp.</p>\n<p><strong>Effect:</strong> One coil burns four hours and makes a 20-foot radius <strong>unpleasant to ordinary insects and vermin</strong>. Grants a <strong>+1 item bonus to saves against diseases carried by insects</strong> while within the area, and removes the environmental penalty for sleeping in insect-heavy country.</p>\n<p><strong>Marking Dust</strong> — 5 gp per flask; Bulk L; 10 uses\n<em>Source: estimated</em></p>\n<p>A fine mineral powder in a squeeze flask, developed by the Natural Corps for tracking working animals across the plains. Almost invisible on the ground and vivid under an arc lamp or a lens.</p>\n<p><strong>Effect:</strong> Spend one use to dust a creature, object, or doorway. For the next 24 hours, anyone who knows to look gains a <strong>+2 item bonus to Survival checks to Track</strong> that subject, and the dust is plainly visible under bright directed light. It comes off in water.</p>"},{"name":"Scholarly and Arts Corps","html":"<p><strong>Bound Codex Excerpt</strong> — 10 to 40 gp by subject; Bulk L\n<em>Source: ordinary trade goods</em></p>\n<p>A hand-copied selection from the order's less sensitive archives. History, natural science or philosophy, bound plainly and made to be read rather than displayed.</p>\n<p><strong>Effect:</strong> Grants a <strong>+1 item bonus</strong> to Recall Knowledge checks on the single narrow subject the excerpt covers, provided you can consult it for a minute. Price scales with how specialised the subject is.</p>\n<p><strong>Traveler's Writing Kit</strong> — 4 gp; Bulk L; Hands 2\n<em>Source: ordinary trade goods</em></p>\n<p>Fine paper, reliable ink and a well-made pen in a sealed case, all considerably better than what most local shops carry.</p>\n<p><strong>Effect:</strong> Provides everything needed for writing, drafting or copying. Grants a <strong>+1 item bonus</strong> to Crafting checks to produce written work and to Society checks to produce a convincing document.</p>\n<p><strong>Handcrafted Instrument</strong> — 15 to 50 gp; Bulk 1\n<em>Source: ordinary trade goods</em></p>\n<p>Arts Corps students and instructors sell surplus work. Flutes, small stringed instruments, drums. Well made and priced honestly.</p>\n<p><strong>Effect:</strong> A functioning instrument of the listed type. At the upper end of the price range it grants a <strong>+1 item bonus</strong> to Performance checks made with it.</p>\n<p><strong>Lens Case</strong> — 6 gp; Bulk L; Hands 1\n<em>Source: estimated</em></p>\n<p>A folding set of ground glass lenses in a brass case, from a jeweller's loupe up to a wide reading glass.</p>\n<p><strong>Effect:</strong> Grants a <strong>+1 item bonus</strong> to Perception checks to examine a small object or surface closely, and to Crafting or Society checks to assess a document, seal, inscription or forgery.</p>\n<p><strong>Cipher Wheel</strong> — 12 gp; Bulk L; Hands 2\n<em>Source: estimated</em></p>\n<p>Concentric brass discs on a pin, with an index and a keyed setting. The Civil Corps uses these for freight schedules and the Assay Office uses them for everything else.</p>\n<p><strong>Effect:</strong> Encode or decode a written message at roughly a page per ten minutes. A message encoded this way requires a successful <strong>DC 25 Society check</strong> to break without the key, or DC 18 if the reader has another wheel of the same pattern. The order sells the common pattern and not its own.</p>\n<p><strong>Spring-Steel Leg</strong> — 16 gp\n<em>Source: Mechanical leap accelerators, commercial (SF2e Tech Core)</em></p>\n<p>A replacement leg of sprung steel and pistons, or a brace fitted over a damaged one. The most common prosthetic the Medical Corps fits, because the rail and the mines take more legs than anything else.</p>\n<p><strong>Effect:</strong> When you Leap, you move 5 feet farther horizontally or 3 feet higher.</p>\n<p><strong>Capacitor Hand</strong> — 60 gp\n<em>Source: Quick-charge hand, commercial (SF2e Tech Core)</em></p>\n<p>A brass hand, or brass fingers on a living one, with capacitor pads that build a charge through the day. Engineers ask for these by name.</p>\n<p><strong>Effect:</strong> Once per day, as a free action, fully recharge a commercial dynamo cell you're holding or touching.</p>\n<p><strong>Tethered Fist</strong> — 80 gp\n<em>Source: Rocket fist, commercial (SF2e Tech Core)</em></p>\n<p>A clockwork fist on a steel cable, fired from the forearm by a spring. Fitted to replace a lost hand, and fitted rather more often than that to the Faith Militant.</p>\n<p><strong>Effect:</strong> As a <strong>single action</strong>, make a fist Strike with the thrown 30 feet and tethered traits. Afterwards the fist lies where it landed until you Interact to reel it in.</p>\n<p><strong>Brace Arm</strong> — 460 gp\n<em>Source: Additional appendage, commercial (SF2e Tech Core)</em></p>\n<p>A third arm of steel and leather, mounted at the shoulder blade. Surgeons, linemen and anyone who has spent a career wishing for one more hand.</p>\n<p><strong>Effect:</strong> You gain an additional hand for holding items, and must Switch Hands to wield what it holds.</p>\n<p><strong>Listening Soles</strong> — 1,300 gp\n<em>Source: Tremor soles, commercial (SF2e Tech Core)</em></p>\n<p>Fine sensors set into the soles of the feet that read vibration through the ground. Rare, expensive, and fitted mostly to mine rescue and the Penitent.</p>\n<p><strong>Effect:</strong> Tremorsense (imprecise, 30 feet).</p>"},{"name":"Grafts","html":"<p>The Medical Corps' grafts are grown tissue, made by the same science that makes the order's mutagens and fitted by the same surgeons who fit its prosthetics. None of them come from an animal killed for the purpose, and none from the dead. The order discusses them openly and fits the practical ones to anyone who asks. The ones built for fighting are fitted to members only.</p>\n<p><strong>Deep-Diver Lungs</strong> — 90 gp\n<em>Source: Vacuum-adapted lungs, commercial (SF2e Tech Core)</em></p>\n<p>Valved lungs for divers, hull crews and the high workings at Venoqual.</p>\n<p><strong>Effect:</strong> You can hold your breath for 10 minutes, and you're acclimated to either thin or thick air, chosen when fitted.</p>\n<p><strong>Filter Lung</strong> — 55 gp\n<em>Source: Necrolung, tactical (SF2e Tech Core)</em></p>\n<p>A spongy grown lining in one lung that strains out smoke, fumes and damp. Fitted to miners, retort crews and fire wardens.</p>\n<p><strong>Effect:</strong> You can breathe toxic air for up to 24 hours without harm, and gain a <strong>+1 status bonus</strong> to saves against inhaled diseases and poisons.</p>\n<p><strong>Buoyancy Bladder</strong> — 25 gp\n<em>Source: Emergency buoyancy bladder, commercial (SF2e Tech Core)</em></p>\n<p>A small bladder beneath the ribs that inflates on command. Standard for the fleet and the harbour crews.</p>\n<p><strong>Effect:</strong> Once per day, as a <strong>single action</strong>, rise to the surface at 20 feet per round and float for 30 minutes.</p>\n<p><strong>Fins</strong> — 50 gp\n<em>Source: Fins, commercial (SF2e Tech Core)</em></p>\n<p>Folding fins along the forearms and calves. Tidewardens, divers and the Portovel pilots.</p>\n<p><strong>Effect:</strong> Deploy them with an Interact action while in light armour or none to gain a <strong>swim Speed of 20 feet</strong>.</p>\n<p><strong>Glide Membrane</strong> — 20 gp\n<em>Source: Patagium, commercial (SF2e Tech Core)</em></p>\n<p>A fold of skin from wrist to ankle. Fitted to scouts, riggers and roofers.</p>\n<p><strong>Effect:</strong> Spread it with an Interact action to glide at a fly Speed of 20 feet, descending at least 1 foot for every 5 moved. As a reaction when you fall 10 feet or more, spread it and take no falling damage.</p>\n<p><strong>Elastic Skin</strong> — 50 gp\n<em>Source: Elastic skin, commercial (SF2e Tech Core)</em></p>\n<p>Skin that stretches further than it should. Popular with mine rescue, and with anyone else whose work involves narrow places.</p>\n<p><strong>Effect:</strong> A <strong>+1 item bonus</strong> to Acrobatics or Athletics checks to Escape or Squeeze.</p>\n<p><strong>Spinneret</strong> — 30 gp\n<em>Source: Spinneret, commercial (SF2e Tech Core)</em></p>\n<p>A small gland at the wrist that draws out strong silk. The silk degrades after a day.</p>\n<p><strong>Effect:</strong> Extrude up to 25 feet of silk line per day, 5 feet per <strong>single action</strong>.</p>\n<p><strong>Pheromone Gland</strong> — 50 gp\n<em>Source: Pheromone gland, commercial (SF2e Tech Core)</em></p>\n<p>Glands at the throat and wrists that put out a scent working animals trust. Drovers and the Natural Corps kennels.</p>\n<p><strong>Effect:</strong> A <strong>+1 item bonus</strong> to Nature checks to Command an Animal.</p>\n<p><strong>Vital Sight</strong> — 850 gp\n<em>Source: Eyes of the soul, commercial (SF2e Tech Core)</em></p>\n<p>A graft behind the eyes that lets the wearer see the heat and pulse of a living body. It turns the whites of the eyes dark. Fitted to senior physicians, and to anyone whose work involves telling the living from the dead.</p>\n<p><strong>Effect:</strong> A <strong>+2 item bonus</strong> to Medicine checks. Once per hour, as a <strong>single action</strong>, gain lifesense as a precise sense within 10 feet for 1 minute, distinguishing living creatures from undead and from things with no life at all.</p>\n<p><strong>Iron Gut</strong> — 325 gp\n<em>Source: Ghoul stomach, commercial (SF2e Tech Core)</em></p>\n<p>A grown stomach lining that can take almost anything. It also makes the wearer hungry all the time, which the Medical Corps warns about twice.</p>\n<p><strong>Effect:</strong> A <strong>+1 circumstance bonus</strong> to Fortitude saves against ingested poisons and to retch while sickened. Having eaten within the last hour grants a +5-foot item bonus to your Speeds and a +1 item bonus to High Jump and Long Jump; otherwise you take a –5-foot item penalty to your Speeds.</p>\n<h3>Members only</h3>\n<p>The following are fitted to members of the order and nobody else.</p>\n<p><strong>Claws</strong> — 20 gp · <strong>Predator Teeth</strong> — 20 gp · <strong>Bone Blade</strong> — 15 gp · <strong>Quills</strong> — 160 gp · <strong>Tendon Wraps</strong> — 27 gp · <strong>Sealed Eardrums</strong> — 50 gp · <strong>Howling Throat</strong> — 55 gp · <strong>Stench Glands</strong> — 32 gp · <strong>Phosphor Mesh</strong> — 60 gp · <strong>Glittergland</strong> — 30 gp · <strong>Slime Gland</strong> — 35 gp</p>\n<p><em>Sources, in order: claws, predator teeth, bone blade, quills, mummified wraps, hollowed eardrums, shrieking modulator, noxious sweat, filament mesh, glittergland, slime gland (all SF2e Tech Core, commercial grade).</em> Each uses its printed statistics. The glittergland deserves a word: a burst of sticky, reflective glitter that makes an invisible creature merely concealed. The Faith Militant fits more of them every year.</p>"},{"name":"Faith Militant Goods, Limited","html":"<p>The order sells very little from this side of the house, but \"very little\" is not \"nothing,\" and the distinction matters. Anything a person could already buy from an Imperial armoury is not a secret worth keeping.</p>\n<p><strong>Standard Musket</strong> — 10 gp; Bulk 1; Hands 2\n<em>Source: flintlock musket (PF2e)</em></p>\n<p>An ordinary muzzle-loading firearm of the sort produced across the world, including by the Empire. The order manufactures these to a better standard than most, sells them without fuss, and considers the whole category unremarkable.</p>\n<p><strong>Effect:</strong> Uses the standard rules for its weapon type. Ammunition and black powder are sold alongside at the usual rates.</p>\n<blockquote>\n<p><strong>What separates this from what the order actually carries.</strong> The Faith Militant's firearms are generations ahead of a musket and are never sold, never lent, and never left where they could be examined. A merchant will sell a visitor a musket cheerfully and will not so much as discuss the other thing.</p>\n</blockquote>\n<p><strong>Smoke Device</strong> — 3 gp; Bulk L\n<em>Source: smoke grenade equivalents</em></p>\n<p>A chemical smoke canister. The order shares basic smoke and flash variants with town watch forces in communities it protects, which makes these the one piece of Faith Militant chemistry available to the public.</p>\n<p><strong>Effect:</strong> Thrown; creates a cloud of smoke roughly 10 feet across for 1 minute. Creatures inside are concealed. No damage.</p>\n<p><strong>Flash Device</strong> — 4 gp; Bulk L\n<em>Source: flashbang equivalents</em></p>\n<p>A chemical flash charge, non-lethal, and the standard non-violent option for a watchman facing something he would rather not fight.</p>\n<p><strong>Effect:</strong> Thrown; creatures in a 10-foot burst must succeed at a Reflex save or be dazzled for 1 round. No damage.</p>"},{"name":"Engineer and Scholarly Instruments","html":"<p><strong>Mechanic's Toolkit</strong> — 12 gp; Bulk 1; Hands 2\n<em>Source: Mechanic's Toolkit / repair kit</em></p>\n<p>The Engineer Corps' standard toolkit, which by outside standards is a work of art. Precision instruments most of the world lacks the manufacturing capability to reproduce.</p>\n<p><strong>Effect:</strong> Functions as a full set of repair tools and grants a <strong>+1 item bonus</strong> to Crafting checks to Repair.</p>\n<p><strong>Environmental Analyzer</strong> — 35 gp; Bulk 1; Hands 2\n<em>Source: Environmental Analyzer (SF2e)</em></p>\n<p>A portable clockwork instrument for measuring and cataloguing conditions. Temperature, air composition, soil content. The Scholarly and Natural Corps share these between them and sell them to serious buyers.</p>\n<p><strong>Effect:</strong> Ten minutes of use grants a <strong>+2 item bonus</strong> to Survival, Nature or Crafting checks to assess environmental conditions in an area, including air quality, water content and soil composition. It measures the mundane world precisely and detects nothing magical.</p>"},{"name":"Noqual","html":"<p>Noqual is a naturally occurring mineral rather than an invention of the order. Sovereign Steel, the alloy made from it, is theirs. The order has more raw noqual than it could plausibly use and sells it openly to serious buyers, priced by weight rather than sitting on a shelf.</p>\n<p><strong>Raw Noqual, Small Worked Parcel</strong> — 600 gp; Bulk 1</p>\n<p>Enough for a single small component, an inlay, or a set of instrument tips.</p>\n<p><strong>Raw Noqual, Full Measure</strong> — 6,000 gp; Bulk 6</p>\n<p>Enough to alloy into a meaningful quantity of finished work, assuming you have a smith who knows what they are doing. Most buyers do not.</p>\n<p>Raw noqual carries the mineral's resistance to magic in proportion to its mass. A parcel this size will not protect a person, and the order says so plainly to every buyer before taking their money.</p>"},{"name":"Chartered Requisition","html":"<p>Everything above is sold. What follows is <strong>issued</strong>, and only against a <strong>Writ of Requisition</strong> signed by a Director and countersigned by the Assay Office.</p>\n<p>The order does not sell restricted equipment and has not made an exception. What it has done, for a party it is sending to do work the order cannot do itself, is lend some of it. The distinction matters to the order and should be made to matter at the table.</p>\n<p><strong>How the writ works</strong></p>\n<ul>\n<li>Items are <strong>signed out by name</strong>, against a specific charter, for the duration of that charter.</li>\n<li>Every item is <strong>logged, numbered, and expected back</strong>. Loss is not punished, it is <em>recorded</em>, and the recording is a real social fact in a body that has been keeping records for nine hundred years.</li>\n<li>The writ can be <strong>read</strong> by any Beheaded member and produces immediate, unquestioning cooperation. It also identifies its bearers instantly to anyone who knows what they are looking at.</li>\n<li>The Assay Office can <strong>revoke</strong> a writ. It has not often needed to.</li>\n<li>Sale, gift or transfer of a requisitioned item to a non-bearer ends the charter. The order does not threaten anyone about this. It explains it once, in a chair, unhurried, with tea.</li>\n</ul>\n<p><strong>What the writ opens</strong></p>\n<table>\n<thead>\n<tr>\n<th><strong>Item</strong></th>\n<th><strong>Use published stats for</strong></th>\n<th><strong>Notes</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Order service revolver</strong></td>\n<td>SF2e <em>rotating pistol</em></td>\n<td>The sidearm the Faith Militant actually carries, generations past the muskets sold in the bazaar</td>\n</tr>\n<tr>\n<td><strong>Pattern 12 repeater</strong></td>\n<td>PF2e <em>jezail</em>, capacity 13</td>\n<td>The order's lever-action rifle. The Faith Militant will teach its use at no charge and will insist on doing so</td>\n</tr>\n<tr>\n<td><strong>Pump shotgun</strong></td>\n<td>SF2e <em>scattergun</em>, capacity 5</td>\n<td>Vigilsylva stock. Issued to anyone going north with the order's blessing</td>\n</tr>\n<tr>\n<td><strong>Adhesive compound grenade</strong></td>\n<td>SF2e <em>stickybomb grenade</em> (Tech Core)</td>\n<td>Built specifically to hold extraplanar things still. Two per bearer per charter, and the Ordnance House counts them</td>\n</tr>\n<tr>\n<td><strong>Electrical discharge baton</strong></td>\n<td>SF2e <em>shock pad</em></td>\n<td>Built for detention, and the order is pointed about that being the reason it exists. Any member can pull the blow to deal nonlethal damage</td>\n</tr>\n<tr>\n<td><strong>Darkvision optics</strong></td>\n<td>PF2e <em>clockwork goggles</em>, greater (Guns &amp; Gears)</td>\n<td>A brass clockwork headset of ground and etched lenses. Wound and set, it gives darkvision for a short spell and then has to be wound again. It can't be worn under a helmet</td>\n</tr>\n<tr>\n<td><strong>Mercy rounds</strong></td>\n<td>SF2e <em>mercy ammunition</em> (Tech Core)</td>\n<td>Rubber-headed cartridges that make any firearm nonlethal. Issued by the box, and nobody counts them</td>\n</tr>\n</tbody>\n</table>\n<p><strong>What the writ does not open</strong></p>\n<ul>\n<li><strong>Sovereign Steel, in any form.</strong> Issue is limited to the Faith Militant, the Penitent, and members who have passed the Militant Course. There is no writ for it and no exception has ever been granted. Asking is not an insult and will not work. <em>If the party want Sovereign Steel they can pass the Course, and the Course is open to them on the same terms as anyone.</em></li>\n<li><strong>The Codex, or any unbound page of it.</strong></li>\n<li><strong>The retort design, the pan design, and the survey maps of the coppice.</strong> The order sells the fuel and not the means of making it.</li>\n<li><strong>Anything noqual-cored.</strong> Partly doctrine, mostly practical: hand a noqual-pattern weapon to Fern or Pipsy and the carrier suffers for it as much as the target.</li>\n</ul>\n<blockquote>\n<p><strong>A note for the party's casters.</strong> Darkvision optics, the discharge baton, the compound grenades and the mercy rounds contain no noqual and are safe for Fern and Pipsy to carry and use. The order will confirm this unprompted, because it has thought about it and does not want them to have to ask.</p>\n</blockquote>"},{"name":"Not For Sale","html":"<p>None of the following reaches a market at any price. This list comes from the order's own technology-sharing doctrine rather than from pricing convenience. Several items formerly on it can now be issued to a chartered party under a Writ of Requisition, which is a loan and not a sale; see the section above.</p>\n<p><strong>Faith Militant, never sold</strong></p>\n<ul>\n<li>The order's own advanced firearms, which are generations past the muskets it sells freely <em>(requisitionable)</em></li>\n<li>Sovereign Steel in any form <em>(never, under any writ)</em></li>\n<li>Adhesive compound grenades, developed specifically for immobilising extraplanar creatures <em>(requisitionable, counted)</em></li>\n<li>Electrical discharge batons <em>(requisitionable)</em></li>\n<li>Darkvision optics <em>(requisitionable)</em></li>\n<li>Rifled ordnance, armoured hulls, and anything that belongs to a ship</li>\n</ul>\n<p><strong>Engineer Corps, internal use only</strong></p>\n<ul>\n<li>High-temperature chemical cutting tools</li>\n<li>Pneumatic ordnance launchers</li>\n<li>Explosive compounds beyond the basic smoke and flash devices above</li>\n<li>Steam-propelled flight harnesses</li>\n<li>Combat automaton parts of any kind</li>\n<li>The order's security fittings: thermopile alarms, bark boxes and fingerprint locks guard the order's own doors and are not sold</li>\n<li>The press hopper, and every Tech Core weapon, armour and shield the Armory issues</li>\n</ul>\n<p><strong>Medical Corps, internal use only</strong></p>\n<ul>\n<li>The order's <strong>experimental</strong> healing elixirs, which work considerably faster than anything on open sale and which nobody in the Medical Corps can yet fully explain. Restricted until testing is complete, not withheld on principle. The order is not in the business of keeping a working remedy from people, and intends to sell these like everything else the moment their behaviour can be predicted reliably</li>\n<li>Surgical instruments beyond the field kits above, most of which an outside surgeon could not identify</li>\n<li>Combat grafts: claws, teeth, bone blades, quills, tendon wraps, sealed eardrums, howling throats, stench glands, phosphor mesh and glitterglands are fitted to members only</li>\n<li>Giant's draught, which is the experimental elixir programme's most visible result and the one the order least wants copied</li>\n</ul>\n<p>A merchant asked directly will say politely, and without further explanation, that it isn't something the order sells.</p>"},{"name":"Price Summary","html":"<table>\n<thead>\n<tr>\n<th>Item</th>\n<th>Price</th>\n<th>Bulk</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Coarse salt, one pound</td>\n<td>4 cp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Hard char, 20 lb</td>\n<td>1 sp</td>\n<td>2</td>\n</tr>\n<tr>\n<td>Curing salt, 25 lb bag</td>\n<td>2 sp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Antiseptic wash (4 doses)</td>\n<td>3 sp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Precision pocket compass</td>\n<td>6 sp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Clockwork pocket lantern</td>\n<td>7 sp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Recording tablet</td>\n<td>7 sp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Smudge coils, box of ten</td>\n<td>1 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Antitoxin, common</td>\n<td>1 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Hazard suit</td>\n<td>1 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Portable water filtration flask</td>\n<td>1 gp 2 sp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Hypo-injector kit</td>\n<td>1 gp 5 sp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Tourniquet clamp</td>\n<td>2 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Preserved rations, one week</td>\n<td>2 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Atomiser</td>\n<td>2 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Rousing ampoule</td>\n<td>3 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Smoke device</td>\n<td>3 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Antitoxin, strong</td>\n<td>3 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Settling draught</td>\n<td>3 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Coagulant powder, common</td>\n<td>3 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Foundry draught</td>\n<td>3 gp 6 sp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Medicated patch, lesser</td>\n<td>4 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Flash device</td>\n<td>4 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Traveler's writing kit</td>\n<td>4 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Expedition pack frame</td>\n<td>4 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Marking dust (10 uses)</td>\n<td>5 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Glare goggles</td>\n<td>5 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Beheaded seed stock, one sack</td>\n<td>5 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Field remedy case</td>\n<td>5 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Pet automaton</td>\n<td>5 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Lens case</td>\n<td>6 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Nerve tonic</td>\n<td>7 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Fever draught</td>\n<td>8 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Clockwork lock set</td>\n<td>8 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Coagulant powder, strong</td>\n<td>9 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Auditory amplifier</td>\n<td>10 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Standard musket</td>\n<td>10 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Recording automaton</td>\n<td>10 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Pathfinder automaton</td>\n<td>10 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Bound codex excerpt</td>\n<td>10 to 40 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Cipher wheel</td>\n<td>12 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Hand dynamo and cell set</td>\n<td>12 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Mechanic's toolkit</td>\n<td>12 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Speaking horn</td>\n<td>12 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Magnetic jack</td>\n<td>15 gp</td>\n<td>2</td>\n</tr>\n<tr>\n<td>Porter automaton</td>\n<td>15 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Steel spinal rods, fitted</td>\n<td>15 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Handcrafted instrument</td>\n<td>15 to 50 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Spring-steel leg, fitted</td>\n<td>16 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Weatherglass</td>\n<td>18 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Portable arc lamp</td>\n<td>20 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Glide membrane, fitted</td>\n<td>20 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Chemical test kit (10 uses)</td>\n<td>22 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Grapnel launcher</td>\n<td>25 gp</td>\n<td>2</td>\n</tr>\n<tr>\n<td>Medicated patch, moderate</td>\n<td>25 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Orderly automaton</td>\n<td>25 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Grabbing automaton</td>\n<td>25 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Buoyancy bladder, fitted</td>\n<td>25 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Survey theodolite</td>\n<td>30 gp</td>\n<td>2</td>\n</tr>\n<tr>\n<td>Spinneret, fitted</td>\n<td>30 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Environmental analyzer</td>\n<td>35 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Vacuum compression case</td>\n<td>40 gp</td>\n<td>2</td>\n</tr>\n<tr>\n<td>Advanced field kit</td>\n<td>50 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Survey sensor</td>\n<td>50 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Fins, fitted</td>\n<td>50 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Elastic skin, fitted</td>\n<td>50 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Pheromone gland, fitted</td>\n<td>50 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Stride dynamo</td>\n<td>55 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Filter lung, fitted</td>\n<td>55 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Propeller pack</td>\n<td>60 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Capacitor hand, fitted</td>\n<td>60 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Tethered fist, fitted</td>\n<td>80 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Honing arm</td>\n<td>85 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Deep-diver lungs, fitted</td>\n<td>90 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Valet automaton</td>\n<td>100 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Fire warden automaton</td>\n<td>105 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Field dressing arm</td>\n<td>150 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Boring cutters</td>\n<td>160 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Helm fittings</td>\n<td>160 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Nerve sensor, fitted</td>\n<td>160 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Condensing mantle</td>\n<td>310 gp</td>\n<td>L</td>\n</tr>\n<tr>\n<td>Iron gut, fitted</td>\n<td>325 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Woven muscle, fitted</td>\n<td>340 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Clockwork hand, fitted</td>\n<td>365 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Brace arm, fitted</td>\n<td>460 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Raw noqual, small parcel</td>\n<td>600 gp</td>\n<td>1</td>\n</tr>\n<tr>\n<td>Vital sight, fitted</td>\n<td>850 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Listening soles, fitted</td>\n<td>1,300 gp</td>\n<td>—</td>\n</tr>\n<tr>\n<td>Raw noqual, full measure</td>\n<td>6,000 gp</td>\n<td>6</td>\n</tr>\n</tbody>\n</table>"},{"name":"Where To Buy It","html":"<p>The Sanguilum Grand Bazaar carries everything above. Outlying markets carry a narrow slice suited to local trade, and each list below is the whole list rather than an abbreviated one.</p>\n<p><strong>Portovel Arterium.</strong> A working port market. Preserved rations, weatherglass, precision compass, standard muskets and powder, fresh catch at 2 sp a pound, salt in both grades by the bag, hard char by the sack, settling draught, hazard suits, propeller packs, helm fittings, and ordinary chandlery goods at varying prices.</p>\n<p><strong>Cordevale.</strong> Farm country. Beheaded seed stock, water filtration flask, field remedy case, curing salt by the bag in any quantity a farm could want, hard char, magnetic jacks, fire warden automatons, atomisers, and seasonal produce off the cart.</p>\n<p><strong>Vigilsylva.</strong> Frontier stock, light and practical. Preserved rations, clockwork lantern, chemical test kit, antiseptic wash, water filtration flask, expedition pack frame, standard muskets and powder, smoke and flash devices, environmental analyzer, salt in both grades, antitoxin, coagulant powder, pathfinder automatons and hazard suits. The test kit sells steadily here for checking whether something in the forest has tainted a stream, and the antiseptic and flask move for the same reason the Fever House is the largest building in town.</p>\n<p><strong>The Grand Bazaar, chartered stock.</strong> A party holding a writ collects requisitioned equipment from the Ordnance House inside the Faith Militant compound rather than from any market stall, against signature, with a Civil Corps clerk reading the list aloud twice.</p>\n<p><strong>Venoqual.</strong> Not a town that does casual retail. Raw noqual at both weights, mechanic's toolkits, hazard suits, foundry draught, survey sensors, boring cutters, and mining tools at 3 to 8 gp each from the same forges that supply Sanguilum.</p>\n<p><strong>Ottojikk.</strong> Not a Beheaded town, so the order's goods arrive through the same merchant houses as everything else. Bazaar prices plus roughly 15%, alongside a certain amount of genuinely exotic stock that came through the Wayhouse doors rather than on a cart.</p>"}]}];
const SHARED = [{"name":"The Two Towns You Know","html":"<h3>Ottojikk</h3>\n<p>Ottojikk is where your five months started, though you slept through the whole thing. It sits at the rail junction where the line up from Sanguilum meets the east-west line between Cordevale and Portovel Arterium. That junction made it rich. Freight yards, cranes, cargo stacked under tarps in half a dozen house colours.</p>\n<p>It's not a Beheaded town, which makes it unusual around here. Ottojikk sits inside the triangle the order holds, with Sanguilum south, Cordevale west and Portovel Arterium east, and it's the hole in the middle. Still under Imperial influence, more or less. The order keeps a school, a small clinic and a rail liaison there. No garrison, no gate, no authority. What they've got instead is patience.</p>\n<p>What Ottojikk actually runs on is <strong>the Wayhouse</strong>, the inn that holds the door-circle. You know how it works because it's how you got here: a door in an inn in Xandar, and a door in Sholtan on the other side of it. None of you walked it this time.</p>\n<p>The staff kept the room you were found in. They haven't rented it out since.</p>\n<h3>Sanguilum</h3>\n<p>Sanguilum is the seat of the Church of the Beheaded and home to a few hundred thousand people. It's been your home for five months, though you were unconscious for most of that.</p>\n<p>It's a white stone city built on a hill above a natural harbour, climbing away from the water in tiers. The roads between the tiers are red brick, laid deliberately so they read like arteries running up through the white. At the crown sits the <strong>Codex Ventriculum</strong>, domed and enormous and visible from most of the city.</p>\n<p>The whole place runs on bells. Every tier keeps its own, and on the hour they ring in sequence from the crown down, so the sound rolls downhill to the harbour and stops. Takes about a minute. The city pauses a little while it happens.</p>\n<p>The Corps aren't segregated, but they are concentrated, and the character of each tier shifts as you climb.</p>\n<table>\n<thead>\n<tr>\n<th>Where</th>\n<th>What's there</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>The Crown</strong></td>\n<td>Codex Ventriculum, the Grand Archive, leadership offices</td>\n</tr>\n<tr>\n<td><strong>Upper tiers</strong></td>\n<td>Scholarly and Arts. Libraries, lecture halls, studios, the Round</td>\n</tr>\n<tr>\n<td><strong>Middle tiers</strong></td>\n<td>Medical and Engineer. The Sanctum Medica, workshops, foundries, rail yards</td>\n</tr>\n<tr>\n<td><strong>Lower tiers</strong></td>\n<td>Civil, Natural and Agrarian. Markets, the Counting House, the Conservatory</td>\n</tr>\n<tr>\n<td><strong>The Harbour</strong></td>\n<td>Shipyards, foundries, ore wharves, warehouses. The biggest works the order has</td>\n</tr>\n<tr>\n<td><strong>The Walls</strong></td>\n<td>Faith Militant. Barracks, sparring yards, armouries</td>\n</tr>\n</tbody>\n</table>\n<p>Cable lifts carry people up and down between the tiers, and a few railcar lines run along them, some raised on arcades through the middle tiers.</p>\n<p>Nobody warns you about the colour. Red bougainvillea spills out of windows and planters in long cascades down the white stone, and there are planted beds, vines and flowering terraces on practically every level. On top of that, every member of every Corps wears the colour of their profession, all day, everywhere.</p>\n<table>\n<thead>\n<tr>\n<th>Corps</th>\n<th>Robes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Deep Prussian blue, cut like long dusters</td>\n</tr>\n<tr>\n<td><strong>Engineer</strong></td>\n<td>Dark crimson, cut as overalls, leather at the joints</td>\n</tr>\n<tr>\n<td><strong>Scholarly</strong></td>\n<td>Deep charcoal grey, full length with wide sleeves</td>\n</tr>\n<tr>\n<td><strong>Natural</strong></td>\n<td>Earthy brown, hemmed at the knee for fieldwork</td>\n</tr>\n<tr>\n<td><strong>Agrarian</strong></td>\n<td>Harvest orange, short-hemmed, well-worn and patched</td>\n</tr>\n<tr>\n<td><strong>Arts</strong></td>\n<td>Deep plum, flowing, a little more dramatic</td>\n</tr>\n<tr>\n<td><strong>Civil</strong></td>\n<td>Warm ochre, formal, immaculately pressed</td>\n</tr>\n<tr>\n<td><strong>Faith Militant</strong></td>\n<td>Forest green, slim and military in cut</td>\n</tr>\n</tbody>\n</table>\n<p>Every one of them wears the long red scarf too. On a busy morning in the lower tiers the effect is genuinely startling.</p>\n<p>Worth saying plainly: this isn't a human organization. Humans are the largest single group in Sanguilum and nowhere near a majority of what you see. Dwarves, elves, halflings, gnomes, orcs, minotaur, tengu, ratfolk and hobgoblins are all unremarkable in the ranks, and so are peoples the rest of the world treats as something other than people. Anadi, ghoran, lizardfolk, kholo, azarketi. The order's spent generations treating the monstrous peoples of the middle continent as colleagues instead of a problem, and plenty of them have taken the scarf because of it. Nobody here comments on any of it, and anyone who does gets a politely blank look.</p>\n<p>One more thing. If your nature is magical, you've been carrying something since you woke that you probably haven't got words for. A low pressure in the air that wasn't there in Xandar. It doesn't hurt and it doesn't seem to be doing anything to you, and nobody's offered an explanation.</p>"},{"name":"Who Governs Sholtan","html":"<p>Nobody, cleanly. The borders here are the old kind. No lines on the ground, no standing army holding one, just a question of who the locals think is in charge. You can cross out of Beheaded influence without anything visibly changing.</p>\n<p><strong>The Beheaded</strong> govern the deep south outright. Sanguilum, Venoqual and Portovel Arterium are order cities, built by them and run by them and unambiguous about it. Cordevale is theirs too, though it doesn't feel that way on the ground. It reads more like a farmers' collective that happens to have Beheaded in it. Between those points the whole triangle is under their influence, and inside it they're quietly extending that influence into towns still nominally Imperial, mostly by being better at wells and grain than the alternative.</p>\n<p>The three cities do different work. <strong>Sanguilum</strong> is the capital and the industrial heart, where the ore lands and the ships and automatons get built. <strong>Venoqual</strong> is the noqual works. <strong>Portovel Arterium</strong> is the continent's front door, and that's about position rather than distance. It sits far enough up the coast that anyone landing there can be on a train to almost anywhere the same week.</p>\n<p><strong>The Empire</strong> holds everything else as loose vassals with wildly varying levels of real control, plus a few outright colonies including the areas around the small northern port.</p>\n<p><strong>The monstrous peoples</strong> of the middle continent hold their own territory under a treaty with the Empire. In practice they're subjugated, under-supported and living to a standard the Empire wouldn't accept for its own. They deal with the Beheaded far more readily than with the Empire, for the straightforward reason that the order treats them as people.</p>\n<p>The Empire's grip out here is weak for three reasons. Sholtan sits ten to fifteen thousand miles from its heartland across genuinely lethal ocean. Magic running loose in the world has made holding any territory much harder than it was a generation ago, and the Empire has more territory to hold than anyone. And it's pouring everything it has into the worst-affected parts of Xandar, relying on local leadership to keep Sholtan together until things calm down. Nothing suggests they will.</p>\n<p>Hold onto this one: the order is locally dominant but it isn't sovereign. It has no claim on you, no authority to detain you, and no interest in either. Everything it has here, it got by being useful.</p>"},{"name":"The Order, Briefly","html":"<p>The Beheaded aren't what most of the world says they are, and you've now got five months of first-hand evidence to that effect.</p>\n<p>Their central belief is that the mortal manipulation of magic is a slow poison that costs the world something every time it's used, and that the world has been quietly paying that cost for a very long time. There are other problems they have with magic, but that's the main one. Their answer is to do everything magic does, medicine and engineering and agriculture and defence, without it, and to try and do it better. They're extremely good at this. The technology in Sanguilum runs centuries ahead of anywhere else you've been and none of it is enchanted.</p>\n<p>Seven non-martial Corps plus the Faith Militant.</p>\n<table>\n<thead>\n<tr>\n<th>Corps</th>\n<th>What they do</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Medical</strong></td>\n<td>Physicians, surgeons, hospitals</td>\n</tr>\n<tr>\n<td><strong>Scholarly</strong></td>\n<td>Archives, research, languages, history</td>\n</tr>\n<tr>\n<td><strong>Engineer</strong></td>\n<td>Machines, rail, automatons, construction</td>\n</tr>\n<tr>\n<td><strong>Natural</strong></td>\n<td>Ecology, beasts, conservation</td>\n</tr>\n<tr>\n<td><strong>Agrarian</strong></td>\n<td>Farming, irrigation, food supply</td>\n</tr>\n<tr>\n<td><strong>Arts</strong></td>\n<td>Music, dance, performance, culture</td>\n</tr>\n<tr>\n<td><strong>Civil</strong></td>\n<td>Administration, law, records, banking</td>\n</tr>\n<tr>\n<td><strong>Faith Militant</strong></td>\n<td>Defence, monster hunting, the Watchline</td>\n</tr>\n</tbody>\n</table>\n<p>The <strong>Penitent</strong> sit outside all that. Elite, silent, and noticeably larger than they ought to be, armoured in Sovereign Steel with edicts worked across the plate and inked into the skin underneath. You've mostly seen them from a distance.</p>"},{"name":"The Rules for Guests","html":"<p>A Civil Corps officer went through all of this with each of you individually while you were recovering. In a chair, over tea, unhurried. You've been told, and the order knows you've been told.</p>\n<p><strong>Nothing gets confiscated.</strong> You keep your weapons and you keep your magic. The edicts bind members, not guests, and you're guests.</p>\n<p><strong>Weapons get declared and stay holstered, sheathed or cased.</strong> Meeting force with force is understood and permitted. Escalating past what was brought to you isn't.</p>\n<p><strong>You were asked what magic you can do</strong>, in general terms rather than as a spell list. On most magic their position is that they disapprove, they'd rather you didn't, and they won't stop you. Casting a spell in public gets you about the same look as walking around with a visible weapon. Noted and watched, not challenged.</p>\n<p>On one category their position is completely different.</p>\n<h3>The Named List</h3>\n<p>The order treats these as violent crimes, not doctrinal disagreements, and draws no distinction between the spell and a knife.</p>\n<table>\n<thead>\n<tr>\n<th>What</th>\n<th>Examples</th>\n<th>Charged as</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Taking control of a body or mind</td>\n<td><em>dominate</em>, <em>charm</em>, <em>command</em>, <em>suggestion</em>, <em>confusion</em></td>\n<td>Assault, and at the upper end enslavement</td>\n</tr>\n<tr>\n<td>Removing a sense or the ability to act</td>\n<td><em>blindness</em>, <em>deafness</em>, <em>paralyze</em>, <em>sleep</em>, <em>shroud of night</em></td>\n<td>Assault</td>\n</tr>\n<tr>\n<td>Reading or entering a mind uninvited</td>\n<td><em>mind reading</em> and similar</td>\n<td>Assault</td>\n</tr>\n<tr>\n<td>Wearing someone else's face to get something</td>\n<td>any illusion or transformation used that way</td>\n<td>Fraud, and if used to obtain intimacy, assault</td>\n</tr>\n</tbody>\n</table>\n<p>Self-defense is a real and accepted justification. If somebody draws a blade on you in an alley, blinding them is defensive and gets treated that way. Nobody expects you to die politely. What won't be accepted is any of the above used first, used casually, or used because somebody annoyed you.</p>\n<p>Their reasoning is simple and they'll say it to your face. A spell that takes somebody's will and walks them around is slavery, done in six seconds with a gesture, and the fact that it wears off in an hour doesn't change what it was. A fair number of Beheaded joined this order because somebody once did that to them. It's the one subject where an otherwise gracious and patient member of this order will lose their temper.</p>\n<h3>Shapechanging</h3>\n<p>Changing your own face is your own business. Wearing a stranger's face to steal something is a property crime like any other. Wearing a stranger's face to get something the real one wouldn't have been given is where it stops being a property crime.</p>"},{"name":"Etiquette","html":"<p>You're welcome here and it isn't grudging. Sholtan sits far enough from Xandar that events there haven't turned anyone against outsiders, and the order sheltered you for five months without asking for anything back.</p>\n<p>Expect consistent courtesy, including from people who disagree with you. Expect a lot of them to want to argue, though none of them will start it. Doctrine, ethics, medicine, history. The Scholarly Corps in particular will want to talk to you at length and none of it is hostile.</p>\n<p>Rank matters a great deal to the order internally, though it won't be enforced on guests. The long red scarf marks membership and every member of every Corps wears one.</p>"},{"name":"Where You Could Go","html":"<p>Everything below runs off the rail line out of Sanguilum.</p>\n<table>\n<thead>\n<tr>\n<th>Place</th>\n<th>What's there</th>\n<th>Travel time</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Venoqual</strong></td>\n<td>Mining town on the largest noqual deposit in the world. Fortified and heavily guarded</td>\n<td>2–4 days</td>\n</tr>\n<tr>\n<td><strong>Ottojikk</strong></td>\n<td>The junction. Merchants, the Wayhouse, and the room you came through</td>\n<td>4–7 days</td>\n</tr>\n<tr>\n<td><strong>Cordevale</strong></td>\n<td>Farming valley that feeds most of the south. Quiet</td>\n<td>5–8 days</td>\n</tr>\n<tr>\n<td><strong>Portovel Arterium</strong></td>\n<td>The continent's front door. Passengers, general trade, and every rumour out of Xandar</td>\n<td>6–11 days</td>\n</tr>\n<tr>\n<td><strong>Vigilsylva</strong></td>\n<td>Frontier fort against the northern forest, held jointly by the Beheaded, the Empire and the monstrous peoples</td>\n<td>10–16 days</td>\n</tr>\n</tbody>\n</table>\n<p>The trains are steam and entirely non-magical, and they run a lot longer between stops than they've any right to. Nobody's explained that either.</p>\n<p>Roughly half the continent to the north is rainforest and it's never been tamed. It's hot, wet and enormous. Most of what kills people in there isn't hunting them. Nothing dries, wounds go bad in a day and a half, fever is everywhere, and the insects are the single most dangerous thing anyone actually runs into. Under the canopy it's permanent green half-light, you can't see thirty feet, and a cut path closes over within days. Rivers are the only real roads.</p>\n<p>There are large things in there too. Trackers working the fringe report tracks and browse damage that match nothing anyone's catalogued, and the secondhand descriptions agree on very large and reptilian. Nobody's gone deep enough and come back to confirm it. Every big expedition ever sent in has failed, most without ever meeting anything hostile.</p>\n<p>The <strong>Watchline</strong> is a fortified boundary running some four thousand two hundred miles, separating the forest from everything south. It isn't a solid wall, long stretches are deliberately left open, and no single power holds it. The order supplies the designs and trains the officers, the Empire supplies materiel and garrisons, and the peoples living nearest the boundary supply most of the actual watchstanders. It's the one thing on this continent all three have agreed to do together.</p>"},{"name":"What You Can Buy","html":"<p>The order sells a lot to outsiders and all of it is non-magical. Medical kits, antiseptics, water filtration flasks, clockwork lanterns, precision compasses, weatherglasses, chemical test kits, preserved rations, hardy seed stock, writing kits, recording tablets, instruments and copied excerpts from the archives are all freely available.</p>\n<p>Medicated patches, rousing ampoules, tourniquet clamps and fever draughts come from the Medical Corps and work on anyone. Arc lamps, hand dynamos, grapnel launchers, listening horns, survey instruments, glare goggles, compression cases and good locks come from the Engineers. Lens cases and cipher wheels come from the Scholars. None of it's magical and all of it can be taken apart on a bench.</p>\n<p>There's newer stock too. The Medical Corps sells antitoxin, coagulant powder, a settling draught for the crossing, and a nerve tonic the Faith Militant buys by the crate. The Engineers sell magnetic jacks, hazard suits, spray atomisers, fittings for ordinary armour, and a line of small clockwork automatons that carry luggage, put out fires, fetch things and follow you around. The Medical Corps will also fit clockwork prosthetics, though that happens in a surgery rather than at a stall.</p>\n<p>Raw <strong>noqual</strong> is sold openly to anyone who can pay. Roughly 600 gp for a small parcel and 6,000 gp for a full measure.</p>\n<p>Plain muskets are the one exception on the military side, sold cheerfully and without fuss, along with powder, shot, and the smoke and flash devices the order shares with town watches. <strong>Sovereign Steel</strong>, the order's own firearms, combat automaton parts, darkvision optics, experimental elixirs, advanced surgical tools and anything else from the Faith Militant's arsenal aren't for sale at any price. Ask a merchant about that last category and they'll tell you politely that it isn't something the order sells, and won't elaborate. They aren't being evasive. A stallholder genuinely doesn't know more than that.</p>\n<p>That list is what the order won't <strong>sell</strong>. It isn't the same as what the order will never let you touch, and the difference is a question for a Director rather than a merchant.</p>"}];
const PRIVATE = [{"name":"Zacchaeus Bael: Your Notes","html":"<h2>The Short Version</h2>\n<p>You're guests, not prisoners. You keep your weapons and your magic. The one hard line is that you don't take anyone's mind or senses from them without cause. Everyone here will be kind to you and none of it is an act. Nothing anywhere else is getting better.</p>\n<h2>Your Notes</h2>\n<p>This is your city and you were raised in it. You can name any building on sight.</p>\n<p>Your adoptive father, <strong>Chair Nathaniel Bael</strong> of the Medical Corps, was at your bedside when you woke. He holds the Chair of Field Surgery and is well known across the order for it.</p>\n<p><strong>Director Phaedra Solenne</strong> runs the Corps. She's followed your career since you were a Ward and she's nearly impossible to impress.</p>\n<p>Your firearms get declared like anyone else's, and you'll do it without being asked.</p>\n<h2>Where You Are</h2>\n<p>You're on the southern end of Sholtan, the second largest continent in the world. Xandar's bigger, but not by as much as people think. Most of you have never set foot here before.</p>\n<p>You didn't travel here. Something moved you, physically, while you were unconscious, and left you at an inn in Xandar, one of the inns around the world that keep a door-circle. Somebody there put you through the door, and you came out the other side in a heap at the Wayhouse in Ottojikk. You'd all been there once before. Donkey didn't come through with you. Nobody asked and nobody explained the rest of it.</p>\n<p><strong>Hek isn't with you, and Hek isn't exactly Hek anymore.</strong> He became Keh, and you watched it happen. Whether that can be undone, or whether it's permanent, nobody knows. That includes everyone you've asked here.</p>\n<p>He didn't come through the door with you. Nobody on this continent has any record of him arriving at all. He hasn't been confirmed dead.</p>\n<p>You also don't know what got you from the fight to that inn in Xandar, or who put you through the door once you were there. The log in Ottojikk shows the six of you arriving from Xandar and nothing about who sent you. Keh is the obvious guess for the first part, and it's the one everybody made. Flips was awake for part of it and Gobbler came round for a moment at the inn. What either of them has chosen to tell you is up to them.</p>\n<p>And you don't know what Keh <em>is</em> now. Demigod, avatar, vessel, something nobody's got a word for. Nobody in Sanguilum has been able to tell you either.</p>\n<h3>The Timeline</h3>\n<table>\n<thead>\n<tr>\n<th>When</th>\n<th>What</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>The event</td>\n<td>Everyone goes down</td>\n</tr>\n<tr>\n<td>Right after</td>\n<td>Somebody at an inn in Xandar puts you through the door-circle. You come out in a heap at the Wayhouse in Ottojikk, and Donkey isn't with you</td>\n</tr>\n<tr>\n<td>First month</td>\n<td>Nursed there by local Beheaded, who decided you were too unstable to move south</td>\n</tr>\n<tr>\n<td>Next four months</td>\n<td>Moved to Sanguilum, treated in the Sanctum Medica, still unconscious</td>\n</tr>\n<tr>\n<td>Last few weeks</td>\n<td>Awake. Recovering separately, retraining, learning a world that changed while you were out</td>\n</tr>\n<tr>\n<td>Now</td>\n<td>Healthy, resupplied, welcome, and out of patience</td>\n</tr>\n</tbody>\n</table>\n<p>Five months unconscious. A few weeks awake. Several of you came out of it changed in ways that go past injury, with bodies and abilities that don't work the way they used to.</p>","character":"Zacchaeus Bael"},{"name":"Fern: Your Notes","html":"<h2>The Short Version</h2>\n<p>You're guests, not prisoners. You keep your weapons and your magic. The one hard line is that you don't take anyone's mind or senses from them without cause. Everyone here will be kind to you and none of it is an act. Nothing anywhere else is getting better.</p>\n<h2>Your Notes</h2>\n<p>The <strong>Grand Archive</strong> is open to you. History, natural science, magical theory, nearly all of it. Only design work held near the Codex is restricted.</p>\n<p><strong>Director Casiveth Null</strong> of the Scholarly Corps is the order's foremost expert on extraplanar civilizations and dead languages. He's a Fetchling, and he'll want to speak with you personally.</p>\n<p>You're a practising caster in a city that disapproves of casting and won't stop you. Expect to be argued with rather than obstructed, and expect them to wait for you to bring it up first.</p>\n<p>You were also, before all of this, a devoted worshipper of Desna. Where that stands now is your own business, but it's the sort of thing the Scholarly Corps will ask about, politely and with real curiosity, if it ever comes up.</p>\n<p>The pressure in the air here is much stronger than anything you felt in Xandar, and nobody's given you an explanation for it.</p>\n<h2>Where You Are</h2>\n<p>You're on the southern end of Sholtan, the second largest continent in the world. Xandar's bigger, but not by as much as people think. Most of you have never set foot here before.</p>\n<p>You didn't travel here. Something moved you, physically, while you were unconscious, and left you at an inn in Xandar, one of the inns around the world that keep a door-circle. Somebody there put you through the door, and you came out the other side in a heap at the Wayhouse in Ottojikk. You'd all been there once before. Donkey didn't come through with you. Nobody asked and nobody explained the rest of it.</p>\n<p><strong>Hek isn't with you, and Hek isn't exactly Hek anymore.</strong> He became Keh, and you watched it happen. Whether that can be undone, or whether it's permanent, nobody knows. That includes everyone you've asked here.</p>\n<p>He didn't come through the door with you. Nobody on this continent has any record of him arriving at all. He hasn't been confirmed dead.</p>\n<p>You also don't know what got you from the fight to that inn in Xandar, and this one has your name on it. Desna sent something through the tear Keh opened. She spoke to Flips, because Flips was the only one still standing, and what she sent word of was you. <em>She will always be welcomed.</em> Whether Flips has told you that yet is her business. Everyone else settled on Keh, because Keh is the obvious guess.</p>\n<p>And you don't know what Keh <em>is</em> now. Demigod, avatar, vessel, something nobody's got a word for. Nobody in Sanguilum has been able to tell you either.</p>\n<h3>The Timeline</h3>\n<table>\n<thead>\n<tr>\n<th>When</th>\n<th>What</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>The event</td>\n<td>Everyone goes down</td>\n</tr>\n<tr>\n<td>Right after</td>\n<td>Somebody at an inn in Xandar puts you through the door-circle. You come out in a heap at the Wayhouse in Ottojikk, and Donkey isn't with you</td>\n</tr>\n<tr>\n<td>First month</td>\n<td>Nursed there by local Beheaded, who decided you were too unstable to move south</td>\n</tr>\n<tr>\n<td>Next four months</td>\n<td>Moved to Sanguilum, treated in the Sanctum Medica, still unconscious</td>\n</tr>\n<tr>\n<td>Last few weeks</td>\n<td>Awake. Recovering separately, retraining, learning a world that changed while you were out</td>\n</tr>\n<tr>\n<td>Now</td>\n<td>Healthy, resupplied, welcome, and out of patience</td>\n</tr>\n</tbody>\n</table>\n<p>Five months unconscious. A few weeks awake. Several of you came out of it changed in ways that go past injury, with bodies and abilities that don't work the way they used to.</p>","character":"Fern"},{"name":"Elemir: Your Notes","html":"<h2>The Short Version</h2>\n<p>You're guests, not prisoners. You keep your weapons and your magic. The one hard line is that you don't take anyone's mind or senses from them without cause. Everyone here will be kind to you and none of it is an act. Nothing anywhere else is getting better.</p>\n<h2>Your Notes</h2>\n<p>Your tattoos are invisible. They're ghost ink and they only surface when heat gets put to them, which for you means any time you use your fire, and for anyone else carrying your work means standing close to a bonfire or a hearth. Day to day you present as unmarked and the order has no particular reason to look twice at you.</p>\n<p>That's worth understanding as a choice rather than a relief. Nothing would be confiscated if they were visible, since guests aren't bound by the edicts. But you're the only person in the party carrying obvious magic who can simply decline to show it.</p>\n<p><strong>Knight Lieutenant Torvis Amsel</strong> runs the Faith Militant's unarmed curriculum. Nagaji, 124 years old, venerable by the standards of his people, and one of the very few in Sanguilum who could hold his own against you.</p>\n<p>The order keeps archives and employs trackers, and if you want to look for Keh, nobody here will tell you no. Be aware of the limit though. Their reach is real in southern Sholtan and almost nothing in Xandar, where their chain of command fell apart and everything they learn now arrives weeks late on a ship. If Keh is on this continent they can help you find him. If he isn't, what they can offer you is whatever comes off the docks at Portovel Arterium.</p>\n<h2>Where You Are</h2>\n<p>You're on the southern end of Sholtan, the second largest continent in the world. Xandar's bigger, but not by as much as people think. Most of you have never set foot here before.</p>\n<p>You didn't travel here. Something moved you, physically, while you were unconscious, and left you at an inn in Xandar, one of the inns around the world that keep a door-circle. Somebody there put you through the door, and you came out the other side in a heap at the Wayhouse in Ottojikk. You'd all been there once before. Donkey didn't come through with you. Nobody asked and nobody explained the rest of it.</p>\n<p><strong>Hek isn't with you, and Hek isn't exactly Hek anymore.</strong> He became Keh, and you watched it happen. Whether that can be undone, or whether it's permanent, nobody knows. That includes everyone you've asked here.</p>\n<p>He didn't come through the door with you. Nobody on this continent has any record of him arriving at all. He hasn't been confirmed dead.</p>\n<p>You also don't know what got you from the fight to that inn in Xandar, or who put you through the door once you were there. The log in Ottojikk shows the six of you arriving from Xandar and nothing about who sent you. Keh is the obvious guess for the first part, and it's the one everybody made. Flips was awake for part of it and Gobbler came round for a moment at the inn. What either of them has chosen to tell you is up to them.</p>\n<p>And you don't know what Keh <em>is</em> now. Demigod, avatar, vessel, something nobody's got a word for. Nobody in Sanguilum has been able to tell you either.</p>\n<h3>The Timeline</h3>\n<table>\n<thead>\n<tr>\n<th>When</th>\n<th>What</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>The event</td>\n<td>Everyone goes down</td>\n</tr>\n<tr>\n<td>Right after</td>\n<td>Somebody at an inn in Xandar puts you through the door-circle. You come out in a heap at the Wayhouse in Ottojikk, and Donkey isn't with you</td>\n</tr>\n<tr>\n<td>First month</td>\n<td>Nursed there by local Beheaded, who decided you were too unstable to move south</td>\n</tr>\n<tr>\n<td>Next four months</td>\n<td>Moved to Sanguilum, treated in the Sanctum Medica, still unconscious</td>\n</tr>\n<tr>\n<td>Last few weeks</td>\n<td>Awake. Recovering separately, retraining, learning a world that changed while you were out</td>\n</tr>\n<tr>\n<td>Now</td>\n<td>Healthy, resupplied, welcome, and out of patience</td>\n</tr>\n</tbody>\n</table>\n<p>Five months unconscious. A few weeks awake. Several of you came out of it changed in ways that go past injury, with bodies and abilities that don't work the way they used to.</p>","character":"Elemir"},{"name":"Pipsy Morningstone: Your Notes","html":"<h2>The Short Version</h2>\n<p>You're guests, not prisoners. You keep your weapons and your magic. The one hard line is that you don't take anyone's mind or senses from them without cause. Everyone here will be kind to you and none of it is an act. Nothing anywhere else is getting better.</p>\n<h2>Your Notes</h2>\n<p>Two separate things are true about you here and the order treats them very differently.</p>\n<p>Your fey ancestry isn't held against you. Their own written doctrine tells members not to fear those born to magic, whether beast or sentient, and you didn't choose what you were born as. That part is genuinely fine.</p>\n<p>Everything you've learned since is another matter. You're a trained druid who has studied and practised and grown your craft well past anything your blood handed you, and that's precisely the mortal use of magic the order objects to. Expect the same treatment Fern gets. Disapproval, argument, and no attempt whatsoever to stop you. Nobody will raise it unless you do.</p>\n<p><strong>Director Sable Ironmark</strong> runs the Natural Corps. She's a leshy, born of natural magic and native to this plane, and there's nothing awkward about that as far as the order is concerned. The edicts object to mortals reaching for magic and using it. They say nothing against things magic made. Sable is the doctrine working exactly as written, and she'll say so flatly if anyone suggests otherwise. She's spent a career on the line between what a person is and what a person does, and she's very good at explaining where that line sits.</p>\n<p>The <strong>Verdant Conservatory</strong> she oversees is a working greenhouse, laboratory and menagerie. You'll like it a great deal.</p>\n<p>Your moonlit seed has been behaving strangely since you got here.</p>\n<p>The <strong>Counting House</strong> in the lower tiers will convert or hold your coin, which is worth doing, since you're carrying an absurd amount of it.</p>\n<h2>Where You Are</h2>\n<p>You're on the southern end of Sholtan, the second largest continent in the world. Xandar's bigger, but not by as much as people think. Most of you have never set foot here before.</p>\n<p>You didn't travel here. Something moved you, physically, while you were unconscious, and left you at an inn in Xandar, one of the inns around the world that keep a door-circle. Somebody there put you through the door, and you came out the other side in a heap at the Wayhouse in Ottojikk. You'd all been there once before. Donkey didn't come through with you. Nobody asked and nobody explained the rest of it.</p>\n<p><strong>Hek isn't with you, and Hek isn't exactly Hek anymore.</strong> He became Keh, and you watched it happen. Whether that can be undone, or whether it's permanent, nobody knows. That includes everyone you've asked here.</p>\n<p>He didn't come through the door with you. Nobody on this continent has any record of him arriving at all. He hasn't been confirmed dead.</p>\n<p>You also don't know what got you from the fight to that inn in Xandar, or who put you through the door once you were there. The log in Ottojikk shows the six of you arriving from Xandar and nothing about who sent you. Keh is the obvious guess for the first part, and it's the one everybody made. Flips was awake for part of it and Gobbler came round for a moment at the inn. What either of them has chosen to tell you is up to them.</p>\n<p>And you don't know what Keh <em>is</em> now. Demigod, avatar, vessel, something nobody's got a word for. Nobody in Sanguilum has been able to tell you either.</p>\n<h3>The Timeline</h3>\n<table>\n<thead>\n<tr>\n<th>When</th>\n<th>What</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>The event</td>\n<td>Everyone goes down</td>\n</tr>\n<tr>\n<td>Right after</td>\n<td>Somebody at an inn in Xandar puts you through the door-circle. You come out in a heap at the Wayhouse in Ottojikk, and Donkey isn't with you</td>\n</tr>\n<tr>\n<td>First month</td>\n<td>Nursed there by local Beheaded, who decided you were too unstable to move south</td>\n</tr>\n<tr>\n<td>Next four months</td>\n<td>Moved to Sanguilum, treated in the Sanctum Medica, still unconscious</td>\n</tr>\n<tr>\n<td>Last few weeks</td>\n<td>Awake. Recovering separately, retraining, learning a world that changed while you were out</td>\n</tr>\n<tr>\n<td>Now</td>\n<td>Healthy, resupplied, welcome, and out of patience</td>\n</tr>\n</tbody>\n</table>\n<p>Five months unconscious. A few weeks awake. Several of you came out of it changed in ways that go past injury, with bodies and abilities that don't work the way they used to.</p>","character":"Pipsy Morningstone"},{"name":"Gobbler: Your Notes","html":"<h2>The Short Version</h2>\n<p>You're guests, not prisoners. You keep your weapons and your magic. The one hard line is that you don't take anyone's mind or senses from them without cause. Everyone here will be kind to you and none of it is an act. Nothing anywhere else is getting better.</p>\n<h2>Your Notes</h2>\n<p>You keep a god, in the headquarters of an order built on rejecting divine bargains. You've never made much of it out loud and nobody here is going to press you on it. Their doctrine calls for patience toward exactly this and most of them manage it without effort.</p>\n<p><strong>Knight Paladin Sera Dunmore</strong> runs the order's hunters and is the best of them, and the youngest Knight Paladin in living memory. She'll recognize what you are within about a minute of watching you work.</p>\n<p>Kitty is welcome. The order doesn't turn away a working animal.</p>\n<h2>Where You Are</h2>\n<p>You're on the southern end of Sholtan, the second largest continent in the world. Xandar's bigger, but not by as much as people think. Most of you have never set foot here before.</p>\n<p>You didn't travel here. Donkey carried you. Something came through the tear Keh opened and went into him, and he took all of you away with the last of what his body had in it, as far as an inn in Xandar. You came out the other side of that inn's door-circle at the Wayhouse in Ottojikk, a town you'd all been to once before.</p>\n<p><strong>Hek isn't with you, and Hek isn't exactly Hek anymore.</strong> He became Keh, and you watched it happen. Whether that can be undone, or whether it's permanent, nobody knows. That includes everyone you've asked here.</p>\n<p>He didn't come through the door with you. Nobody on this continent has any record of him arriving at all. He hasn't been confirmed dead.</p>\n<p><strong>You saw him after.</strong> You came round for a moment, afraid, while a man at that inn was carrying the lot of you into the door room, and Donkey was standing beyond the door beside him. Donkey lowered his head, he glowed, and he faded as the door shut. You haven't stopped feeling him since. He didn't leave you. Nobody else saw it. Flips was awake for the front half and heard something of her own. The rest of them think Keh moved you, because Keh is the obvious guess.</p>\n<p>And you don't know what Keh <em>is</em> now. Demigod, avatar, vessel, something nobody's got a word for. Nobody in Sanguilum has been able to tell you either.</p>\n<h3>The Timeline</h3>\n<table>\n<thead>\n<tr>\n<th>When</th>\n<th>What</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>The event</td>\n<td>Everyone goes down</td>\n</tr>\n<tr>\n<td>Right after</td>\n<td>Donkey carries you all off the field and spends himself doing it. A man at an inn in Xandar puts you through the door-circle, and you come out at the Wayhouse in Ottojikk</td>\n</tr>\n<tr>\n<td>First month</td>\n<td>Nursed there by local Beheaded, who decided you were too unstable to move south</td>\n</tr>\n<tr>\n<td>Next four months</td>\n<td>Moved to Sanguilum, treated in the Sanctum Medica, still unconscious</td>\n</tr>\n<tr>\n<td>Last few weeks</td>\n<td>Awake. Recovering separately, retraining, learning a world that changed while you were out</td>\n</tr>\n<tr>\n<td>Now</td>\n<td>Healthy, resupplied, welcome, and out of patience</td>\n</tr>\n</tbody>\n</table>\n<p>Five months unconscious. A few weeks awake. Several of you came out of it changed in ways that go past injury, with bodies and abilities that don't work the way they used to.</p>","character":"Gobbler"},{"name":"Flips Niko: Your Notes","html":"<h2>The Short Version</h2>\n<p>You're guests, not prisoners. You keep your weapons and your magic. The one hard line is that you don't take anyone's mind or senses from them without cause. Everyone here will be kind to you and none of it is an act. Nothing anywhere else is getting better.</p>\n<h2>Your Notes</h2>\n<p>You were asked at intake what you can turn into and you answered. That's the end of the matter as long as you don't use it to deceive anyone. Nobody has an issue with what you are and nobody has raised it since.</p>\n<p>Your false priest form isn't illegal. Wearing a scarf you didn't earn is rude, and members who gave years to this order will take it as an insult, but the order doesn't make mockery a crime and says so openly. It becomes fraud the moment you use it to get into a room, past a door, or to walk off with something the real thing would've been handed and you wouldn't. Nobody's raised it. Nobody's forgotten it either.</p>\n<p>The <strong>Grand Archive</strong> holds the order's collected record of the world's peoples and it's open to you. If there are records of other tanuki anywhere on this continent, they're in that building, and asking costs nothing. They keep records and they'll help you look.</p>\n<p><strong>Instructor Callo Verrienne</strong> runs the dance program at the Round. She'll want to learn everything you know within about thirty seconds of watching you move.</p>\n<h2>Where You Are</h2>\n<p>You're on the southern end of Sholtan, the second largest continent in the world. Xandar's bigger, but not by as much as people think. Most of you have never set foot here before.</p>\n<p>You didn't travel here. You were the only one who made the save, so you're the only one who watched it happen. Something came through the tear Keh opened, went into Donkey, and Donkey carried all of you away. You went under again before he set you down. What you've been told since is that somebody at an inn in Xandar put the six of you through the door-circle, and that you came out in a heap at the Wayhouse in Ottojikk. You'd all been there once before.</p>\n<p><strong>Hek isn't with you, and Hek isn't exactly Hek anymore.</strong> He became Keh, and you watched it happen. Whether that can be undone, or whether it's permanent, nobody knows. That includes everyone you've asked here.</p>\n<p>He didn't come through the door with you. Nobody on this continent has any record of him arriving at all. He hasn't been confirmed dead.</p>\n<p><strong>Desna spoke to you.</strong> She said it was the last time she'd be able to save you, and she asked you to tell Fern that she will always be welcomed. Nobody else heard it. Donkey didn't come through the door with you, and Keh is the guess everyone reached for. You know it's wrong. How much of that you've passed on, and to who, is yours.</p>\n<p>And you don't know what Keh <em>is</em> now. Demigod, avatar, vessel, something nobody's got a word for. Nobody in Sanguilum has been able to tell you either.</p>\n<h3>The Timeline</h3>\n<table>\n<thead>\n<tr>\n<th>When</th>\n<th>What</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>The event</td>\n<td>Everyone goes down</td>\n</tr>\n<tr>\n<td>Right after</td>\n<td>Donkey carries you off the field. Somebody at an inn in Xandar puts you through the door-circle, and you come out at the Wayhouse in Ottojikk. He doesn't come with you</td>\n</tr>\n<tr>\n<td>First month</td>\n<td>Nursed there by local Beheaded, who decided you were too unstable to move south</td>\n</tr>\n<tr>\n<td>Next four months</td>\n<td>Moved to Sanguilum, treated in the Sanctum Medica, still unconscious</td>\n</tr>\n<tr>\n<td>Last few weeks</td>\n<td>Awake. Recovering separately, retraining, learning a world that changed while you were out</td>\n</tr>\n<tr>\n<td>Now</td>\n<td>Healthy, resupplied, welcome, and out of patience</td>\n</tr>\n</tbody>\n</table>\n<p>Five months unconscious. A few weeks awake. Several of you came out of it changed in ways that go past injury, with bodies and abilities that don't work the way they used to.</p>","character":"\"Flips\" Niko"}];

let folder = game.folders.find((f) => f.name === FOLDER && f.type === "JournalEntry");
if (!folder) folder = await Folder.create({ name: FOLDER, type: "JournalEntry" });

const players = game.users.filter((u) => !u.isGM);
const findUser = (character) => {
  const explicit = NAME_TO_USER[character] ?? NAME_TO_USER[character.replace(/"/g, "")];
  if (explicit) { const u = players.find((p) => p.name === explicit); if (u) return u; }
  const clean = character.replace(/"/g, "");
  const actor = game.actors.find((a) => a.type === "character" && (a.name === character || a.name === clean || a.name.includes(clean.split(" ").pop())));
  if (actor) { const owner = players.find((p) => actor.testUserPermission(p, "OWNER")); if (owner) return owner; }
  const assigned = players.find((p) => p.character && (p.character.name === character || p.character.name.includes(clean.split(" ").pop())));
  if (assigned) return assigned;
  return players.find((p) => {
    const n = p.name.toLowerCase(), c = clean.toLowerCase();
    return n === c || c.startsWith(n) || n.startsWith(c.split(" ")[0]);
  }) ?? null;
};

const page = (p, sort, ownership) => ({
  name: p.name, type: "text", sort,
  title: { show: true, level: 1 },
  text: { format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML, content: p.html },
  ...(ownership ? { ownership } : {}),
});

const owned = [...DM.map((e) => e.name), PLAYER_JOURNAL];
if (REBUILD) {
  const old = game.journal.filter((j) => owned.includes(j.name) && j.folder?.id === folder.id);
  if (old.length) await JournalEntry.deleteDocuments(old.map((j) => j.id));
}
const have = (name) => game.journal.find((j) => j.name === name && j.folder?.id === folder.id);

let made = 0;
for (const [i, e] of DM.entries()) {
  if (have(e.name)) continue;
  await JournalEntry.create({
    name: e.name, folder: folder.id, sort: (i + 1) * 100,
    ownership: { default: OWN.NONE },
    pages: e.pages.map((p, j) => page(p, (j + 1) * 100)),
  });
  made++;
}

const unmatched = [];
if (!have(PLAYER_JOURNAL)) {
  const pages = SHARED.map((p, j) => page(p, (j + 1) * 100));
  PRIVATE.forEach((p, j) => {
    const user = findUser(p.character);
    if (!user) unmatched.push(p.character);
    const ownership = { default: OWN.NONE, ...(user ? { [user.id]: OWN.OBSERVER } : {}) };
    pages.push(page(p, (SHARED.length + j + 1) * 100, ownership));
  });
  await JournalEntry.create({
    name: PLAYER_JOURNAL, folder: folder.id, sort: (DM.length + 1) * 100,
    ownership: { default: OWN.OBSERVER }, pages,
  });
  made++;
}

ui.notifications.info(`Sholtan journals: ${made} entr${made === 1 ? "y" : "ies"} created` +
  (unmatched.length ? `. ${unmatched.length} private page(s) left GM-only: ${unmatched.join(", ")}. Fill NAME_TO_USER and rebuild.` : "."));
if (unmatched.length) console.warn("Sholtan journals | unmatched characters:", unmatched);
